  const pitchYieldHTML = opts.showPitchYield
    ? `<div class="pitch-yield-preview" title="What discarding this card into the graveyard would grant right now">🗑 Discard for ${pitchYieldPreviewHTML(defId)}</div>`
    : '';
  // 2026-09-20, per explicit request ("Hover preview of the cards in codex should show you the
