  // The Wait clock keeps its plain "⏳ 5".
  if(n > 4) return `<span class="pips pips-${kind} is-num${kind === 'wait' ? '' : ' is-res-num'}" data-n="${n}" aria-label="${n}"><i>${glyph}</i><b>${n}</b></span>`;
