  if(!c.archetypes || !c.archetypes.length) c.archetypes = ['Misc'];
  delete c.archetype; // superseded by the plural archetypes[] field going forward
  delete c.type; // retired (2026-09-18) — Structure is now just a Type Tags pill, see isStructure()
  // 2026-09-27, item 8: the checkbox IS c.locked directly now (see the field markup above) —
  // no more !checked inversion.
