// Snapshot every source ONCE per render/claim, not once per def — 13 achievements would
// otherwise mean 13 redundant localStorage reads + getCardDefs() rebuilds every time this panel
// draws. Mirrors renderPlayerStatsSubpage's own clearedNodes/mapsFullyCleared computation
// exactly (including the tutorial-marker-node exclusion) so the two panels can never disagree
// about what "5 nodes cleared" means.
// "New achievement" on the results screen (2026-10-11): achievements that became ready to claim since you last looked.
// Remembered per browser, so each one is announced once.
const ACHV_ANNOUNCED_KEY = 'bramblewood_achv_announced_v1';
function newAchievementsChipHTML(m){
  try{
    if(!m || !m.over) return '';
    if(m.mode==='tutorial') return ''; // 2026-10-12: a tutorial result never carries the account's achievement news
    if(!m.newAchv){
      let seen; try{ seen = new Set(JSON.parse(localStorage.getItem(ACHV_ANNOUNCED_KEY) || '[]')); }catch(e){ seen = new Set(); }
      const ctx = achievementContext();
      const ready = ACHIEVEMENT_DEFS.filter(d=> achievementStatus(d, ctx).claimable);
      m.newAchv = ready.filter(d=> !seen.has(d.id));
      ready.forEach(d=> seen.add(d.id)); try{ localStorage.setItem(ACHV_ANNOUNCED_KEY, JSON.stringify([...seen])); }catch(e){}
    }
    if(!m.newAchv.length) return '';
    const names = m.newAchv.slice(0, 2).map(d=> (d.icon ? d.icon + " " : "") + escapeHtml(d.title || d.id)).join(', ') + (m.newAchv.length > 2 ? ` +${m.newAchv.length - 2}` : '');
    return `<div class="winloss-achv" role="status"><span class="wa-ico">🏆</span><span><b>${m.newAchv.length === 1 ? _t('New achievement') : _t('New achievements')}</b> ${names}</span></div>`; // 2026-10-14 (user: "'Claim it on the achievement board...' -> dont need to say this")
  }catch(e){ return ''; }
}
// A fight you have actually won (see the clearedAt note in achievementContext).
function conquestNodeBeaten(progress, mapId, key){ const id = conquestNodeId(mapId, key); return !!(progress && progress.clearedAt && progress.clearedAt[id] && (progress.completed||[]).includes(id)); }
function achievementContext(){
  const s = loadMatchStats();
  const progress = ensureTutorialMarkersComplete(loadConquestProgress());
  const tutorialIds = CONQUEST_MAPS.flatMap(m=> m.nodes.filter(n=>n.kind==='tutorial').map(n=> conquestNodeId(m.id, n.key)));
  const clearedNodes = progress.completed.filter(id=> !tutorialIds.includes(id)).length;
  const mapsFullyCleared = CONQUEST_MAPS.filter(m=> m.nodes.some(n=> n.kind!=='tutorial') && m.nodes.filter(n=>n.kind!=='tutorial').every(n=> progress.completed.includes(conquestNodeId(m.id, n.key)))).length; // 2026-10-12: a map with no fights isn't "cleared"
  const defs = getCardDefs();
  const ownedCards = Object.values(defs).filter(c=>!c.test && !c.locked).length;
  const leveledCards = Object.keys(myCardLevels).filter(id=> (myCardLevels[id]||0)>0 && defs[id] && !defs[id].test).length;
  return {
    wins: s.wins, bestWinStreak: s.bestWinStreak,
    ownedCards, leveledCards,
    clearedNodes, mapsFullyCleared,
    raidBossesUnlocked: progress.raidUnlocked.length,
    // 2026-10-14 (user: "Wyrmslayer should only be achieved when I defeat the Caldera wyrm! Not just from seeing it."):
    // progress.completed is also filled by things that are not a win (the 11-wb carry-over that ticks the whole Volcano
    // Lair, the admin "clear map" / "jump to" tools, the reset-to-Map-N job). progress.clearedAt is only written by
    // completeConquestNode, i.e. by actually winning that fight, so the "defeat / clear this boss" achievements read it.
    roadDone: conquestNodeBeaten(progress, 'm11', '20-10') ? 1 : 0,
    eyeDone: conquestNodeBeaten(progress, 'me', '20-A-4') ? 1 : 0,
    worldBoss: conquestNodeBeaten(progress, 'mx', '20-B-4') ? 1 : 0,
  };
}
function loadClaimedAchievements(){
  try{ const raw = localStorage.getItem('bramblewood_arena_achievements'); if(raw){ const arr = JSON.parse(raw); if(Array.isArray(arr)) return new Set(arr); } }catch(e){}
  return new Set();
}
let myClaimedAchievements = loadClaimedAchievements();
function saveClaimedAchievements(){ try{ localStorage.setItem('bramblewood_arena_achievements', JSON.stringify(Array.from(myClaimedAchievements))); }catch(e){} }
function achievementStatus(def, ctx){
  const current = Math.min(def.target, def.progress(ctx));
  const complete = current >= def.target;
  const claimed = myClaimedAchievements.has(def.id);
  return {current, complete, claimed, claimable: complete && !claimed};
}
// The one entry point the Claim button below calls. Re-derives completion from live data rather
// than trusting the DOM/caller, so a stale render (or a hand-crafted call) can never grant a
// reward for an achievement that isn't actually met yet, and the myClaimedAchievements guard
// makes a double-click (or a second call after the Set already has this id) a genuine no-op
// rather than a double payout.
function claimAchievement(id){
  const def = ACHIEVEMENT_DEFS.find(a=>a.id===id);
  if(!def) return false;
  const ctx = achievementContext();
  const {complete, claimed} = achievementStatus(def, ctx);
  if(!complete || claimed) return false;
  Object.keys(def.reward).forEach(kind=> grantCurrency(kind, def.reward[kind]));
  myClaimedAchievements.add(id);
  saveClaimedAchievements();
  return true;
}
function achievementRewardChipsHTML(reward){
  return Object.keys(reward).map(kind=>{
    const meta = CURRENCY_META[kind]; if(!meta) return '';
    return `<span class="hud-pill forge-cur-${kind}">${meta.glyph} +${reward[kind]}</span>`;
  }).join('');
}
const ACHV_CATS = [['battle','⚔️','Battles'], ['road','🗺️','The road'], ['boss','👑','Bosses and raids'], ['collection','🗂️','Collection'], ['forge','🔨','The Forge']];
const ACHV_TIER = {1:'Bronze', 2:'Silver', 3:'Gold', 4:'Dragon'};
let achvFilter = 'all';
function achievementsPanelHTML(){
  const ctx = achievementContext();
  const rows = ACHIEVEMENT_DEFS.map(def=> ({def, st: achievementStatus(def, ctx)}));
  const claimed = rows.filter(r=> r.st.claimed).length, ready = rows.filter(r=> r.st.claimable).length, total = rows.length;
  const pct = Math.round(claimed / Math.max(1, total) * 100);
  const show = r=> achvFilter === 'all' || (achvFilter === 'ready' && r.st.claimable) || (achvFilter === 'open' && !r.st.complete) || (achvFilter === 'done' && r.st.claimed);
  const tile = ({def, st})=>{ const p = Math.round((st.current/def.target)*100), tier = def.tier || 1;
    const state = st.claimed ? 'is-claimed' : st.claimable ? 'is-ready' : st.current > 0 ? 'is-going' : 'is-locked';
    return `<article class="achv-tile ${state} tier-${tier}" aria-label="${escapeAttr(def.title)}: ${st.claimed ? 'claimed' : st.claimable ? 'ready to claim' : st.current + ' of ' + def.target}">
      <div class="achv-medal" title="${ACHV_TIER[tier] || ''} medal"><span>${def.icon}</span>${st.claimed ? '<i class="achv-stamp" aria-hidden="true">✓</i>' : ''}</div>
      <div class="achv-body"><b class="achv-title">${escapeHtml(def.title)}</b><p class="achv-desc">${escapeHtml(def.desc)}</p>
        ${st.claimed ? '' : `<div class="achv-meter"><div class="achv-bar" role="progressbar" aria-valuemin="0" aria-valuemax="${def.target}" aria-valuenow="${st.current}"><i style="width:${p}%"></i></div><small class="achv-progress">${st.current} / ${def.target}</small></div>`}
        <div class="achv-foot"><div class="achv-reward-preview">${achievementRewardChipsHTML(def.reward)}</div>${st.claimed ? `<span class="achv-claimed-badge">Claimed</span>` : st.claimable ? `<button class="btn primary small achv-claim-btn" data-achv="${def.id}">🎁 Claim</button>` : ''}</div></div>
    </article>`; };
  const groups = ACHV_CATS.map(([k, ico, name])=>{ const rs = rows.filter(r=> (r.def.cat || 'battle') === k), vis = rs.filter(show); if(!vis.length) return '';
    return `<section class="achv-group"><h3>${ico} ${escapeHtml(name)} <small>${rs.filter(r=> r.st.claimed).length}/${rs.length}</small></h3><div class="achv-grid">${vis.map(tile).join('')}</div></section>`; }).join('');
  const f = (k, label, n)=> `<button type="button" class="achv-f${achvFilter === k ? ' is-on' : ''}" data-achv-filter="${k}" aria-pressed="${achvFilter === k}">${label}${n != null ? ` <small>${n}</small>` : ''}</button>`;
  return `<div class="panel achievements-panel">
    <header class="achv-head">
      <div class="achv-ring" style="--p:${pct}" aria-hidden="true"><span><b>${claimed}</b><small>of ${total}</small></span></div>
      <div class="achv-head-txt"><h2>🏆 Achievements</h2><p class="panel-sub">${claimed} of ${total} claimed${ready ? ` · <b>${ready} ready to claim</b>` : ''}</p></div>
      ${ready > 1 ? `<button type="button" class="btn primary achv-claim-all" id="achvClaimAll">🎁 Claim all ${ready}</button>` : ''}
    </header>
    <div class="achv-filters" role="group" aria-label="Show">${f('all', 'All', total)}${f('ready', 'Ready', ready)}${f('open', 'In progress', rows.filter(r=> !r.st.complete).length)}${f('done', 'Claimed', claimed)}</div>
    ${groups || '<p class="panel-sub achv-empty">Nothing here yet.</p>'}
  </div>`;
}
function wireAchievementsPanel(){
  const redraw = ()=>{ const panel = document.querySelector('.achievements-panel'); if(panel) panel.outerHTML = achievementsPanelHTML(); try{ if(window.renderTopbar) renderTopbar(); }catch(e){} wireAchievementsPanel(); };
  document.querySelectorAll('[data-achv-filter]').forEach(b=> b.onclick = ()=>{ achvFilter = b.dataset.achvFilter; redraw(); });
  { const all = document.getElementById('achvClaimAll'); if(all) all.onclick = ()=>{ let n = 0; const sum = {}; ACHIEVEMENT_DEFS.forEach(d=>{ if(claimAchievement(d.id)){ n++; Object.entries(d.reward||{}).forEach(([k, v])=> sum[k] = (sum[k]||0) + v); } }); if(!n) return; rewardRush(all.getBoundingClientRect(), sum, {big:true}); showToast(TX('toast.claimed-achievements', {n}), 'ok'); redraw(); }; }
  document.querySelectorAll('.achv-claim-btn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const id = btn.getAttribute('data-achv');
      if(!claimAchievement(id)) return; // already claimed / not actually complete — silent no-op
      SoundKit.buffUp();
      // Small celebratory flourish reusing the existing star-fall system (same one Forge level-
      // ups and match wins already use) — celebrate() reads its own originEl.getBoundingClientRect()
      // internally (see starFallCelebration), so this passes the button itself, not a point.
      { const def = ACHIEVEMENT_DEFS.find(a=> a.id===id); rewardRush(btn.getBoundingClientRect(), def ? def.reward : {}); }
      const panel = document.querySelector('.achievements-panel');
      if(panel) panel.outerHTML = achievementsPanelHTML();
      try{ if(window.renderTopbar) renderTopbar(); }catch(e){}
      wireAchievementsPanel();
    });
  });
}
