// Inline deck rename (2026-10-07, user: "Clicking 'Deck' in the deck editor should let me edit the
// deck's name"): the name turns into a text box in place. Enter or clicking away saves, Escape cancels.
function startDeckRename(el, deckId, after){
  const d = (myDecks||[]).find(x=> x.id===deckId); if(!el || !d || el.querySelector('input')) return;
  const inp = document.createElement('input'); inp.type = 'text'; inp.className = 'deck-rename-input'; inp.value = d.name; inp.maxLength = 40;
  inp.setAttribute('aria-label', 'Deck name');
  el.replaceChildren(inp); inp.focus(); inp.select();
  let done = false;
  const finish = save=>{ if(done) return; done = true; if(save && inp.value.trim() && inp.value.trim() !== d.name){ renameDeck(deckId, inp.value); try{ showToast(TX('toast.deck-renamed')); }catch(e){} } (after || renderDeckSection)(); };
  inp.addEventListener('keydown', e=>{ if(e.key==='Enter'){ e.preventDefault(); finish(true); } else if(e.key==='Escape'){ e.preventDefault(); finish(false); } e.stopPropagation(); });
  inp.addEventListener('blur', ()=> finish(true));
  inp.addEventListener('click', e=> e.stopPropagation());
}
function wireDeckTop(){
  document.querySelectorAll('#deckHeroBanner [data-loadout]').forEach(b=> b.addEventListener('click', ()=> openLoadoutPicker(b.dataset.loadout)));
  const nm = document.querySelector('#deckHeroBanner [data-rename-deck]');
  if(nm){ nm.addEventListener('click', ()=> startDeckRename(nm, nm.dataset.renameDeck));
    nm.addEventListener('keydown', e=>{ if((e.key==='Enter' || e.key===' ') && !nm.querySelector('input')){ e.preventDefault(); startDeckRename(nm, nm.dataset.renameDeck); } }); }
}
// Castle / Leader picker (2026-10-05, user: "I should be able to select castle and leader by
// clicking into them, opening a sub window. Then the sections 'choose your bramble' and 'leader'
// wouldn't need to exist anymore").
function openLoadoutPicker(kind){
  document.querySelectorAll('.loadout-picker-overlay').forEach(e=> e.remove());
  const defs = getCardDefs();
  const ov = document.createElement('div'); ov.className = 'modal-overlay loadout-picker-overlay';
  const isCastle = kind === 'castle';
  let q = '';
  // 2026-10-12: a card in your deck can't also lead. 11:26 (user: "Potential leaders that you already put in your deck should be
  // listed, but greyed out - to show that you have them, but theyre used"): they're listed last, greyed, and can't be picked.
  const inDeck = id=> (myDeckCounts||{})[id] > 0;
  const leaderIds = ()=> getDraftableIds().filter(id=> defs[id] && !defs[id].locked && canLeadDef(defs[id]))
    .filter(id=> !q || defs[id].name.toLowerCase().includes(q))
    .sort((a,b)=> (inDeck(a) - inDeck(b)) || (RARITY_TIER_BANDS.indexOf(defs[b].rarity||'common') - RARITY_TIER_BANDS.indexOf(defs[a].rarity||'common')) || ((defs[b].attack||0)+(defs[b].health||0)) - ((defs[a].attack||0)+(defs[a].health||0)));
  const body = ()=> isCastle
    ? `<div class="lp-grid lp-castles">${Object.values(CHARACTER_DEFS).map(ch=> ({ch, open: castleUnlocked(ch) || (typeof adminModeEnabled!=='undefined' && adminModeEnabled)})).sort((a,b)=> (b.open - a.open)).map(({ch, open})=> `<button type="button" class="lp-item ${ch.id===myCharacterId?'is-on':''} ${open?'':'is-locked'}" ${open ? `data-pick="${escapeAttr(ch.id)}"` : 'disabled'} title="${open ? '' : escapeAttr(ch.drop ? 'Drops now and then from fights on Map ' + mapNumberOf(ch.drop.map) + ', or from a basic pack' : 'Beat the boss of Map ' + mapNumberOf(ch.unlockMap) + ' to unlock')}">
        <span class="lp-tile">${(()=>{ const lc = castleLeveled(ch, castleLevelOf(ch.id)); return matchCastleTileHTML(lc, lc.health, lc.health, 'preview', ''); })()}</span><b>${escapeHtml(ch.name)} <span class="lp-lv">Lv ${castleLevelOf(ch.id)}/${castleLevelOf(ch.id) >= CASTLE_MAX_LEVEL ? CASTLE_LIMIT_MAX : CASTLE_MAX_LEVEL}</span></b><small>${escapeHtml(characterDescHTML(ch))}</small></button>`).join('')}</div>
      <p class="lp-temper">🔨 Temper your castles in the Forge (🏰 Castles).</p>`
    : `<div class="lp-grid">${'' /* 2026-10-15 (user: "There is no need for the 'Remove' pill on the chosen leader."): no "✕ No leader / Clear the slot" tile; the chosen leader is just marked */}${leaderIds().slice(0, 120).map(id=> inDeck(id) ? `<button type="button" class="lp-item is-used" disabled aria-disabled="true" title="${escapeAttr(defs[id].name)} is in your deck. Take it out to make it your leader">
        <span class="lp-tile">${cardTileHTML(defs[id], {inPlay:true})}</span><b>${escapeHtml(defs[id].name)}</b><small>In your deck</small></button>` : `<button type="button" class="lp-item ${id===myLeaderId?'is-on':''}" data-pick="${escapeAttr(id)}">
        <span class="lp-tile">${cardTileHTML(defs[id], {inPlay:true})}</span><b>${escapeHtml(defs[id].name)}</b></button>`).join('') || '<p class="panel-sub">No cards match.</p>'}</div>`;
  ov.innerHTML = `<div class="modal loadout-picker" role="dialog" aria-label="${isCastle ? 'Choose your castle' : 'Choose your leader'}">
      <button type="button" class="modal-close-btn" aria-label="Close" data-close>✕</button>
      <h2>${isCastle ? '🏰 Choose your castle' : '👑 Choose your leader'}</h2>
      <p class="panel-sub">${isCastle ? 'Your castle sets your starting health and gives your whole side a passive.' : 'Your leader waits beside the board; summon it once per match. It counts double toward battle rating. Leaders are Heroic or above, or have the Leader passive.'}</p>
      ${isCastle ? '' : '<input type="search" class="lp-search" id="lpSearch" placeholder="Search your cards…" aria-label="Search your cards">'}
      <div class="lp-body">${body()}</div>
    </div>`;
  document.body.appendChild(ov);
  if(!isCastle) maybeLeaderRuleLesson(leaderIds().length > 0);
  const close = ()=>{ ov.remove(); document.removeEventListener('keydown', onKey); };
  const onKey = e=>{ if(e.key==='Escape') close(); };
  document.addEventListener('keydown', onKey);
  ov.addEventListener('click', e=>{
    if(e.target===ov || e.target.closest('[data-close]')) return close();
    const tb = e.target.closest('[data-temper-castle]');
    if(tb){ if(temperCastle(tb.dataset.temperCastle)){ try{ SoundKit.clang(); SoundKit.unlock && SoundKit.unlock(); }catch(_){} showToast(TX('toast.tempered-to-lv', {v1: castleLevelOf(tb.dataset.temperCastle)}), 'ok'); ov.querySelector('.lp-body').innerHTML = body(); try{ refreshDeckHeroBanner(); }catch(_){} } return; }
    const b = e.target.closest('[data-pick]'); if(!b) return;
    const id = b.dataset.pick;
    if(isCastle){ myCharacterId = id; saveMyCharacter(); }
    else { myLeaderId = id || null; saveMyLeader(); }
    try{ SoundKit.pickup(); }catch(_){}
    close(); refreshDeckHeroBanner();
  });
  const srch = ov.querySelector('#lpSearch');
  if(srch){ srch.focus(); srch.addEventListener('input', ()=>{ q = srch.value.trim().toLowerCase(); ov.querySelector('.lp-body').innerHTML = body(); }); }
}
function characterDescHTML(ch){
  const e = ch.effects||{};
  const bits = [];
  if(e.startGold) bits.push(`Start with +${e.startGold} 🪵`); // 2026-09-22: startGold now seeds starting Lumber, not Gold — see newPlayer() in bramblewood-engine.js
  if(e.firstUnitAtkBonus) bits.push(`1st unit played: +${e.firstUnitAtkBonus} ⚔`);
  if(e.unitHpBonus) bits.push(`Every unit played: +${e.unitHpBonus} ❤`);
  if(e.flyerAtkBonus) bits.push(`Flying units played: +${e.flyerAtkBonus} ⚔`);
  if(e.castleRegen) bits.push(`Heals ${e.castleRegen} ❤ each round`);
  if(e.enemyWaitBonus) bits.push(`The enemy's first 3 units arrive with +${e.enemyWaitBonus} ⏳ Wait`);
  if(e.castleBolt) bits.push(`Each round a ballista bolt hits a random enemy unit for ${e.castleBolt}`);
  if(e.castleLumberEvery) bits.push(`+1 🪵 every ${e.castleLumberEvery} rounds`);
  if(e.castleThorns) bits.push(`A unit that hits this castle takes ${e.castleThorns}`);
  if(e.herbRefinery) bits.push(`Each round, one of: heal your most wounded unit 3, 2 damage to a random enemy unit, or +1 🪵`);
  if(e.castleSpawn){ const sp = e.castleSpawn, d = getCardDefs()[sp.defId]; bits.push(`${(sp.count||1) > 1 ? (sp.count + '× ') : ''}${d ? d.name : sp.defId} join${(sp.count||1) > 1 ? '' : 's'} you on round ${sp.first||2}${sp.every ? ' and every ' + sp.every + ' rounds after' : ''}`); }
  return bits.length ? bits.join(' · ') : 'No passive — a plain, sturdy baseline.';
}
// 2026-09-20, per explicit request ("The castle ain't cards yet. Make them the same format as
