var DECK_LOOKS_KEY = 'bramblewood_arena_deck_looks', myDeckLooks = null; // 2026-10-16: per-copy looks (see deckLooksAll)
function loadMyDeck(){
  try{
    const raw = localStorage.getItem('bramblewood_arena_deck');
    if(raw) return JSON.parse(raw);
  }catch(e){}
  return {'otter-centurion':4,'bee-knight':4,'bee-drone':3,'dolphin-knight':3,'caustic-scorpion':3,'ent':1,'yeti':1,'scraper-of-skies':1};
}
function saveMyDeck(){ if(deckDraftActive()) return markDeckDirty(); try{ localStorage.setItem('bramblewood_arena_deck', JSON.stringify(myDeckCounts)); }catch(e){} try{ saveDeckLooks(); }catch(e){} /* 2026-10-16: which copies are Shiny / alt art */ if(typeof syncActiveDeckFromGlobals==='function') syncActiveDeckFromGlobals(); }
function deckTotal(counts){ return Object.values(counts).reduce((a,b)=>a+b,0); }
// Valid deck size (2026-09-16, per explicit request: "a valid deck is 20 cards. Do not allow
// a deck with <20 or >20 cards."). Enforced at the point a deck is actually USED (starting a
// match, running the simulator) rather than hard-blocking every add/remove click mid-build —
// a deck-in-progress can freely sit above or below 20 while you're still swapping cards
// around; you just can't START or RUN with anything other than exactly 20. The two hardcoded
// AI decks (DEFAULT_DECK in startMatch, every Conquest node's fixed enemy deck) aren't
// player-built decks and are intentionally exempt from this — DEFAULT_DECK already happens to
// total exactly 20, but Conquest's per-node decks don't, by design (they're scripted encounters,
// not something a person assembles from the pool).
const DECK_SIZE = 20;
// randomAiDeck (2026-09-18, per explicit request: "make it such that the AI always has random
// cards") — the "vs AI" Arena opponent used to run the exact same hardcoded DEFAULT_DECK every
// single match, which made it fully solvable/counter-draftable after a game or two. This builds
// a fresh random 20-card deck each time a match starts instead. It draws only from currently
// UNLOCKED cards (the same pool the player's own deck-builder pool restricts to) rather than the
// full 238-card roster — most cards are still locked/unbalanced (see the "balance locked cards"
// ask alongside this one), so drawing the AI's deck from that larger pool would make matches
// wildly uneven until that balance pass is done. Picks a random number of distinct cards (5-9,
// matching DEFAULT_DECK's old spread of 8) then randomly distributes 20 copies across them,
// capped at 4 copies each (DEFAULT_DECK's own max) so no single card can dominate the draw.
function randomAiDeck(){
  const defs = getCardDefs();
  const pool = getDraftableIds(true).filter(id=>!defs[id].locked);
  if(pool.length===0) return {'otter-centurion':4,'bee-knight':4,'bee-drone':3,'dolphin-knight':3,'caustic-scorpion':3,'ent':1,'yeti':1,'scraper-of-skies':1}; // fallback if somehow nothing is unlocked
  const shuffled = [...pool].sort(()=>Math.random()-0.5);
  const distinctCount = Math.max(1, Math.min(pool.length, 5 + Math.floor(Math.random()*5))); // 5-9 distinct cards, clamped to what's actually available
  const chosen = shuffled.slice(0, distinctCount);
  const counts = {}; chosen.forEach(id=> counts[id]=0);
  const perCardCap = Math.max(4, Math.ceil(DECK_SIZE/chosen.length)); // guarantees DECK_SIZE is always reachable even with very few unlocked cards
  let total = 0, guard = 0;
  while(total < DECK_SIZE && guard++ < 2000){
    const id = chosen[Math.floor(Math.random()*chosen.length)];
    if(counts[id] >= perCardCap) continue;
    counts[id]++; total++;
  }
  return counts;
}
// Small "X/20 cards" readout — used anywhere a deck's card count is shown so the 20-card
// requirement is visible at a glance, not just enforced with a surprise alert() at Start/Run
// time. 2026-09-16 follow-up: the warning half is now its own removable pill (was a plain text
// suffix) that disappears entirely once the deck is exactly 20 — only the plain count remains.
const _t = (en, vars)=> (typeof window!=='undefined' && window.i18) ? window.i18(en, vars) : String(en).replace(/\{(\w+)\}/g, (m, k)=> vars && vars[k]!=null ? vars[k] : m);
function deckSizeBadgeHTML(counts){
  const total = deckTotal(counts);
  const ok = total===DECK_SIZE;
  // 2026-10-08 (user: "Allow them to add cards [beyond 20], for convenience. But they cannot use the
  // deck if it's not legal"): over or under is a calm note, never a red alarm. Play checks legality.
  const countHTML = `<b style="color:${ok?'var(--health)':'var(--ink)'}">${escapeHtml(_t('{n}/{max} cards', {n:total, max:DECK_SIZE}))}</b>`;
  const diff = total - DECK_SIZE;
  const warnPillHTML = ok ? ` <span class="deck-size-ok-pill">✓ ${_t('ready to play')}</span>`
    : ` <span class="deck-size-warn-pill">${diff > 0 ? _t('{n} over · take {n} out to play', {n:diff}) : _t('{n} more to play', {n:-diff})}</span>`;
  return `${countHTML}${warnPillHTML}`;
}

// ---- Multiple decks (2026-09-20, per explicit request: "Deck Menu: Similar to the 'Player'
// page. Shows your decks. Deck has a small preview w/ Castle | Leader | Deck pill items.") ----
// Before this, the whole app had exactly ONE deck: the bare myDeckCounts/myCharacterId/
// myLeaderId globals above, each its own localStorage key. Rather than rip out every place that
// reads those three globals (match-starting, the Simulator, the Forge, etc. — all of Play), this
// layers a deck LIST on top of them: myDecks[] is the source of truth for what decks exist, but
// myDeckCounts/myCharacterId/myLeaderId still ALWAYS mirror whichever deck is "active" (the one
// you'd actually play a match with), kept in sync by syncActiveDeckFromGlobals()/
// switchActiveDeck() below. Every existing call site that reads/writes those three globals
// (renderPlayerSubTab, startMatch, etc.) keeps working completely unchanged.
function genDeckId(){ return 'deck-' + Math.random().toString(36).slice(2,9); }
function loadMyDecks(){
  try{
    const raw = localStorage.getItem('bramblewood_arena_decks');
    if(raw){
      const parsed = JSON.parse(raw);
      if(Array.isArray(parsed) && parsed.length) return parsed;
    }
  }catch(e){}
  return null; // signals "never migrated yet" to initMyDecks()
}
function saveMyDecks(skipCloudPush){ try{ localStorage.setItem('bramblewood_arena_decks', JSON.stringify(myDecks)); }catch(e){} if(!skipCloudPush) cloudPushDecks(); }
function loadActiveDeckId(){ try{ return localStorage.getItem('bramblewood_arena_active_deck') || null; }catch(e){ return null; } }
function saveActiveDeckId(){ try{ localStorage.setItem('bramblewood_arena_active_deck', activeDeckId); }catch(e){} }
let myDecks = loadMyDecks();
let activeDeckId = loadActiveDeckId();
if(!myDecks){
  // First run under the multi-deck system: fold the pre-existing single deck (already loaded
  // into myDeckCounts/myCharacterId/myLeaderId above) into deck #1 so nobody's existing
  // deck/Bramble/leader silently vanishes on upgrade.
  const firstId = genDeckId();
  myDecks = [{id:firstId, name:'Deck 1', characterId: myCharacterId, leaderId: myLeaderId, counts: Object.assign({}, myDeckCounts)}];
  activeDeckId = firstId;
  saveMyDecks(); saveActiveDeckId();
} else if(!activeDeckId || !myDecks.find(d=>d.id===activeDeckId)){
  activeDeckId = myDecks[0].id; saveActiveDeckId();
}
function getActiveDeck(){ return myDecks.find(d=>d.id===activeDeckId) || myDecks[0]; }
// Main deck (2026-10-08, user: "deck editor ... with main deck selection"): the deck you PLAY with.
// The editor still loads whichever deck you are editing into the working globals (every builder
// call site reads them), so leaving the Deck screen puts the main deck back (restoreMainDeck).
let mainDeckId = (()=>{ try{ return localStorage.getItem('bramblewood_arena_main_deck') || null; }catch(e){ return null; } })();
if(!mainDeckId || !myDecks.find(d=> d.id===mainDeckId)) mainDeckId = activeDeckId;
function setMainDeck(id){ if(!myDecks.find(d=> d.id===id)) return; mainDeckId = id; try{ localStorage.setItem('bramblewood_arena_main_deck', id); }catch(e){} }
function deckIsLegal(d){ return !!d && deckTotal(d.counts||{}) === DECK_SIZE; }
function restoreMainDeck(){ if(mainDeckId && activeDeckId !== mainDeckId && myDecks.find(d=> d.id===mainDeckId)) switchActiveDeck(mainDeckId); }
// Called right after ANY of the three legacy save*() functions (saveMyDeck/saveMyCharacter/
// saveMyLeader) run, so an edit made through the existing deck-builder UI (which only ever
// touches the bare globals) is reflected back into myDecks immediately.
function syncActiveDeckFromGlobals(){
  const d = getActiveDeck();
  if(!d) return;
  d.counts = Object.assign({}, myDeckCounts);
  try{ d.looks = JSON.parse(JSON.stringify(deckLooksAll())); }catch(e){} // 2026-10-16: per-copy looks ride with the deck
  d.characterId = myCharacterId;
  d.leaderId = myLeaderId;
  saveMyDecks();
}
function switchActiveDeck(id){
  const d = myDecks.find(x=>x.id===id);
  if(!d) return;
  activeDeckId = id; saveActiveDeckId();
  myDeckCounts = Object.assign({}, d.counts||{}); myDeckLooks = d.looks ? JSON.parse(JSON.stringify(d.looks)) : legacyDeckLooks(myDeckCounts); saveMyDeck(); // 2026-10-16: the deck's own looks
  myCharacterId = d.characterId || 'castle'; saveMyCharacter();
  myLeaderId = d.leaderId || null; saveMyLeader();
}
function createNewDeck(){
  const n = myDecks.length + 1;
  const d = {id: genDeckId(), name: `Deck ${n}`, characterId: 'castle', leaderId: null, counts: {}};
  myDecks.push(d); saveMyDecks();
  switchActiveDeck(d.id);
  return d;
}
function renameDeck(id, name){
  const d = myDecks.find(x=>x.id===id); if(!d) return;
  d.name = (name||'').trim().slice(0,40) || d.name;
  saveMyDecks();
}
function deleteDeck(id){
  if(myDecks.length<=1) return false; // always keep at least one deck
  const idx = myDecks.findIndex(x=>x.id===id);
  if(idx<0) return false;
  myDecks.splice(idx,1);
  saveMyDecks();
  if(mainDeckId===id) setMainDeck(myDecks[0].id);
  if(activeDeckId===id) switchActiveDeck(mainDeckId || myDecks[0].id);
  return true;
}
// Small Castle|Leader|Deck pill-preview row for one deck — used on the Deck Menu list. Reuses
// CHARACTER_DEFS (the "Bramble"/Castle picker) and the card defs (for the Leader's icon/name)
// exactly like the existing Player-tab builder does.
/* ============================================================
   Heroes (2026-10-05, "new card type: Hero — gains experience from battling and crafting
   materia, up to L100, gains skills, you pick your stat points: build your own card").
   One Hero per player for now. It's a real card (id 'hero', 1 copy) generated from the save:
   • Level 1→100 from XP: battles with the Hero in your deck, and crafting Materia in the Forge.
   • Each level gives 1 stat point (+3 extra every 10th level). You spend them: Attack, Health,
     Swiftness (Wait 1 → 0). Free respec while we tune it.
   • Skills at levels 5, 15, 30, 50, 75, 100: pick 1 of 3 from your people's kit. Number skills
     grow with level (1 + every 25 levels).
   • Cost to play rises with level (1 → 4), so a strong Hero is a real investment each match.
   • Power budget: a maxed Hero lands around a top Legendary (≈ 10 attack / 45 health worth).
   • PvE for now: stripped from anything that leaves your device (live matches, ghosts, invites),
     because other players' games don't have your Hero's card yet.
   ============================================================ */
const HERO_KEY = 'bramblewood_hero_v1';
const HERO_ID = 'hero';
const HERO_MAX_LEVEL = 100;
const HERO_SKILL_LEVELS = [5, 15, 30, 50, 75, 100];
const HERO_COSTS = {atk: 5, hp: 1, speed: 25};   // stat points per +1 Attack / +1 Health / Wait −1. Priced from the roster: Health runs ~5× Attack (median cost-3 card is 8/34).
const HERO_PEOPLES = {
  legion: {label:'Rivergate Legionary', blurb:'Steady and hard to move. Shields, armour and holding the line.', icon:'🦦', art:'river-warden', archetypes:['Otter','River'], base:{attack:2, health:9},
    skills:['guardian','armor','bulwark','shell','thorns','sturdy','siege','reflect','regen']},
  tribes: {label:'Sunfeather Warrior', blurb:'Fast and bright. Wings, speed and first strikes.', icon:'🐦', art:'crimson-wing-recruit', archetypes:['Hummingbird'], base:{attack:3, health:6},
    skills:['flying','evasive','swift','quick','crit','frenzy','puncture','ambush','momentum']},
  road:   {label:'Road-folk Wanderer', blurb:'Sly and slippery. Poison, bleeding, tricks and a bow.', icon:'🐭', art:'wandering-traveller', archetypes:['Mouse','Traveller'], base:{attack:2, health:7},
    skills:['stealth','poison','bleed','expose','gash','render','arrow','corrode','fester']},
};
function loadHero(){ try{ const h = JSON.parse(localStorage.getItem(HERO_KEY)||'null'); if(h && HERO_PEOPLES[h.people]) return Object.assign({xp:0, alloc:{atk:0,hp:0,speed:0}, picks:{}, materia:{}, battles:0, wins:0}, h); }catch(e){} return null; }
let myHero = loadHero();
function saveHero(){ try{ localStorage.setItem(HERO_KEY, JSON.stringify(myHero)); }catch(e){} try{ soonCheckMilestones(); }catch(e){} }
// Pacing: Lv 20 ≈ 15 wins, Lv 50 ≈ 110, Lv 100 ≈ 600 (fewer with Materia). Total to 100 ≈ 21.5k XP.
function heroXpToNext(L){ return Math.round(10 + 1.5*L + 0.04*L*L); }
function heroLevelFromXp(xp){ let L = 1, left = xp; while(L < HERO_MAX_LEVEL && left >= heroXpToNext(L)){ left -= heroXpToNext(L); L++; } return {level:L, into:left, need: L < HERO_MAX_LEVEL ? heroXpToNext(L) : 0}; }
function heroPointsForLevel(L){ return (L-1) + 3*Math.floor(L/10); }
function heroPointsSpent(h){ return h.alloc.atk*HERO_COSTS.atk + h.alloc.hp*HERO_COSTS.hp + h.alloc.speed*HERO_COSTS.speed; }
function heroPointsFree(h){ return heroPointsForLevel(heroLevelFromXp(h.xp).level) - heroPointsSpent(h); }
function heroSkillValue(L){ return 1 + Math.floor(L/25); }
function heroSkillDef(key){ return [...PASSIVE_DEFS, ...ACTIVE_PRESETS].find(p=> p.key===key); }
function heroSkillOffer(h, atLevel){
  // three choices, stable per hero and milestone, never repeating a skill already picked
  const pool = HERO_PEOPLES[h.people].skills.filter(k=> !Object.values(h.picks).includes(k) && heroSkillDef(k));
  let seed = (h.created||1) % 100000 + atLevel*7919; const rnd = ()=> (seed = (seed*16807) % 2147483647) / 2147483647;
  const a = pool.slice(); for(let i = a.length-1; i > 0; i--){ const j = Math.floor(rnd()*(i+1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a.slice(0, 3);
}
// Hero rarity climbs with level (2026-10-09, user: "Hero: the cards can gain rarity over their
// upgrading"). A new hero starts Common and ends Legendary at the top of the ladder.
const HERO_RARITY_STEPS = [[1,'common'],[5,'uncommon'],[15,'rare'],[30,'epic'],[50,'heroic'],[70,'unique'],[90,'legendary']];
function heroRarityForLevel(L){ let r = 'common'; HERO_RARITY_STEPS.forEach(([at, k])=>{ if(L >= at) r = k; }); return r; }
function heroNextRarity(L){ const n = HERO_RARITY_STEPS.find(([at])=> at > L); return n ? {level:n[0], rarity:n[1]} : null; }
function heroDef(){
  const h = myHero; if(!h) return null;
  const P = HERO_PEOPLES[h.people], L = heroLevelFromXp(h.xp).level;
  const effects = {};
  Object.values(h.picks).forEach(k=>{
    const sd = heroSkillDef(k); if(!sd) return;
    if(sd.build) Object.assign(effects, sd.build(heroSkillValue(L)));
    else effects[k] = sd.kind==='boolean' ? true : heroSkillValue(L);
  });
  const artDef = CARD_DEFS_BASELINE[P.art] || {};
  return {id:HERO_ID, name: h.name || P.label, icon: P.icon, art: artDef.art || '', hero:true, heroLevel:L,
    attack: P.base.attack + h.alloc.atk, health: P.base.health + h.alloc.hp,
    cost: 1 + (L>=20) + (L>=50) + (L>=80), wait: Math.max(0, 1 - h.alloc.speed),
    rarity: heroRarityForLevel(L), archetypes: P.archetypes.slice(), effects, locked:false,
    flavor: `${P.label} · Level ${L}. Built by your own hand, one battle at a time.`};
}
function heroGainXp(n, why){
  if(!myHero || !(n > 0)) return;
  const before = heroLevelFromXp(myHero.xp).level;
  myHero.xp += n; saveHero();
  const after = heroLevelFromXp(myHero.xp).level;
  if(after > before){
    try{ SoundKit.heroLevel(); }catch(e){}
    heroLevelUpPending = after;
    const pts = heroPointsFree(myHero), skill = HERO_SKILL_LEVELS.some(l=> l > before && l <= after);
    setTimeout(()=> showToast(TX('toast.reached-level-deck-hero', {name: escapeHtml(myHero.name), after, v3: pts>0 ? ` ${pts} stat point${pts===1?'':'s'} to spend` : '', v4: skill ? ' · a new skill to pick' : ''}), 'ok'), 700);
  } else if(why) showToast(TX('toast.hero-xp', {n, why}), 'ok');
}
// Battle XP: the Hero must have been in the deck you fought with. Win +30 (+10 if it took the field), loss or draw +10.
function heroAwardBattle(m){
  if(!myHero || !m || !(myDeckCounts && myDeckCounts[HERO_ID] > 0)) return;
  // only when the Hero really was in this fight's deck (raids, trenches and drafts use other decks)
  let inFight = !!(m.stats && m.stats[statKeyFor('A', HERO_ID)]);
  if(!inFight){ try{ inFight = /"hero"/.test(JSON.stringify(m.players && m.players[1] || {})); }catch(e){} }
  if(!inFight) return;
  const played = !!(m.stats && m.stats[statKeyFor('A', HERO_ID)] && m.stats[statKeyFor('A', HERO_ID)].played > 0);
  const won = m.winner === 1;
  myHero.battles = (myHero.battles||0) + 1; if(won) myHero.wins = (myHero.wins||0) + 1;
  heroGainXp((won ? 30 : 10) + (won && played ? 10 : 0), won ? 'victory' : 'experience');
}
let heroLevelUpPending = 0;
// A crystal forms over the craft button: it grows out of a ring of sparks, spins once, and drops
// toward the Materia counts. Pure CSS/DOM; skipped for reduced motion.
function materiaBurstVfx(kind){
  if(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const btn = document.querySelector('#heroCraftBtn, [data-fmb="craft"]'); if(!btn) return;
  const r = btn.getBoundingClientRect();
  const el = document.createElement('div'); el.className = 'materia-burst mk-' + kind.id; el.setAttribute('aria-hidden', 'true');
  el.style.left = (r.left + r.width/2) + 'px'; el.style.top = (r.top - 8) + 'px';
  el.innerHTML = `<span class="mb-gem">${kind.icon}</span>` + Array.from({length:10}, (_, i)=> `<i style="--a:${i*36}deg; --d:${(i%3)*40}ms"></i>`).join('');
  document.body.appendChild(el); setTimeout(()=> el.remove(), 1400);
}
// When the Hero Hall opens after a level-up, the big card gets a rising ring of light once.
function heroHallLevelFlourish(body){
  if(!heroLevelUpPending) return; heroLevelUpPending = 0;
  if(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const card = body.querySelector('.hero-card-big'); if(!card) return;
  card.classList.remove('is-levelling'); void card.offsetWidth; card.classList.add('is-levelling');
  setTimeout(()=> card.classList.remove('is-levelling'), 1500);
}
function statKeyFor(side, defId){ return side + '|' + defId; }
// Materia (T4, first version): crafted in the Forge from Magic Dust. Each craft grants Hero XP and
// a crystal of one of four kinds, kept for socketing later.
const MATERIA_KINDS = [{id:'ember', icon:'🔥', name:'Ember'}, {id:'tide', icon:'💧', name:'Tide'}, {id:'grove', icon:'🌿', name:'Grove'}, {id:'stone', icon:'🪨', name:'Stone'}];
const MATERIA_DUST_COST = 125, MATERIA_HERO_XP = 30; // ×5 with the forge economy v2 income (2026-10-11)
// Materia belongs to the player now (2026-10-08), not the Hero: it is what Enchanting spends.
// A Hero's old crystals move over once. Crafting still gives a Hero XP when you have one.
var myMateria = (()=>{ try{ return JSON.parse(localStorage.getItem('bramblewood_materia_v1')||'null'); }catch(e){ return null; } })();
function saveMateria(){ try{ localStorage.setItem('bramblewood_materia_v1', JSON.stringify(myMateria)); }catch(e){} }
function materiaStore(){
  if(!myMateria){ myMateria = {}; try{ if(typeof myHero!=='undefined' && myHero && myHero.materia) Object.assign(myMateria, myHero.materia); }catch(e){} saveMateria(); }
  return myMateria;
}
// Enchanting (2026-10-08, user: "Split refinement, enchantment, and upgrading"): socket one Materia
// crystal into a card for a small, permanent bonus. One socket per card; a new crystal replaces the
// old one (the old crystal is used up). Values are a first pass, easy to retune here.
const ENCHANTS = {
  ember: {atk:1, hp:0, label:'+1 ⚔ · its hits scorch', fx:{hit:'burn'}},
  stone: {atk:0, hp:3, label:'+3 ❤'},
  tide:  {atk:0, hp:2, label:'+2 ❤'},
  grove: {atk:1, hp:1, label:'+1 ⚔ +1 ❤'},
};
var myCardEnchants = (()=>{ try{ return JSON.parse(localStorage.getItem('bramblewood_enchants_v1')||'{}') || {}; }catch(e){ return {}; } })();
function saveCardEnchants(){ try{ localStorage.setItem('bramblewood_enchants_v1', JSON.stringify(myCardEnchants)); }catch(e){} }
function enchantCard(id, kind){
  const st = materiaStore();
  if(!ENCHANTS[kind] || (st[kind]||0) < 1) return false;
  st[kind]--; saveMateria();
  myCardEnchants[id] = kind; saveCardEnchants(); invalidateCardDefs();
  return true;
}
// Refining (2026-10-08, user: "Refinement is to upgrade the foil treatment. You can never make
// something Shiny besides getting it in a pack"): raises your best copy one step up the finish
// ladder. Shiny is never touched here; it only comes from receiving a card (grantCardCopy).
const REFINE_LADDER = [
  {key:null, label:'Plain'},
  {key:'auto', label:'Foil', cost:{dust:200, gold:500}},
  {key:'hex', label:'Hex', cost:{dust:300, gold:750}},
  {key:'etched', label:'Etched', cost:{dust:400, gold:1000}},
  {key:'ice', label:'Cracked ice', cost:{dust:500, gold:1250}},
  {key:'reverse', label:'Reverse', cost:{dust:600, gold:1500}},
  {key:'prism', label:'Prism', cost:{dust:750, gold:1750, gems:5}},
  {key:'gold', label:'Gold leaf', cost:{dust:1000, gold:2250, gems:10}},
];
function copyRefineRank(c){
  if(!c || !c.foil) return 0;
  const i = REFINE_LADDER.findIndex(r=> r.key === (c.finish || 'auto'));
  return i < 0 ? 1 : i; // pack-only finishes (rainbow / pearl / cosmos) sit on the Foil step
}
function bestCopyIndex(id){
  const copies = myCardCopies[id] || []; let best = -1, rank = -1;
  copies.forEach((c, i)=>{ const r = copyRefineRank(c) + (c && c.shiny ? 0.5 : 0); if(r > rank){ rank = r; best = i; } });
  return best;
}
function canAffordCost(c){ return (myCurrencies.dust||0) >= (c.dust||0) && (myCurrencies.gold||0) >= (c.gold||0) && (myCurrencies.gems||0) >= (c.gems||0); }
function refineCard(id){
  const i = bestCopyIndex(id); if(i < 0) return null;
  const c = myCardCopies[id][i], r = copyRefineRank(c), next = REFINE_LADDER[r+1];
  if(!next || !canAffordCost(next.cost)) return null;
  myCurrencies.dust -= next.cost.dust||0; myCurrencies.gold -= next.cost.gold||0; myCurrencies.gems -= next.cost.gems||0; saveCurrencies();
  c.foil = true; if(next.key === 'auto') delete c.finish; else c.finish = next.key; // never sets shiny
  saveCardCopies();
  return next;
}
function craftMateria(){
  if((myCurrencies.dust||0) < MATERIA_DUST_COST){ showToast(TX('toast.need-magic-dust-to-craft-materia', {MATERIA_DUST_COST})); return false; }
  myCurrencies.dust -= MATERIA_DUST_COST; saveCurrencies();
  const k = MATERIA_KINDS[Math.floor(Math.random()*MATERIA_KINDS.length)];
  const st = materiaStore(); st[k.id] = (st[k.id]||0) + 1; saveMateria();
  if(myHero) heroGainXp(MATERIA_HERO_XP, `crafted ${k.icon} ${k.name} Materia`);
  try{ SoundKit.materiaForm(); }catch(e){}
  try{ materiaBurstVfx(k); }catch(e){}
  return k;
}
// Decks that leave this device (live matches, ghosts, invites, raid records) go without the Hero.
function publicDeck(counts){ const out = Object.assign({}, counts||{}); delete out[HERO_ID]; return out; }

// Deck showcase (2026-10-04, "deck preview cards should prominently highlight the leader and castle
// choice, and some signature of the deck — archetypes, average attack, defence and cost"). Used on
// the Manage-decks cards and the Profile's "what rivals see" preview.
function deckSignature(d){
  const defs = getCardDefs(), counts = d.counts || {};
  let n = 0, atk = 0, hp = 0, cost = 0; const arch = {};
  Object.entries(counts).forEach(([id, c])=>{
    const x = defs[id]; if(!x || !(c > 0)) return;
    n += c; atk += (x.attack||0)*c; hp += (x.health||0)*c; cost += (x.cost||0)*c;
    (x.archetypes||[]).forEach(a=>{ if(a && a!=='Misc') arch[a] = (arch[a]||0) + c; });
  });
  const archetypes = Object.entries(arch).sort((a,b)=> b[1]-a[1]).filter(([,c])=> c >= Math.max(3, n*0.15)).slice(0,3).map(([a])=> a);
  const fmt = v=> n ? (Math.round(v/n*10)/10).toFixed(1) : '–';
  return {n, archetypes, avgAtk: fmt(atk), avgHp: fmt(hp), avgCost: fmt(cost)};
}
// The deck's own cards on its preview (2026-10-08, user: "The card preview (cards in the deck) now
// should be changed to showing the cards"): every distinct card as a small tile, cheapest first,
// with its copy count.
function deckCardsStripHTML(d){
  const defs = getCardDefs(), counts = d.counts || {};
  const ids = Object.keys(counts).filter(id=> defs[id] && counts[id] > 0).sort((a,b)=> (defs[a].cost||0)-(defs[b].cost||0) || (defs[a].name||'').localeCompare(defs[b].name||''));
  if(!ids.length) return '<p class="panel-sub dm-empty">No cards yet. Edit the deck to add some.</p>';
  return `<div class="dm-cards" aria-label="Cards in this deck">${ids.map(id=> `<span class="dm-card" data-defid="${escapeAttr(id)}" aria-label="${escapeAttr(defs[id].name)} ×${counts[id]}">${cardTileHTML(defs[id], {inPlay:true})}${counts[id]>1 ? `<b class="dm-x">×${counts[id]}</b>` : ''}</span>`).join('')}</div>`;
}
// deck-medium-preview (2026-10-10, user: "the deck-medium-preview ... does not show the cards and highlights the art of
// the leader and castle. Castle on the left, leader on the right, as the background of the preview"). The large one is the
// full deck card with every card (deck-large-preview, hover a card for its details).
function deckMediumPreviewHTML(d){
  const defs = getCardDefs();
  const castle = CHARACTER_DEFS[d.characterId] || CHARACTER_DEFS.castle;
  const leader = d.leaderId && defs[d.leaderId];
  const sig = deckSignature(d), total = deckTotal(d.counts||{});
  // 2026-10-14 (user: "don't need to write the name of the castle and leader - the pictures are enough ... include the total Attack
  // and total HP as well. Don't need to write the number of cards in the deck unless its invalid aka not 20"): the names live in the
  // aria-label and tooltips now; the foot shows the rating, the deck's total Attack and Health, and the count only when it's off.
  const tot = Object.entries(d.counts||{}).reduce((a, [id, n])=>{ const c = defs[id]; if(c && n > 0){ a.atk += (c.attack||0) * n; a.hp += (c.health||0) * n; } return a; }, {atk:0, hp:0});
  // 2026-10-14 (21:33, user: "The Deck preview art should show the Castle's art. Not the generic icon."): the castle half paints the castle's art.
  const leaderBg = leader && leader.art ? `background-image:url(${leader.art})` : '';
  return `<div class="deck-medium-preview ${d.id===mainDeckId?'is-main':''}" data-deckid="${d.id}">
    <div class="dmp-bg" aria-hidden="true">
      <div class="dmp-castle ${castle && castle.art ? 'has-art' : ''}" title="${escapeAttr((castle ? castle.name : 'Castle') + ' · Lv ' + castleLevelOf(castle && castle.id))}"${castle && castle.art ? ` style="background-image:url(${castle.art})"` : ''}>${castle && castle.art ? '' : `<span>${castle ? castle.icon || '🏰' : '🏰'}</span>`}</div>
      <div class="dmp-leader ${leader && leader.art ? 'has-art' : ''}" title="${escapeAttr(leader ? 'Leader: ' + leader.name : 'No leader')}" style="${leaderBg}">${leader && !leader.art ? `<span>${leader.icon||'👑'}</span>` : ''}</div>
    </div>
    <div class="dmp-top"><b class="dmp-name">${escapeHtml(d.name)}</b>${d.id===mainDeckId?'<span class="deck-active-badge">★ MAIN</span>':''}</div>
    <div class="dmp-foot">
      <span class="dmp-meta"><span class="dmp-rating" title="Battle rating: how strong this deck plays overall">⚔ ${mainDeckLevel(d.counts||{}, d.leaderId)}</span><span class="dmp-tot" title="Total Attack of the cards in this deck">🗡️ ${tot.atk}</span><span class="dmp-tot" title="Total Health of the cards in this deck">❤️ ${tot.hp}</span>${total===DECK_SIZE ? '' : `<span class="short" title="A deck needs exactly ${DECK_SIZE} cards to play">🃏 ${total}/${DECK_SIZE}</span>`}${sig.archetypes.slice(0, 2).map(a=> `<span>${escapeHtml(a)}</span>`).join('')}</span>
    </div>
  </div>`;
}
function deckShowcaseHTML(d, opts){
  opts = opts || {};
  const defs = getCardDefs();
  const castle = CHARACTER_DEFS[d.characterId] || CHARACTER_DEFS.castle;
  const leader = d.leaderId && defs[d.leaderId];
  const sig = deckSignature(d);
  const total = deckTotal(d.counts||{});
  const castleTile = matchCastleTileHTML(castle, castle ? castle.health : 30, castle ? castle.health : 30, 'preview', '');
  const leaderTile = leader ? cardTileHTML(leader, {inPlay:true}) : `<div class="ds-empty-leader">👑<small>No leader yet</small></div>`;
  return `<div class="deck-showcase ${opts.compact?'is-compact':''}">
    <div class="ds-pair">
      <figure class="ds-slot"><div class="ds-tile">${castleTile}</div><figcaption>🏰 ${escapeHtml(castle ? castle.name : 'Castle')}</figcaption></figure>
      <figure class="ds-slot"><div class="ds-tile">${leaderTile}</div><figcaption>👑 ${leader ? escapeHtml(leader.name) : 'Leader'}</figcaption></figure>
    </div>
    <div class="ds-info">
      <div class="ds-arch">${sig.archetypes.length ? sig.archetypes.map(a=> `<span class="ds-arch-chip">${escapeHtml(a)}</span>`).join('') : '<span class="ds-arch-chip is-mixed">Mixed</span>'}</div>
      <div class="ds-stats">
        <span title="Average attack"><b>${sig.avgAtk}</b><small>⚔ avg atk</small></span>
        <span title="Average health"><b>${sig.avgHp}</b><small>❤ avg hp</small></span>
        <span title="Average cost (Lumber)"><b>${sig.avgCost}</b><small>🪵 avg cost</small></span>
      </div>
      <div class="ds-meta">${total===DECK_SIZE ? '' : `<span class="short" title="A deck needs exactly ${DECK_SIZE} cards to play">🃏 ${total}/${DECK_SIZE}</span>`}<span title="Battle rating: how strong this deck plays overall">⚔ ${mainDeckLevel(d.counts||{}, d.leaderId)}</span>${(()=>{ const t = Object.entries(d.counts||{}).reduce((a, [id, n])=>{ const c = defs[id]; if(c && n > 0){ a.atk += (c.attack||0) * n; a.hp += (c.health||0) * n; } return a; }, {atk:0, hp:0}); return `<span title="Total Attack of the cards in this deck">🗡️ ${t.atk}</span><span title="Total Health of the cards in this deck">❤️ ${t.hp}</span>`; })()}</div>
    </div>
  </div>`;
}
function deckPreviewPillsHTML(d){
  const defs = getCardDefs();
  const castle = CHARACTER_DEFS[d.characterId] || CHARACTER_DEFS.castle;
  const leader = d.leaderId && defs[d.leaderId];
  const total = deckTotal(d.counts||{});
  return `<div class="deck-preview-pills">
    <span class="deck-pill deck-pill-castle" title="Castle (Bramble)">${castle?castle.icon:'🏰'} ${escapeHtml(castle?castle.name:'Castle')}</span>
    <span class="deck-pill deck-pill-leader" title="Leader">👑 ${leader?escapeHtml(leader.name):'No Leader'}</span>
    <span class="deck-pill deck-pill-count ${total===DECK_SIZE?'ok':''}" title="Deck size">🃏 ${total}/${DECK_SIZE}</span>
    <span class="deck-pill deck-pill-level" title="Battle rating: each card's rarity weight × its level factor; the leader counts double. A starting deck is about 10, a full level-10 Ancient deck about 2,500">⚔ Rating ${mainDeckLevel(d.counts||{}, d.leaderId)}</span>
  </div>`;
}
// Battle rating (2026-10-11, user: "battle rating: Replace deck level ... a beginner level deck has rating 1-25. While
// the max it can be is about 2,500. A good middle ground is 400+ for Map 20"). Each card adds its rarity's weight (the
// same ladder as its Forge cost: Common 1, Uncommon 2, Rare 4, Very Rare 6, Super Rare 8, Epic 11, Heroic 14, Unique 17,
// Legendary 21, Mythic 25, Ancient 30; Base 0.5) × its level factor (1 at level 1, 3.79 at level 10, 0.7 at a Base
// card's level 0); the leader counts double. A full deck of level-10 Ancients with an Ancient leader is ≈2,500.
const RATING_WEIGHT = {starter:0.5, common:1, uncommon:2, rare:4, veryrare:6, superrare:8, epic:11, heroic:14, unique:17, legendary:21, mythic:25, ancient:30, divine:36, void:42, daemonic:48};
function ratingWeightOf(d){ if(!d) return 0; const r = d.rarity || 'common', as = (RARITY_DEFS.find(x=> x.key===r) || {}).as; return RATING_WEIGHT[r] || RATING_WEIGHT[as] || 1; }
// cap (2026-10-16, the Tower): its enemies fight up to Level 20, and the same straight line carries on past 11 (Lv 20 = 6.89).
function ratingLevelFactor(L, cap){ L = Math.max(0, Math.min(cap || 11, Number(L)||0)); return L <= 0 ? 0.7 : 1 + (L - 1) * 0.31; }
function deckLevelFrom(counts, levelOf, leaders, cap){
  const defs = getCardDefs();
  const one = id=>{ const k = String(id).split('~')[0], d = defs[k]; if(!d) return 0; return ratingWeightOf(d) * ratingLevelFactor(levelOf(k), cap); };
  let t = 0;
  Object.keys(counts||{}).forEach(id=>{ t += (counts[id]||0) * one(id); });
  (leaders||[]).filter(Boolean).forEach(id=>{ t += 2 * one(id); });
  return Math.max(0, Math.round(t));
}
// An enemy's battle rating is the rating a player should bring (enemy decks are small and their strength is in the
// castle), on one curve for the whole road: about 12 at Map 1, 400 at Map 20, rising about 20% a map. Inside a map the
// skirmishes run from 85% to 115% of the map's par, an elite is 115%, a boss 130%, the campaign boss 140%, a side map
// +10%. A fight can set its own (node.rating, in the skirmish editor).
// 2026-10-12 (D60 + your map list): rebased so the Sundered Peak's final boss (Map 20, ×1.4) lands on 400; its side maps set their own.
function mapParRating(mapNo){ return 12 * Math.pow((400/1.4)/12, (Math.max(1, mapNo) - 1) / 19); }
function enemyDeckLevel(node){
  // 2026-10-12 (22:25, user: "The battle rating seen in the game should be real values! Not hard coded"): worked out from the
  // enemy's actual deck, at the levels its cards will really fight at (the road level, or a level set in Edit skirmish), with its
  // leaders counted like a player's leader. No more curve or typed-in rating.
  if(!node || !node.deck) return 0;
  const defs = getCardDefs(); let road = 0;
  try{ const real = CONQUEST_MAPS.flatMap(m=> m.nodes||[]).find(n=> n === node) || CONQUEST_MAPS.flatMap(m=> m.nodes||[]).find(n=> n.key === node.key); road = roadEnemyLevel(real || node); }catch(e){}
  const lv = id=>{ const set = node.cardLevels && node.cardLevels[id]; const b = cardBaseLevel(CARD_DEFS_BASELINE[id] || defs[id]); return set != null && set !== '' ? Number(set) : Math.max(b, road || b); };
  // Enemy decks are smaller than a player's 20; scale to 20 cards so the two ratings compare like for like.
  const n = Object.values(node.deck).reduce((a, b)=> a + (b||0), 0) || 1;
  const leaders = (node.leaders || (node.leaderId ? [node.leaderId] : [])).filter(Boolean);
  const cap = node.levelCap || 11; // the Tower's floors fight up to Level 20 (2026-10-16)
  const body = deckLevelFrom(node.deck, lv, [], cap) * (DECK_SIZE / n), lead = deckLevelFrom({}, lv, leaders, cap);
  return Math.round(body + lead);
}
function mainDeckLevel(counts, leaderId){
  return deckLevelFrom(counts, id=> getCardLevel(id), leaderId ? [leaderId] : []);
}
// PvP matchmaking keeps the older power score (rarity × max(1, level)), so stored ghost decks stay comparable.
function deckPowerLevel(counts, leaderId){
  if(typeof BramblewoodAutobattle==='undefined') return 0;
  return BramblewoodAutobattle.deckLevelOf(getCardDefs(), counts, id=> Math.max(1, (myCardLevels||{})[id]||0), leaderId ? [leaderId] : []);
}

// ---- Deck import/export codes (2026-09-21, per the "shop/packs and deck-export-codes" pick
// from roadmap-and-backlog.md's own suggested build order — shop/packs already shipped
// 2026-09-20, this closes out the other half) ----
// A short shareable text string that fully encodes one deck (name, Castle/Bramble, Leader,
// and card counts) so a player can hand a build to someone else outside the game (Discord, a
// forum post, etc.) without a screenshot, and the recipient gets it back as a real, editable
// deck rather than a picture of one. Format: `BWD1:` + a UTF-8-safe base64 blob of a small JSON
// payload — deliberately NOT a bit-packed/minified format (a Hearthstone/Marvel-Snap-style
// deck code doesn't need to be byte-optimal to be "shareable," and staying plain JSON under the
// base64 means a future field can be added without a version-2 migration for old codes: an
// older client just ignores a key it doesn't recognize, and `decodeDeckCode` below already
// tolerates missing keys with sane defaults).
const DECK_CODE_PREFIX = 'BWD1:';
// btoa/atob only handle Latin1 — a deck name can contain any Unicode a player typed (emoji
// included), so this wraps them in the standard encodeURIComponent/escape round-trip rather
// than risk `btoa` throwing on a non-Latin1 character (a real crash a naive `btoa(JSON...)`
// would hit the first time someone names a deck with, say, an emoji).
function b64EncodeUnicode(str){ return btoa(unescape(encodeURIComponent(str))); }
function b64DecodeUnicode(str){ return decodeURIComponent(escape(atob(str))); }
function encodeDeckCode(d){
  const payload = { n: (d.name||'Deck').slice(0,40), c: d.characterId||'castle', l: d.leaderId||null, d: Object.assign({}, d.counts||{}) };
  return DECK_CODE_PREFIX + b64EncodeUnicode(JSON.stringify(payload));
}
// Returns {ok:true, deck:{name,characterId,leaderId,counts}, warnings:[...]} or {ok:false, reason}.
// Deliberately permissive rather than all-or-nothing: an otherwise-valid code from a NEWER
// build that references a card this build doesn't know about (or one that got renamed/removed
// since the code was shared) still imports everything it can, dropping just the unrecognized
// entries and reporting them as warnings — a friend's shared deck shouldn't refuse to import
// entirely over one card neither of you can do anything about.
function decodeDeckCode(str){
  const raw = (str||'').trim();
  if(!raw) return {ok:false, reason:'Empty code.'};
  if(!raw.startsWith(DECK_CODE_PREFIX)) return {ok:false, reason:'Not a Bramblewood deck code (missing the "'+DECK_CODE_PREFIX+'" prefix).'};
  let payload;
  try{ payload = JSON.parse(b64DecodeUnicode(raw.slice(DECK_CODE_PREFIX.length))); }
  catch(e){ return {ok:false, reason:'Could not read that code — it looks corrupted or truncated.'}; }
  if(!payload || typeof payload!=='object') return {ok:false, reason:'Could not read that code — it looks corrupted or truncated.'};
  const warnings = [];
  const defs = getCardDefs();
  const characterId = (payload.c && CHARACTER_DEFS[payload.c]) ? payload.c : (warnings.push('Unknown Castle/Bramble — defaulted to the starting Castle.'), 'castle');
  let leaderId = null;
  if(payload.l){
    if(defs[payload.l]) leaderId = payload.l;
    else warnings.push('The Leader card in this code no longer exists — imported with no Leader.');
  }
  const counts = {};
  let droppedCards = 0;
  Object.keys(payload.d||{}).forEach(id=>{
    const n = Math.max(0, Math.min(60, Math.round(Number(payload.d[id])||0))); // 60: generous sanity cap, not a real deck-size rule
    if(n<=0) return;
    if(!defs[id]){ droppedCards++; return; }
    counts[id] = n;
  });
  if(droppedCards>0) warnings.push(`${droppedCards} card${droppedCards===1?'':'s'} in this code no longer exist${droppedCards===1?'s':''} and were skipped.`);
  const name = (typeof payload.n==='string' && payload.n.trim()) ? payload.n.trim().slice(0,40) : 'Imported Deck';
  return {ok:true, deck:{name, characterId, leaderId, counts}, warnings};
}

// ---- Local profile / "login" (2026-09-20, per explicit request: "Have a login page at the
// landing page. If already logged in, click start.") — the game is a single static file with no
// backend/server (see initUserAuth's own comment above on why real Google OAuth isn't something
// this app can do on its own), so "logged in" here means a simple on-device profile: a display
// name saved to localStorage, nothing more. No password, no account recovery, no server — the
// same honest, no-fake-auth spirit as initUserAuth's Artifact-only "Signed in as X" pill, just
// as a standalone concept that works even outside an Artifact host. ----
function loadMyProfile(){
  try{ const raw = localStorage.getItem('bramblewood_arena_profile'); if(raw) return JSON.parse(raw); }catch(e){}
  return null;
}
function saveMyProfile(p){ try{ localStorage.setItem('bramblewood_arena_profile', JSON.stringify(p)); }catch(e){} myProfile = p; }
function clearMyProfile(){ try{ localStorage.removeItem('bramblewood_arena_profile'); }catch(e){} myProfile = null; }
let myProfile = loadMyProfile();

// Conquest (2026-09-16, per explicit request) is now the featured/default sub-tab — a map
// campaign of preset AI skirmishes sits beside the existing Player (deck/character) and
// Arena (quick vs AI/vs PC/Async) sub-tabs, plus a Raid tab for permanently-unlocked Raid
// Bosses. 'conquest' | 'player' | 'arena' | 'raid' — only relevant when no match is in progress.
let playSubTab = 'conquest';
// Item #4 (2026-09-18): a small, generic ">1s hover" tooltip helper — a single shared tooltip
// element (created once, reused for every caller) that only appears after the pointer has sat
// still on `el` for `delayMs` (default 1000ms), and disappears the instant the pointer leaves,
// even mid-delay. Kept generic (not Conquest-specific) since the same "don't explain everything
// up front, only on a deliberate long hover" pattern is reusable anywhere else a button could use
// it later.
let __delayedTooltipEl = null;
// Tooltip lifecycle (2026-10-11 card-object audit, user: "tooltip fade hooks, e.g. OnFade → Tooltip.Fade()"). Rather
// than every card and button carrying its own fade/remove callbacks, each floating tip registers the element it
// describes here. While any tip is up, one animation-frame loop follows its anchor: the tip takes on the anchor's
// effective opacity (so it fades with a dying or fading card), and it closes the moment the anchor is removed from
// the page, hidden (display/visibility/opacity 0, or inside a hidden parent) or shrunk to nothing. Tips that close
// normally just stop being tracked. See docs/card-object-audit-2026-10-11.md.
const TipWatch = (()=>{
  const live = new Map(); let raf = 0;
  const effOpacity = el=>{ let o = 1; for(let n = el; n && n.nodeType === 1 && o > 0.01; n = n.parentElement) o *= Number(getComputedStyle(n).opacity); return o; };
  function gone(a){
    if(!a || !a.isConnected) return true;
    if(a.checkVisibility && !a.checkVisibility({visibilityProperty:true})) return true;
    const r = a.getBoundingClientRect(); return !(r.width || r.height);
  }
  function tick(){
    raf = 0;
    live.forEach((rec, tip)=>{
      if(!tip.isConnected || tip.hidden){ tip.style.opacity = ''; live.delete(tip); return; }
      if(gone(rec.anchor)){ tip.style.opacity = ''; live.delete(tip); try{ rec.hide(); }catch(e){} return; }
      const o = effOpacity(rec.anchor);
      if(o < 0.03){ tip.style.opacity = ''; live.delete(tip); try{ rec.hide(); }catch(e){} return; }
      tip.style.opacity = o < 0.98 ? o.toFixed(2) : '';
    });
    if(live.size) raf = requestAnimationFrame(tick);
  }
  return {
    track(tip, anchor, hide){ if(!tip || !anchor) return; live.set(tip, {anchor, hide: hide || (()=>{ tip.hidden = true; })}); if(!raf) raf = requestAnimationFrame(tick); },
    release(tip){ if(tip){ live.delete(tip); tip.style.opacity = ''; } },
    count(){ return live.size; },
  };
})();
if(typeof window !== 'undefined') window.TipWatch = TipWatch;
function attachDelayedTooltip(el, text, delayMs){
  if(!el) return;
  delayMs = delayMs==null ? 1000 : delayMs;
  let timer = null;
  const show = ()=>{
    timer = null;
    if(!el.isConnected) return; // re-rendered away while the timer ran
    if(!__delayedTooltipEl){
      __delayedTooltipEl = document.createElement('div');
      __delayedTooltipEl.className = 'tab-hover-tip';
      document.body.appendChild(__delayedTooltipEl);
    }
    __delayedTooltipEl.textContent = text;
    __delayedTooltipEl.hidden = false;
    const r = el.getBoundingClientRect();
    __delayedTooltipEl.style.left = (r.left + r.width/2) + 'px';
    __delayedTooltipEl.style.top = (r.bottom + 8) + 'px';
    TipWatch.track(__delayedTooltipEl, el, hide);
  };
  const hide = ()=>{ if(timer){ clearTimeout(timer); timer=null; } if(__delayedTooltipEl) __delayedTooltipEl.hidden = true; };
  el.addEventListener('mouseenter', ()=>{ timer = setTimeout(show, delayMs); });
  el.addEventListener('mouseleave', hide);
  el.addEventListener('mousedown', hide); // clicking the button shouldn't leave a stale tooltip up
}
// Tiered hover reveal (2026-09-30, queued backlog item: "Deck hover reveal (cards-remaining
// count) + a general 'hold Shift to reveal 2nd-tier info' convention, applied to the deck first
// and meant to generalize to other hidden-info spots"). Piloted on the in-match deck pile (see
// wireDeckHoverReveal below) but deliberately generic here — content comes from two callbacks, not
// anything deck-specific — so any other hidden-info spot can adopt the exact same convention later
// just by calling this with its own tier1/tier2 builders. Tier 1 shows on a plain hover, same as
// attachDelayedTooltip above but instant (no delay -- this is meant to feel like a quick glance,
// not a "wait for it" explainer); tier 2 replaces it live, for as long as Shift stays held, without
// needing to re-hover -- pressing/releasing Shift mid-hover swaps the content immediately via the
// shared keydown/keyup listeners below, not just at the moment the pointer first arrives.
let __tieredHoverEl = null;
let __tieredHoverShiftHeld = false;
let __tieredHoverActiveRefresh = null; // the currently-hovered element's own refresh fn, or null when nothing's hovered -- lets the one shared Shift listener below live-update whichever tiered tooltip (if any) is currently open
function __tieredHoverRefreshIfActive(){ if(__tieredHoverActiveRefresh) __tieredHoverActiveRefresh(); }
document.addEventListener('keydown', e=>{ if(e.key==='Shift'){ __tieredHoverShiftHeld = true; __tieredHoverRefreshIfActive(); } });
document.addEventListener('keyup', e=>{ if(e.key==='Shift'){ __tieredHoverShiftHeld = false; __tieredHoverRefreshIfActive(); } });
window.addEventListener('blur', ()=>{ __tieredHoverShiftHeld = false; __tieredHoverRefreshIfActive(); }); // an Alt-Tab mid-hold shouldn't leave this stuck thinking Shift is still down -- same guard wireDebugBar's own Shift-hold tracking uses, at the top of this file
function attachTieredHoverReveal(el, tier1Fn, tier2Fn){
  if(!el) return;
  const refresh = ()=>{
    if(!__tieredHoverEl){
      __tieredHoverEl = document.createElement('div');
      __tieredHoverEl.className = 'tiered-hover-tip conquest-tooltip'; // reuses the Conquest map tooltip's panel look (surface/border/radius/shadow) rather than inventing a third tooltip skin
      document.body.appendChild(__tieredHoverEl);
    }
    __tieredHoverEl.innerHTML = (__tieredHoverShiftHeld ? tier2Fn : tier1Fn)();
    __tieredHoverEl.hidden = false;
    const r = el.getBoundingClientRect();
    __tieredHoverEl.style.left = (r.left + r.width/2) + 'px';
    __tieredHoverEl.style.top = (r.top - 10) + 'px';
    TipWatch.track(__tieredHoverEl, el, hide);
  };
  const hide = ()=>{ __tieredHoverActiveRefresh = null; if(__tieredHoverEl) __tieredHoverEl.hidden = true; };
  el.addEventListener('mouseenter', ()=>{ __tieredHoverActiveRefresh = refresh; refresh(); });
  el.addEventListener('mouseleave', hide);
}
// The deck hover reveal's tier-2 content (see wireDeckHoverReveal in renderMatchUI): a player's
// `deck` field is a flat array of plain defId strings (see newPlayer/buildDeckIdsFrom in
// bramblewood-engine.js) -- grouped here into counts, sorted by how many copies remain (most
// first, so "what do I still have the most of" reads at a glance), name as the tiebreak.
function deckBreakdownHTML(deckIds, defs){
  const counts = {};
  deckIds.forEach(id=>{ counts[id] = (counts[id]||0)+1; });
  const rows = Object.entries(counts).map(([id,n])=>{
    const d = defs[id];
    return { name: (d&&d.name)||id, icon: (d&&d.icon)||'❔', n };
  }).sort((a,b)=> b.n-a.n || a.name.localeCompare(b.name));
  if(!rows.length) return `<div class="dht-empty">Deck is empty.</div>`;
  return `<div class="dht-list">${rows.map(r=>`<div class="dht-row"><span class="dht-ico">${r.icon}</span><span class="dht-name">${escapeHtml(r.name)}</span><span class="dht-n">×${r.n}</span></div>`).join('')}</div>`;
}
