// Item #11 (2026-09-18): "The drag and drop works also by dragging a card into the deck list
// section of build your deck." — pool tiles were already made draggable for item #10's leader
// slot; dropping one onto #myDeckList now does the same thing a click already does (add one
// copy), just via drag. Bound once here (not inside renderMyDeckPanels, which only replaces
// #myDeckList's innerHTML on every add/remove/filter change — the container node itself is
// never recreated, so a listener attached to it survives every one of those refreshes and
// re-binding on each would just stack duplicate handlers).
function wireDeckListDrop(){
  const listEl = document.getElementById('myDeckList');
  if(!listEl) return;
  listEl.addEventListener('dragover', e=>{ e.preventDefault(); listEl.classList.add('dragover'); });
  listEl.addEventListener('dragleave', ()=> listEl.classList.remove('dragover'));
  listEl.addEventListener('drop', e=>{
    e.preventDefault(); listEl.classList.remove('dragover');
    const defId = e.dataTransfer.getData('text/plain');
    const defs = getCardDefs();
    if(!defId || !defs[defId] || defs[defId].locked) return;
    // Same rarity copy-limit enforcement as the click/tap path (deckCardClick) -- this drop
    // handler bypasses that function entirely, so it needs its own identical check.
    if(editionCapReached(myDeckCounts, defId, defs) || defId === myLeaderId){ // a leader can't also sit in the deck (2026-10-12)
      denyShake(listEl);
      try{ fxHook('deckFull', listEl); }catch(e){} // 2026-10-15 batch F
      return;
    }
    myDeckCounts[defId] = (myDeckCounts[defId]||0) + 1;
    saveMyDeck();
    renderMyDeckPanels();
  });
}
// Item #10: wires the leader slot's dragover/drop + clear button. Called once from
// renderPlayerSubTab (the slot itself lives in its own #leaderSlotWrap, outside the
// #myDeckList/#myDeckPool nodes that renderMyDeckPanels regenerates on every add/remove/filter
// click, so it doesn't need re-wiring on every one of those refreshes).
function wireLeaderSlot(){
  const wrap = document.getElementById('leaderSlotWrap');
  if(!wrap) return;
  const slot = document.getElementById('leaderSlot');
  if(!slot) return;
  slot.addEventListener('dragover', e=>{ e.preventDefault(); slot.classList.add('dragover'); });
  slot.addEventListener('dragleave', ()=> slot.classList.remove('dragover'));
  slot.addEventListener('drop', e=>{
    e.preventDefault(); slot.classList.remove('dragover');
    const defId = e.dataTransfer.getData('text/plain');
    const defs = getCardDefs();
    if(!defId || !defs[defId]) return;
    if(!canLeadDef(defs[defId])){ showToast(TX('toast.leaders-must-be-heroic-or-above'), 'error'); try{ denyShake(slot); }catch(_){} return; }
    myLeaderId = defId; saveMyLeader();
    wrap.innerHTML = leaderSlotHTML();
    wireLeaderSlot();
    refreshDeckHeroBanner();
    try{ fxHook('deckHeroBanner', document.getElementById('deckHeroBanner')); }catch(e){} // 2026-10-15 batch F: a new leader takes the banner
  });
  const clearBtn = document.getElementById('leaderClearBtn');
  if(clearBtn) clearBtn.addEventListener('click', ()=>{
    myLeaderId = null; saveMyLeader();
    wrap.innerHTML = leaderSlotHTML();
    wireLeaderSlot();
    refreshDeckHeroBanner();
  });
}
// The fleshed-out stats subpage itself. Beyond the original played/wins/losses/draws/win-rate,
// this adds: current streak (win or loss) + best win streak, a Conquest campaign progress
// readout (nodes cleared / total, maps fully cleared), how many Raid Bosses have been
// permanently unlocked, and a quick readout of the current loadout (Bramble + deck size) so the
// whole page reads as an actual "profile" rather than four numbers in a row.
function renderPlayerStatsSubpage(body){
  const s = loadMatchStats();
  const winPct = s.played ? Math.round((s.wins/s.played)*100) : 0;
  const progress = ensureTutorialMarkersComplete(loadConquestProgress());
  // Tutorial marker nodes (0-1/0-2) are virtual, not real progress — excluded here same as
  // everywhere else that counts "real" Conquest nodes (isMapUnlocked, flattenConquestNodes, etc.)
  const allNodes = CONQUEST_MAPS.flatMap(m=>m.nodes).filter(n=>n.kind!=='tutorial');
  const totalNodes = allNodes.length;
  // Tutorial marker ids (auto-added by ensureTutorialMarkersComplete above) are excluded from
  // this count too, so "cleared / total" only ever counts real fights on both sides of the ratio.
  const tutorialIds = CONQUEST_MAPS.flatMap(m=> m.nodes.filter(n=>n.kind==='tutorial').map(n=> conquestNodeId(m.id, n.key)));
  const clearedNodes = progress.completed.filter(id=> !tutorialIds.includes(id)).length;
  const mapsFullyCleared = CONQUEST_MAPS.filter(m=> m.nodes.some(n=> n.kind!=='tutorial') && m.nodes.filter(n=>n.kind!=='tutorial').every(n=> progress.completed.includes(conquestNodeId(m.id, n.key)))).length; // 2026-10-12: a map with no fights isn't "cleared"
  const raidBossesTotal = allNodes.filter(n=>n.kind==='raidboss').length;
  const raidBossesUnlocked = progress.raidUnlocked.length;
  const bramble = CHARACTER_DEFS[myCharacterId] || CHARACTER_DEFS['castle'];
  const streakLabel = s.curStreak>0 ? `${s.curStreak} ${s.curStreakType==='win'?'🔥 Win':'💧 Loss'} streak` : '—';
  body.innerHTML = `
    <div class="panel">
      <h2>📊 Player Stats</h2><p class="panel-sub">Tracked locally in your browser, across all vs-AI matches.</p>
      <div class="player-stats-row">
        <div class="stat-box"><div class="stat-num">${s.played}</div><div class="stat-lbl">Matches</div></div>
        <div class="stat-box"><div class="stat-num">${s.wins}</div><div class="stat-lbl">Wins</div></div>
        <div class="stat-box"><div class="stat-num">${s.losses}</div><div class="stat-lbl">Losses</div></div>
        <div class="stat-box"><div class="stat-num">${s.draws}</div><div class="stat-lbl">Draws</div></div>
        <div class="stat-box"><div class="stat-num">${winPct}%</div><div class="stat-lbl">Win rate</div></div>
      </div>
      <div class="player-stats-row">
        <div class="stat-box"><div class="stat-num">${streakLabel}</div><div class="stat-lbl">Current streak</div></div>
        <div class="stat-box"><div class="stat-num">${s.bestWinStreak}</div><div class="stat-lbl">Best win streak</div></div>
      </div>
    </div>
    <div class="panel">
      <h2>🗺️ Conquest Progress</h2>
      <div class="player-stats-row">
        <div class="stat-box"><div class="stat-num">${clearedNodes}/${totalNodes}</div><div class="stat-lbl">Nodes cleared</div></div>
        <div class="stat-box"><div class="stat-num">${mapsFullyCleared}/${CONQUEST_MAPS.length}</div><div class="stat-lbl">Maps fully cleared</div></div>
        <div class="stat-box"><div class="stat-num">${raidBossesUnlocked}/${raidBossesTotal}</div><div class="stat-lbl">Raid Bosses unlocked</div></div>
      </div>
    </div>
    <div class="panel">
      <h2>🌿 Current Loadout</h2>
      <div class="player-stats-row">
        <div class="stat-box"><div class="stat-num">${bramble.icon} ${bramble.name}</div><div class="stat-lbl">Bramble</div></div>
        <div class="stat-box"><div class="stat-num">${deckTotal(myDeckCounts)}/${DECK_SIZE}</div><div class="stat-lbl">Deck size</div></div>
      </div>
    </div>
    <div class="panel" style="text-align:center; display:flex; gap:10px; justify-content:center;">
      <button class="btn" id="statsBackBtn">← Back</button>
      <button class="btn ghost" id="statsExitBtn">Exit</button>
    </div>`;
  document.getElementById('statsBackBtn').addEventListener('click', ()=>{ playerStatsOpen = false; renderPlay(); });
  document.getElementById('statsExitBtn').addEventListener('click', goHome);
}
// Gauntlet (#274, 2026-09-25 — the "Async Arena (until 10 wins)" you described, built under a
// NEW name instead of overloading the existing Async Arena feature above, which already means
// something different: "a paused vs-AI match you can resume later." Gauntlet is a back-to-back
// win-streak run against the existing vs-AI engine (startMatch('gauntlet') below reuses the exact
// same randomAiDeck() opponent as ordinary Arena "vs AI") — win and the streak climbs with a
// growing reward each fight; lose and it resets to 0; reach GAUNTLET_GOAL wins in a row and the
// run pays out a bonus and resets, ready to start again. Tracked locally (like Async Arena's own
// save state) — not yet synced to the cloud profile, same known-gap flagged on a few other
// recently-shipped local-only features (Achievements' claimed state, Prestige tiers).
const GAUNTLET_GOAL = 10;
const GAUNTLET_STREAK_KEY = 'bramblewood_gauntlet_streak_v1';
const GAUNTLET_BEST_KEY = 'bramblewood_gauntlet_best_v1';
function loadGauntletStreak(){ try{ return Number(localStorage.getItem(GAUNTLET_STREAK_KEY))||0; }catch(e){ return 0; } }
function saveGauntletStreak(n){ try{ localStorage.setItem(GAUNTLET_STREAK_KEY, String(n)); }catch(e){} }
function loadGauntletBest(){ try{ return Number(localStorage.getItem(GAUNTLET_BEST_KEY))||0; }catch(e){ return 0; } }
function saveGauntletBest(n){ try{ localStorage.setItem(GAUNTLET_BEST_KEY, String(n)); }catch(e){} }

// ============================================================================================
// Dungeon (2026-09-26, per explicit request: "a new concept called dungeon! You fight 3 enemies
// in a row. These will appear as dark grey skirmishes. typically they are not compulsory. The
// loss is that: cards that died and hp your castle lost is permanent") — the deliberate MIRROR
// of Gauntlet just above: Gauntlet is an open-ended win streak where every single fight is a
// clean full reset (fresh AI deck, full-health Castle) and only the STREAK NUMBER persists
// between fights; Dungeon is exactly 3 fights where the opposite is true — the streak doesn't
// matter (there's no "keep going past 3"), but the Castle's current HP and the player's own deck
// carry forward, battered, from one fight into the next. That's the entire design: a short,
// optional ("typically not compulsory" — it lives as its own card on the Arena screen, next to
// Test Battle/Gauntlet, gating nothing on the main Conquest trail) higher-stakes side mode.
//
// "Cards that died" is read literally and narrowly: only a genuine combat death — the engine's
// own {type:'death', side:'A', defId} event in the just-finished fight's m.log — permanently
// trims a copy from the run's saved deck. Discarding/pitching a card for its resource (a normal,
// constant, fully-intentional economy action in every match, dungeon or not) pushes its own
// distinct {type:'discard', ...} event and is deliberately NOT touched — treating every pitch as
// a permanent loss would make a Dungeon run unplayable by Fight 2, since pitching is something a
// normal turn does routinely, not a mistake or a risk.
//
// Enemy difficulty escalates a little each stage (DUNGEON_ENEMY_HQ_HP) purely via the same
// {id,name,health,effects} placeholder-character shape Conquest's own enemy nodes already use —
// no new opponent-deck content needed, since Fight 1-3 all draw the same randomAiDeck() pool
// Gauntlet/Test Battle already use; only the enemy Castle's HP pool grows.
//
// Run state persists to localStorage (mirroring ENERGY_KEY's {current,...} object pattern, not
// Gauntlet's bare number) since "stage 2 of 3, missing a Bee Knight, Castle at 14 HP" is real
// data that needs to survive the gap between one fight's matchState ending and the next one
// starting — and, same as Energy, survive a reload too rather than quietly resetting a run whose
// whole point is that its losses are meant to stick.
const DUNGEON_RUN_KEY = 'bramblewood_dungeon_run_v1';
const DUNGEON_STAGE_COUNT = 3;
const DUNGEON_ENEMY_HQ_HP = [22, 28, 36]; // escalating per stage — a deliberate design choice (not spec'd explicitly) so 3 fights in a row actually feel like they're getting harder
function loadDungeonRun(){
  try{
    const raw = localStorage.getItem(DUNGEON_RUN_KEY);
    if(!raw) return null;
    const parsed = JSON.parse(raw);
    if(!parsed || typeof parsed.deckCounts!=='object' || !(parsed.stage>=1)) return null;
    return parsed;
  }catch(e){ return null; }
}
function saveDungeonRun(run){ try{ localStorage.setItem(DUNGEON_RUN_KEY, JSON.stringify(run)); }catch(e){} }
function clearDungeonRun(){ try{ localStorage.removeItem(DUNGEON_RUN_KEY); }catch(e){} }
function dungeonDeckCount(run){ return Object.values(run.deckCounts).reduce((a,b)=>a+b, 0); }
function startDungeonFight(){
  let run = loadDungeonRun();
  if(!run){
    // A brand-new run always starts from your real, currently-built deck — the one and only
    // point a Dungeon run ever reads myDeckCounts directly, so it has to be the normal valid
    // 20-card deck (same gate startMatch() itself uses) before Fight 1 can begin. Every later
    // fight in this same run reads the attritioned copy saved in DUNGEON_RUN_KEY instead, which
    // is allowed to have fewer than 20 cards left — that shrinkage IS the mode.
    if(deckTotal(myDeckCounts)!==DECK_SIZE){
      showToast(TX('toast.your-main-deck-has-cards-it', {v1: deckTotal(myDeckCounts), DECK_SIZE}), 'warn');
      return;
    }
    run = {stage:1, deckCounts:{...myDeckCounts}, castleHp:null};
    saveDungeonRun(run);
  }
  const engine = makeSimEngine(getCardDefs(), nextMatchRng(), {recordEvents:true, battleMode:'open'});
  const sideOf = id=> id===1?'A':'B';
  const myCharacter = myCastleDef();
  const hqHp = DUNGEON_ENEMY_HQ_HP[Math.min(run.stage-1, DUNGEON_ENEMY_HQ_HP.length-1)];
  const enemyCharacter = {id:'dungeon-enemy', name:`Dungeon Foe ${run.stage}`, health:hqHp, effects:{}};
  const players = {
    1: engine.newPlayer(1, run.deckCounts, myCharacter),
    2: engine.newPlayer(2, randomAiDeck(), enemyCharacter),
  };
  // The whole point: Fight 2/3 start with whatever Castle HP Fight 1/2 ended on, not a fresh
  // full bar. Stage 1 (castleHp still null) keeps the character's real, full HP untouched.
  if(run.castleHp!=null) players[1].hq.hp = Math.max(1, Math.min(run.castleHp, players[1].hq.maxHp));
  const deckTotals = {1: players[1].deck.length, 2: players[2].deck.length};
  const stats = {};
  engine.draw(players[1], 3, 'A', stats, []);
  engine.draw(players[2], 3, 'B', stats, []);
  matchState = {engine, players, sideOf, stats, over:false, winner:0, selectedUid:null, log:[], round:1, resolving:false,
    mode:'dungeon', active:1, turnDone:{1:false,2:false}, awaitingPass:false, deckTotals, speedMult:1,
    dungeonStage: run.stage,
    leaderDefId: matchLeaderId(), leaderUid: null};
  lastBoardSig = {1:null, 2:null};
  knownBoardUids = new Set();
  renderPlay();
}
// ============================================================================================
// Ranked 1v1 Live (#277, 2026-09-25) — real-time two-device PvP, matched by rating.
//
// WHY HOST-AUTHORITATIVE: every other multiplayer-shaped mode in this app ('pc' hot-seat, 'ai')
// runs ONE engine instance locally and trusts it completely, because there's only ever one
// Math.random() stream in play. A real match between two different browsers can't do that —
// deck shuffling (buildDeckIdsFrom) and every combat roll (crits, etc.) would diverge between
// the two clients within a turn or two if both ran their own copy of the engine off their own
// local RNG. So exactly ONE client — the HOST (always seat 1; see find_ranked_match's RPC,
// which always inserts the host as player1) — ever calls a real m.engine.* mutator. The PEER
// (always seat 2) never mutates locally at all: every one of their taps/drags becomes a small
// "intent" message sent over a per-match Supabase Realtime broadcast channel, which the host
// replays through the SAME action-entry functions its own UI uses (playCardByUid/
// discardCardByUid/skipTurn/attemptSummonLeader) — see replayLiveIntent() below. Those four
// functions already resolve "who is this action for" via activePlayerId(m) rather than a
// passed-in pid, which is exactly what makes this replay-by-direct-call trick work with zero
// duplicated game logic: as long as m.active correctly points at the peer's seat when their
// intent arrives (guaranteed — the peer's own client already only *sends* an intent when it's
// genuinely their turn), calling playCardByUid(...) on the host attributes the mutation to the
// peer's seat automatically.
//
// KNOWN V1 LIMITATIONS (deliberately scoped out — flagged here AND in the roadmap, not hidden):
//   1. Hand-visibility isn't cryptographically enforced. broadcastLiveState() below sends the
//      HOST'S FULL players[] object (both seats' hands) to the shared channel — the UI never
//      renders your opponent's hand (viewerHandPid() gates that), but a technically-inclined
//      opponent inspecting network traffic/devtools could read it anyway. Closing that gap for
//      real needs a server-side authoritative engine (an Edge Function) that only ever sends
//      each viewer their OWN redacted state — a real follow-up project, not a quick fix.
//   2. The board camera is NOT mirrored per viewer — see renderMatchUI's isLiveRanked comment.
//      Both clients render seat 1 in the bottom "mine" row / seat 2 in the top "enemy" row; the
//      peer's own board ends up up top. Labels are correct either way ("You"/"Opponent" always
//      names the row that's actually yours), just visually unconventional for the peer.
//   3. The peer never sees combat ANIMATED — applyLiveStateSnapshot() is an instant cut to
//      whatever the host just broadcast, not a replayed, paced event log the way the host's own
//      local resolveRound() plays out. The peer's screen effectively jumps straight to each
//      round's result.
//   4. No leader-summon support (m.leaderDefId is left null for both seats) and no reconnect-
//      after-disconnect handling — a dropped peer connection currently just stalls; either side
//      leaving cleanly (the Quit button) is the only handled exit path.
//   5. Matchmaking (find_ranked_match RPC) is a simple poll-and-pair, not a true real-time push —
//      each queued client re-checks every ~2.2s rather than being notified the instant a match
//      forms, so pairing can lag by a couple of seconds even when an opponent is already waiting.
// None of this could be verified against a real second client in this sandbox (no network
// egress to the live Supabase project here) — built per your own call to "build it now, test
// once deployed" rather than block on that.
// ============================================================================================
let liveQueueing = false;
let liveQueuePollTimer = null;
let liveMatchSub = null; // the active match's Realtime channel object, once matched

function renderArenaSubTabIfOpen(){
  if(document.getElementById('playSubBody') && playSubTab==='arena' && !matchState) renderArenaSubTab(document.getElementById('playSubBody'));
}

async function findLiveRankedMatch(){
  if(!sbClient || !isSignedIn()){
    requireSignIn('to queue for Ranked 1v1 Live', ()=> findLiveRankedMatch());
    return;
  }
  if(deckTotal(myDeckCounts)!==DECK_SIZE){
    showToast(TX('toast.your-main-deck-has-cards-it-2', {v1: deckTotal(myDeckCounts), DECK_SIZE}), 'warn');
    return;
  }
  liveQueueing = true;
  renderArenaSubTabIfOpen();
  pollLiveQueue();
}

async function pollLiveQueue(){
  if(!liveQueueing) return;
  try{
    const { data, error } = await sbClient.rpc('find_ranked_match', {
      p_rating: myRating, p_deck: publicDeck(myDeckCounts), p_character: myCharacterId, p_leader: matchLeaderId() || null,
    });
    if(error){ console.warn('find_ranked_match error', error); }
    else if(data){ await enterLiveMatch(data); return; } // matched — stop polling
  }catch(e){ console.warn('find_ranked_match threw', e); }
  if(liveQueueing) liveQueuePollTimer = setTimeout(pollLiveQueue, 2200);
}

function cancelLiveRankedQueue(){
  liveQueueing = false;
  if(liveQueuePollTimer){ clearTimeout(liveQueuePollTimer); liveQueuePollTimer = null; }
  if(sbClient) sbClient.rpc('cancel_ranked_queue', {}).then(()=>{}, ()=>{});
  renderArenaSubTabIfOpen();
}

async function enterLiveMatch(row){
  liveQueueing = false;
  if(liveQueuePollTimer){ clearTimeout(liveQueuePollTimer); liveQueuePollTimer = null; }
  const mySeat = row.player1_id===cloudUserId ? 1 : 2;
  const oppId = mySeat===1 ? row.player2_id : row.player1_id;
  const oppRating = Number(mySeat===1 ? row.player2_rating : row.player1_rating) || 1500;
  const oppDeck = mySeat===1 ? row.player2_deck : row.player1_deck;
  const oppCharacter = mySeat===1 ? row.player2_character : row.player1_character;
  const role = row.host_id===cloudUserId ? 'host' : 'peer';
  let oppName = 'Opponent';
  try{
    const { data: oppProfile } = await sbClient.from('profiles').select('display_name').eq('id', oppId).maybeSingle();
    if(oppProfile && oppProfile.display_name) oppName = oppProfile.display_name;
  }catch(e){ /* non-fatal — the generic "Opponent" label is fine */ }
  const settings = row.settings || {};
  // D74 (closed 2026-10-14): Ranked Live plays Standard, every card at Level 1, so levels bought or ground out don't decide a
  // ranked game. Both players run this same rule, so they stay in step. Friendly invites keep the format they chose.
  const isStd = settings.format==='standard' || row.ranked !== false;
  standardMatchActive = isStd; _stdDefsCache = null;
  startLiveRankedMatch({ standard: isStd,
    friendly: row.ranked===false, battleMode: Registry.battleMode(settings.battleMode) ? settings.battleMode : Registry.defaultBattleMode(),
    matchId: row.id, role, mySeat, oppId, oppRating, oppName,
    myDeck: settings.format==='standard' ? loadStandardDeck() : myDeckCounts, myCharacter: myCharacterId, // the deck you queued with is the one your opponent sees
    oppDeck: oppDeck || {}, oppCharacter: oppCharacter || 'castle',
  });
}

function startLiveRankedMatch(cfg){
  cfg = Object.assign({}, cfg, {myDeck: publicDeck(cfg.myDeck), oppDeck: publicDeck(cfg.oppDeck)});
  const engine = makeSimEngine(getCardDefs(), nextMatchRng(), {recordEvents:true, battleMode: cfg.battleMode || Registry.defaultBattleMode()});
  const sideOf = id=> id===1?'A':'B';
  const p1Deck = cfg.mySeat===1 ? cfg.myDeck : cfg.oppDeck;
  const p2Deck = cfg.mySeat===1 ? cfg.oppDeck : cfg.myDeck;
  const p1Character = CHARACTER_DEFS[cfg.mySeat===1 ? cfg.myCharacter : cfg.oppCharacter] || CHARACTER_DEFS['castle'];
  const p2Character = CHARACTER_DEFS[cfg.mySeat===1 ? cfg.oppCharacter : cfg.myCharacter] || CHARACTER_DEFS['castle'];
  const players = { 1: engine.newPlayer(1, p1Deck, p1Character), 2: engine.newPlayer(2, p2Deck, p2Character) };
  const deckTotals = {1: players[1].deck.length, 2: players[2].deck.length};
  const stats = {};
  // Only the HOST actually draws opening hands — see the module header comment on why only one
  // client may ever touch Math.random() here. The peer starts with an empty mirror and waits
  // for the host's first broadcastLiveState() call, right below, to fill it in.
  if(cfg.role==='host'){
    engine.draw(players[1], 3, 'A', stats, []);
    engine.draw(players[2], 3, 'B', stats, []);
  }
  matchState = {
    engine, players, sideOf, stats, over:false, winner:0, selectedUid:null, log:[], round:1, resolving:false,
    mode:'liveRanked', active:1, turnDone:{1:false,2:false}, awaitingPass:false, deckTotals, speedMult:1,
    leaderDefId:null, leaderUid:null, // leader-summon isn't wired up for a real 2-player match yet — see module header, limitation #4
    liveMatchId: cfg.matchId, liveRole: cfg.role, liveMySeat: cfg.mySeat, liveOpponentId: cfg.oppId,
    liveOpponentRating: cfg.oppRating, liveOpponentName: cfg.oppName, liveReplaying: false,
    liveFriendly: !!cfg.friendly, battleMode: cfg.battleMode || Registry.defaultBattleMode(), standard: !!cfg.standard,
  };
  lastBoardSig = {1:null, 2:null};
  knownBoardUids = new Set();
  liveMatchSub = liveMatchChannel(cfg.matchId);
  renderPlay();
  if(cfg.role==='host') broadcastLiveState(); // gives the peer its first real snapshot (opening hands, etc.)
}

function liveMatchChannel(matchId){
  if(!sbClient) return null;
  const ch = sbClient.channel('live-match-'+matchId, {config:{broadcast:{self:false}}});
  ch.on('broadcast', {event:'intent'}, ({payload})=>{ replayLiveIntent(payload); });
  ch.on('broadcast', {event:'state'}, ({payload})=>{ applyLiveStateSnapshot(payload); });
  ch.on('broadcast', {event:'abandon'}, ()=>{ handlePeerAbandoned(); });
  ch.subscribe();
  return ch;
}

function sendLiveIntent(intent){
  if(!liveMatchSub) return;
  liveMatchSub.send({type:'broadcast', event:'intent', payload: intent});
}

// Host-only: replays a peer's relayed intent by calling the exact same action-entry function
// the host's own UI uses — see the module header for why this is safe and correct. m.liveReplaying
// suspends the "is it actually my own turn" guard those functions carry (see their own liveRanked
// branches) for the duration of this one call, since a replay is legitimately acting on the
// PEER's behalf, not the host's own.
async function replayLiveIntent(intent){
  const m = matchState;
  if(!m || m.mode!=='liveRanked' || m.liveRole!=='host' || !intent) return;
  if(activePlayerId(m) !== intent.fromSeat){ broadcastLiveState(); return; } // stale/out-of-turn intent (e.g. a race with a state broadcast already in flight) — drop it silently rather than risk misattributing an action
  m.liveReplaying = true;
  try{
    if(intent.type==='playCard') await playCardByUid(intent.uid, intent.side, intent.dropPoint);
    else if(intent.type==='discardCard') await discardCardByUid(intent.uid);
    else if(intent.type==='skipTurn') await skipTurn();
    else if(intent.type==='summonLeader') await attemptSummonLeader(intent.preferredLane);
  } finally { m.liveReplaying = false; }
  // Always resync the peer after handling one of its intents — including a no-op/rejected one —
  // so its mirror can never drift into re-sending an action the host already applied.
  broadcastLiveState();
}

// Host-only: broadcasts the full, authoritative match state to the peer. See module header
// limitation #1 for why this is NOT redacted (the peer's own hand data rides along even though
// the UI never shows it) and limitation #3 for why the peer receives this as an instant cut,
// not a paced replay.
function broadcastLiveState(){
  const m = matchState;
  if(!m || m.mode!=='liveRanked' || m.liveRole!=='host' || !liveMatchSub) return;
  liveMatchSub.send({type:'broadcast', event:'state', payload: {
    players: m.players, stats: m.stats, log: m.log, round: m.round,
    active: m.active, turnDone: m.turnDone, over: m.over, winner: m.winner, deckTotals: m.deckTotals,
  }});
}

// Peer-only: applies a host-broadcast snapshot wholesale. Not a diff/merge — the peer has no
// local engine state of its own to reconcile against (it never mutates locally at all), so
// every field the host sends simply replaces this client's mirror.
function applyLiveStateSnapshot(snapshot){
  const m = matchState;
  if(!m || m.mode!=='liveRanked' || m.liveRole!=='peer' || !snapshot) return;
  m.players = snapshot.players; m.stats = snapshot.stats || {}; m.log = snapshot.log || [];
  m.round = snapshot.round || m.round; m.active = snapshot.active || m.active;
  m.turnDone = snapshot.turnDone || m.turnDone; m.over = !!snapshot.over; m.winner = snapshot.winner || 0;
  m.deckTotals = snapshot.deckTotals || m.deckTotals;
  lastBoardSig = {1:null, 2:null}; // force a full re-render rather than a diffed one
  renderPlay();
}

function handlePeerAbandoned(){
  const m = matchState;
  if(!m || m.mode!=='liveRanked' || m.over) return;
  alert(TX('dialog.your-opponent-left-the-match'));
  cleanupLiveMatch();
  matchState = null;
  renderPlay();
}
function leaveLiveMatch(){
  const m = matchState;
  if(m && m.mode==='liveRanked' && !m.over){
    if(liveMatchSub) liveMatchSub.send({type:'broadcast', event:'abandon', payload:{}});
    if(sbClient && m.liveMatchId) sbClient.rpc('abandon_live_match', {p_match_id: m.liveMatchId}).then(()=>{}, ()=>{});
  }
  cleanupLiveMatch();
}
function cleanupLiveMatch(){
  if(liveMatchSub){ try{ sbClient.removeChannel(liveMatchSub); }catch(e){} liveMatchSub = null; }
}

// ---- Async Arena runs vs ghost decks (2026-10-03) — see bramblewood-ghosts.js for the model:
// a run is up to 7 wins (ends at 3 losses); at each win stage you fight a ghost of a deck that
// reached the same stage. Recorded ghosts live in this browser for now (offline); a cloud table
// can feed the same pool later without changing the rules.
const ASYNC_RUN_KEY = 'bramblewood_async_run_v1';
const ASYNC_GHOSTS_KEY = 'bramblewood_async_ghosts_v1';
const Ghosts = (typeof BramblewoodGhosts!=='undefined') ? BramblewoodGhosts : null;
function loadAsyncRun(){ try{ const r = JSON.parse(localStorage.getItem(ASYNC_RUN_KEY)||'null'); return r && typeof r.wins==='number' ? r : null; }catch(e){ return null; } }
function saveAsyncRun(r){ try{ if(r) localStorage.setItem(ASYNC_RUN_KEY, JSON.stringify(r)); else localStorage.removeItem(ASYNC_RUN_KEY); }catch(e){} }
function loadAsyncGhosts(){ try{ return JSON.parse(localStorage.getItem(ASYNC_GHOSTS_KEY)||'[]') || []; }catch(e){ return []; } }
function saveAsyncGhosts(list){ try{ localStorage.setItem(ASYNC_GHOSTS_KEY, JSON.stringify(list)); }catch(e){} }
function myGhostOwnerId(){ return cloudUserId || 'local-player'; }
function asyncStagePool(stage){
  // Your own recorded decks never come back as your opponent.
  const rec = loadAsyncGhosts().filter(g=> g.owner!==myGhostOwnerId());
  return Ghosts.buildStagePool(getCardDefs(), stage, rec, Date.now());
}
function asyncRunSummaryHTML(){
  if(!Ghosts) return '';
  const run = loadAsyncRun();
  const stage = run ? run.wins : 0;
  const pool = asyncStagePool(stage);
  return `<span class="async-run-line">${run ? `Run: <b>${run.wins}W–${run.losses}L</b> · Stage ${stage+1}/${Ghosts.ASYNC.MAX_WINS}` : `New run · up to ${Ghosts.ASYNC.MAX_WINS} wins, ${Ghosts.ASYNC.MAX_LOSSES} losses ends it`} · ${pool.active} decks at this stage</span>`;
}
// Called from resolveRound's over-branch for mode 'async'.
function settleAsyncRunAfterMatch(m){
  if(!Ghosts) return;
  const run = loadAsyncRun() || Ghosts.newAsyncRun(Date.now());
  const won = m.winner===1;
  const stage = (m.asyncStage!=null) ? m.asyncStage : run.wins;
  if(won){
    run.wins++;
    saveAsyncGhosts(Ghosts.recordAsyncGhost(loadAsyncGhosts(), {owner: myGhostOwnerId(), name: (myProfile && myProfile.name) || 'You', avatar: loadAvatar(), deck: Object.assign({}, myDeckCounts), stage, at: Date.now(), source:'player'}));
    const g = 12 + stage*6, d = 2 + stage;
    grantCurrency('gold', g); grantCurrency('dust', d);
    m.asyncRewardEarned = {gold:g, dust:d};
  } else run.losses++;
  m.asyncRunAfter = {wins: run.wins, losses: run.losses};
  if(Ghosts.asyncRunOver(run)){
    if(run.wins >= Ghosts.ASYNC.MAX_WINS){ grantCurrency('gold', 150); grantCurrency('metal', 2); m.asyncRewardEarned = Object.assign({gold:0, dust:0}, m.asyncRewardEarned); m.asyncRewardEarned.gold += 150; m.asyncRewardEarned.metal = 2; }
    m.asyncRunComplete = true;
    saveAsyncRun(null);
  } else saveAsyncRun(run);
}
// ---- Live data (2026-10-03, explicit: "Cloud tables: it should be live, not in local") ----
// ghost_decks (PvP strangers + Autobattler runs), raid_week_attempts (the weekly raid party) and
// player_progress (your progress blob) — see supabase/migrations/20261003_live_ghosts_raid_progress.sql.
// Reads are public; writes need any session (guest sessions included). If the tables don't exist
// yet (migration not applied) or we're offline, everything quietly keeps working from this
// browser's own copies, exactly as before.
const LiveData = {available:null, ghosts:{pvp:[], autobattle:[]}, ghostsAt:{}, raid:{}, progressPushedHash:null};
const LIVE_GHOST_TTL_MS = 3*60*1000;
function liveCanWrite(){ return !!(sbClient && cloudUserId && LiveData.available!==false); }
function liveTableMissing(error){ return !!error && (/does not exist|schema cache|relation/i.test(error.message||'') || error.code==='42P01' || error.code==='PGRST205'); }
function liveRowToGhost(mode, r){
  const base = {owner: r.owner_id, name: r.display_name || 'Player', avatar: r.avatar || null, stage: r.stage, at: Date.parse(r.recorded_at)||0, source:'player'};
  return mode==='pvp' ? Object.assign(base, {deck: (r.payload||{}).deck || {}, rating: (r.payload||{}).rating, deckLevel: (r.payload||{}).deckLevel}) : Object.assign({}, r.payload||{}, base);
}
async function liveRefreshGhosts(mode, force){
  if(!sbClient || LiveData.available===false) return false;
  if(!force && LiveData.ghostsAt[mode] && Date.now() - LiveData.ghostsAt[mode] < LIVE_GHOST_TTL_MS) return false;
  LiveData.ghostsAt[mode] = Date.now();
  try{
    const since = new Date(Date.now() - 14*24*3600*1000).toISOString();
    const { data, error } = await sbClient.from('ghost_decks').select('owner_id, mode, stage, display_name, avatar, payload, recorded_at').eq('mode', mode).gte('recorded_at', since).order('recorded_at', {ascending:false}).limit(1500);
    if(error){ if(liveTableMissing(error)) LiveData.available = false; return false; }
    LiveData.available = true;
    LiveData.ghosts[mode] = (data||[]).map(r=> liveRowToGhost(mode, r));
    return true;
  }catch(e){ return false; }
}
function livePushGhost(mode, stage, payload){
  if(!liveCanWrite()) return;
  if(payload && payload.deck) payload = Object.assign({}, payload, {deck: publicDeck(payload.deck)});
  sbClient.from('ghost_decks').upsert({owner_id: cloudUserId, mode, stage, display_name: (myProfile && myProfile.name) || 'Player', avatar: loadAvatar(), payload, recorded_at: new Date().toISOString()}, {onConflict:'owner_id,mode,stage'})
    .then(({error})=>{ if(liveTableMissing(error)) LiveData.available = false; }, ()=>{});
}
async function liveRefreshRaid(bossId, cycle){
  if(!sbClient || LiveData.available===false) return false;
  const key = bossId+':'+cycle;
  const cur = LiveData.raid[key];
  if(cur && Date.now() - cur.at < 60*1000) return false;
  LiveData.raid[key] = {at: Date.now(), rows: cur ? cur.rows : []};
  try{
    const { data, error } = await sbClient.from('raid_week_attempts').select('owner_id, display_name, avatar, deck, damage, won, fought_at').eq('boss_id', bossId).eq('cycle', cycle).order('fought_at', {ascending:true}).limit(2000);
    if(error){ if(liveTableMissing(error)) LiveData.available = false; return false; }
    LiveData.available = true;
    LiveData.raid[key] = {at: Date.now(), rows: (data||[]).map(r=> ({bossId, cycle, owner: r.owner_id, name: r.display_name || 'Player', avatar: r.avatar, deck: r.deck, damage: r.damage, won: r.won, at: Date.parse(r.fought_at)||0, source:'player', live:true}))};
    return true;
  }catch(e){ return false; }
}
function livePushRaidAttempt(a, onDone){
  if(!liveCanWrite()){ onDone && onDone(false); return; }
  sbClient.from('raid_week_attempts').insert({boss_id: a.bossId, cycle: a.cycle, owner_id: cloudUserId, display_name: a.name, avatar: a.avatar, deck: publicDeck(a.deck), damage: Math.max(0, Math.min(10000, a.damage|0)), won: !!a.won})
    .then(({error})=>{ if(liveTableMissing(error)) LiveData.available = false; onDone && onDone(!error); }, ()=> onDone && onDone(false));
}
// Progress blob: these localStorage keys follow you across devices.
const PROGRESS_KEYS = ['bramblewood_conquest_progress_v1','bramblewood_arena_tutorial_done','bramblewood_arena_tutorial_stage','bramblewood_arena_faction',
  'bramblewood_quests_v1','bramblewood_lifetime_stats_v1','bramblewood_avatar','bramblewood_pvp_tickets_v1','bramblewood_ab_run_v1','bramblewood_hero_v1',
  'bramblewood_gauntlet_streak_v1','bramblewood_gauntlet_best_v1','bramblewood_dungeon_run_v1','bramblewood_player_xp_v1','bramblewood_raid_attempts_v1','bramblewood_dialogue_flags_v1','bramblewood_unlocks_v1',
  // 2026-10-03: discoveries (hidden-card sightings), raid part attempts + claims (so a reward can't be claimed twice on two devices), recent opponents
  'bramblewood_arena_discovered','bramblewood_raid_part_attempts_v1','bramblewood_raid_claims_v1','bramblewood_recent_opponents_v1',
  // 2026-10-07: optional personal details (hobby, birthday) — player_progress is readable only by its owner
  'bramblewood_personal_v1',
  // 2026-10-10: tutorial progress (level, side, guided step, tries), for Admin → Players
  'bramblewood_tutorial_progress_v1',
  // 2026-10-17 (card stats): your lifetime record per card (CARD_STATS_KEY; integers only, only cards with a record)
  'bramblewood_card_stats_v1'];
// Keys merged (union) on pull instead of overwritten, because both devices may have added to them.
const PROGRESS_MERGE_KEYS = {
  'bramblewood_arena_discovered': (a,b)=> JSON.stringify(Array.from(new Set([...(JSON.parse(a||'[]')||[]), ...(JSON.parse(b||'[]')||[])]))),
  'bramblewood_raid_claims_v1': (a,b)=> JSON.stringify(Object.assign({}, JSON.parse(a||'{}')||{}, JSON.parse(b||'{}')||{})),
  // 2026-10-17 (card stats): counts only ever grow, so the larger of the two copies wins, number by number (never added twice)
  'bramblewood_card_stats_v1': (a,b)=>{ const A = JSON.parse(a||'{}')||{}, B = JSON.parse(b||'{}')||{}, out = Object.assign({}, A);
    Object.keys(B).forEach(id=>{ const x = Array.isArray(A[id]) ? A[id] : [], y = Array.isArray(B[id]) ? B[id] : [], r = [];
      for(let i = 0; i < Math.max(x.length, y.length); i++) r[i] = Math.max(Number(x[i])||0, Number(y[i])||0);
      out[id] = cardStatsTrim(r); });
    return JSON.stringify(out); },
};
const PROGRESS_LOCAL_AT_KEY = 'bramblewood_progress_local_at';
function progressSnapshot(){ const d = {}; PROGRESS_KEYS.forEach(k=>{ try{ const v = localStorage.getItem(k); if(v!=null) d[k] = v; }catch(e){} }); return d; }
function snapshotHash(d){ return String(hashStr(JSON.stringify(d))); }
async function livePullProgress(){
  if(!sbClient || !cloudUserId || LiveData.available===false) return;
  try{
    const { data, error } = await sbClient.from('player_progress').select('data, updated_at').eq('profile_id', cloudUserId).maybeSingle();
    if(error){ if(liveTableMissing(error)) LiveData.available = false; return; }
    LiveData.available = true;
    const localAt = Number(localStorage.getItem(PROGRESS_LOCAL_AT_KEY)||0);
    if(data && data.data && Date.parse(data.updated_at) > localAt){
      Object.entries(data.data).forEach(([k,v])=>{ if(!PROGRESS_KEYS.includes(k) || typeof v!=='string') return; try{
        v = migrateStoredNodeValue(k, v); // 2026-10-14: a blob pushed by an older build still names fights by the old ids (f-1 → 1-1)
        const merge = PROGRESS_MERGE_KEYS[k]; localStorage.setItem(k, merge ? merge(localStorage.getItem(k), v) : v); }catch(e){} });
      try{ myDiscoveredCardIds = new Set(JSON.parse(localStorage.getItem(DISCOVERED_KEY)||'[]')); }catch(e){}
      LiveData.progressPushedHash = snapshotHash(progressSnapshot());
      try{ localStorage.setItem(PROGRESS_LOCAL_AT_KEY, String(Date.parse(data.updated_at))); }catch(e){}
      if(!matchState){ try{ if(currentTab==='home') renderHome(); else if(currentTab==='play') renderPlay(); }catch(e){} }
    } else livePushProgress(true);
  }catch(e){}
}
function livePushProgress(force){
  if(!liveCanWrite()) return;
  const snap = progressSnapshot(), h = snapshotHash(snap);
  if(!force && h===LiveData.progressPushedHash) return;
  LiveData.progressPushedHash = h;
  const now = Date.now();
  try{ localStorage.setItem(PROGRESS_LOCAL_AT_KEY, String(now)); }catch(e){}
  sbClient.from('player_progress').upsert({profile_id: cloudUserId, data: snap, updated_at: new Date(now).toISOString()})
    .then(({error})=>{ if(liveTableMissing(error)) LiveData.available = false; }, ()=>{});
}
setInterval(()=>{ try{ livePushProgress(false); }catch(e){} }, 20000);
window.addEventListener('pagehide', ()=>{ try{ livePushProgress(false); }catch(e){} });
