function bumpFightSerial(){ try{ localStorage.setItem(FIGHT_SERIAL_KEY, String(fightSerial() + 1)); }catch(e){} }
function fieldRowsSeen(){ try{ return JSON.parse(localStorage.getItem(FIELD_ROWS_KEY) || '{}') || {}; }catch(e){ return {}; } }
