  for(let i = 0; i < n; i++){ const id = ids[Math.floor(Math.random()*ids.length)]; if((o.counts[id]||0) >= ITEM_CAP) continue; o.counts[id] = (o.counts[id]||0) + 1; got.push(id); }
  saveItems(o);
