      const e = document.createElement('span'); e.className = 'pred-eyes' + (Math.random() < 0.35 ? ' is-red' : ''); e.setAttribute('aria-hidden', 'true'); e.innerHTML = '<i></i><i></i>'; e.style.left = x + '%'; e.style.top = y + '%'; canvas.appendChild(e);
