      const loopMs = Math.max(600, rest - 950), dir = Math.random() < .5 ? -1 : 1, R = kind==='firefly' ? 7 : 11, a = R*0.32, k = 5, turns = Math.max(1, loopMs/2600);
      const o = {t:0};
