    if(SWAP_SKIP_SOURCES.has(source) || adminModeEnabled) return;
    if(swapOffersShown() >= SWAP_OFFERS_MAX || !swapTutorialDone()) return;
    if(!dominatedDeckCard(id)) return;
    queueDeckSwap({id, natural:true, strict:true});
