    if(hm.wait) sc.wait = Object.assign({}, hm.wait);
    if(hm.steps) sc.steps = hm.steps.slice();
    if(hm.fire){ sc.steps = [{fire: entry.key}]; sc.notes.push('Fired by hand: ' + hm.why); }
    if(!sc.steps) sc.steps = ['round'];
