  const doFlip = !(opts&&opts.instant) && hasGsap() && typeof Flip!=='undefined';
  let flipState = null;
  if(doFlip) flipState = Flip.getState(row.querySelectorAll('.board-card[data-flip-id]'), {props:'opacity'});
  ghostEl.remove();
