  if(placementPreview){ if(placementPreview.ghostEl && placementPreview.ghostEl.parentElement) placementPreview.ghostEl.remove(); placementPreview = null; }
  const me = m.players[viewerHandPid(m)];
  const actualSide = me.row.center.length===0 ? 'center' : side; // mirrors placeCard's own center-first rule
  const doFlip = hasGsap() && typeof Flip!=='undefined';
  let flipState = null;
  if(doFlip) flipState = Flip.getState(row.querySelectorAll('.board-card[data-flip-id]'), {props:'opacity'});
  const ghost = document.createElement('div');
  ghost.className = 'board-card ghost-preview';
  ghost.setAttribute('data-flip-id', '__placement_ghost__');
  const [rA, rB] = rarityStops(d.rarity||'common');
  // 2026-09-21 ("...or drag and dropping it" — the card doesn't say its wait timer while being
  // dragged either): this ghost preview is its own hand-built markup, separate from
  // cardTileHTML's real waitbadge, and never included it at all — so a card with a real Wait
  // showed no hint of that during the whole drag, only once it actually landed. Mirrors
  // cardTileHTML's own waitbadge exactly so the preview genuinely previews what you're about to get.
  ghost.innerHTML = `<div class="card-tile ${rarityTierClass(d.rarity)} ${biomeClass(d)}" style="--rarity-a:${rA}; --rarity-b:${rB}">
    ${d.wait>0?`<div class="waitbadge" title="Wait — turns before it can act after being played">${pipsHTML('⏳', d.wait, 'wait')}</div>`:''}
    <div class="ico">${cardIcoHTML(d)}</div><div class="rarity-band"></div><div class="nm">${escapeHtml(d.name||'')}</div>
    <div class="stats"><span class="atk">⚔${d.attack}</span><span class="hp">❤${d.health}</span></div>
  </div>`;
  if(actualSide==='center'){
    const centerSlot = row.querySelector('.center-slot-empty');
    if(centerSlot) centerSlot.replaceWith(ghost); else row.appendChild(ghost);
  } else if(actualSide==='left'){
    row.insertBefore(ghost, row.firstChild);
  } else {
    row.appendChild(ghost);
  }
