function revealBoardCardsAtEnd(){
  const m = matchState; if(!m) return;
  const alive = new Set(); [1,2].forEach(pid=> ['left','center','right'].forEach(sd=> (m.players[pid].row[sd]||[]).forEach(c=>{ if(c.hp > 0) alive.add(String(c.uid)); })));
  document.querySelectorAll('#rowMine .board-card[data-uid], #rowEnemy .board-card[data-uid]').forEach(el=>{
    if(!alive.has(String(el.dataset.uid))) return;
    const t = el.querySelector('.card-tile');
    const wasEntering = el.classList.contains('is-entering') || (hasGsap() && gsap.isTweening(el));
    el.classList.remove('is-entering');
    try{ if(hasGsap()){ gsap.killTweensOf(el); if(t) gsap.killTweensOf(t); } }catch(e){}
    // a card still flying in from the hand when the match ended was frozen mid-air (above the row, shrunk): land it
    if(wasEntering){ try{ if(hasGsap()){ gsap.set(el, {clearProps:'position,left,top,width,height,transform,x,y,rotation,scale,opacity'}); if(t) gsap.set(t, {clearProps:'transform,opacity,filter'}); } else { el.style.transform = ''; el.style.position = ''; } }catch(e){} }
    if(parseFloat(getComputedStyle(el).opacity) < 0.95 && !el.classList.contains('is-scattering')){ el.style.opacity = '1'; }
    if(t && parseFloat(getComputedStyle(t).opacity) < 0.95){ t.style.opacity = '1'; }
    if(el.style.visibility === 'hidden') el.style.visibility = '';
  });
}
// Castle crumble (2026-10-13, user: "When the enemy castle dies from normal damage, show a new crumbling animation"): the
// castle shakes, cracks, and slumps into a heap of falling stones and dust before the result sign.
// The deck has a visible thickness (2026-10-13, user: "Your deck has a observable thickness, growing to the top left"): one
// card edge peeks out up and to the left for every two cards left, up to twelve.
// The deck pile (2026-10-14, user: "The 'deck' - the cards should look a bit closer together. 2ndly, the base card should be inline
// with the other cards, then it grows from there"): the bottom card sits exactly where the hand's cards sit; each card above it is
// lifted a hair up and to the left (at most 6 layers, 1px apart), so a full deck rises out of the row instead of sinking below it.
function deckPileStyle(n){
  const k = Math.min(6, Math.ceil((n||0) / 4)); if(!k) return '';
  const edges = Array.from({length:k}, (_, i)=> `${i+1}px ${i+1}px 0 ${i % 2 ? 'rgba(60,40,20,.85)' : 'rgba(236,214,170,.95)'}`);
  return `box-shadow:${edges.join(', ')}, ${k}px ${k+3}px 0 rgba(0,0,0,.22); top:${-k}px; left:${-k}px; margin-top:0;`;
}
async function castleCrumble(el){
  if(!el || !el.isConnected || reducedMotion()) return;
  // 2026-10-14: the cellular-automaton crumble eats the castle along its own cracks, chips falling as rubble.
  if(window.ProcFX && ProcFX.crumble){ const tile = el.classList.contains('card-tile') ? el : el.querySelector('.card-tile');
    if(tile){ try{ SoundKit.thud ? SoundKit.thud() : (SoundKit.quick && SoundKit.quick()); }catch(e){}
      // 2026-10-14 (user: "While the enemy Bramble HP = 0 triggers crumbling, it also queues the post-battle in 0.5s"): the crumble
      // rides GSAP's global clock, which the fight speed (1.5×–3×) and hit-stop scale, so at speed it was over in a blink and the
      // Victory sign and results came straight after. It now always plays at 1×, runs at least its full length, then holds a beat.
      const gtl = window.gsap && gsap.globalTimeline, ts0 = gtl ? gtl.timeScale() : 1, t0 = performance.now();
      if(gtl) gtl.timeScale(1);
      await new Promise(res=>{ let done = false; const fin = ()=>{ if(!done){ done = true; res(); } };
        try{ ProcFX.crumble(tile, {seed: tile.dataset.pfxSeed || 'castle', duration: 1.8, onDone: fin}); }catch(e){ fin(); } setTimeout(fin, 3200); });
      const left = 2400 - (performance.now() - t0); if(left > 0) await sleep(left);
      if(gtl && gtl.timeScale() === 1) gtl.timeScale(ts0);
      el.classList.add('is-crumbled'); await sleep(450); return; } }
  const r = el.getBoundingClientRect(); if(!r.width) return;
  const layer = document.createElement('div'); layer.className = 'crumble-layer'; layer.setAttribute('aria-hidden', 'true');
  layer.style.cssText = `left:${r.left}px; top:${r.top}px; width:${r.width}px; height:${r.height}px;`;
  document.body.appendChild(layer);
  layer.innerHTML = '<i class="crumble-crack"></i><i class="crumble-dust"></i>' + Array.from({length:22}, (_, i)=>{
    const x = (i * 37) % 100, sz = 6 + (i * 7) % 12, dx = ((i * 53) % 60) - 30, rot = ((i * 97) % 300) - 150, dl = (i % 7) * 45 + 380;
    return `<b class="crumble-stone" style="left:${x}%; top:${10 + (i * 29) % 60}%; width:${sz}px; height:${Math.round(sz*0.8)}px; --dx:${dx}px; --rot:${rot}deg; animation-delay:${dl}ms"></b>`; }).join('');
  el.classList.add('is-crumbling');
  try{ SoundKit.thud ? SoundKit.thud() : (SoundKit.quick && SoundKit.quick()); }catch(e){}
  await sleep(1500);
  el.classList.add('is-crumbled');
  setTimeout(()=> layer.remove(), 900);
  await sleep(450); // a beat before the Victory sign (2026-10-14)
}
// 2026-10-16 (user: "Sometimes the battle gets stuck ... you can't pass turn, but you also can't play a card"): a throw anywhere in
// the round's replay used to leave m.resolving set for good, which locks play, pitch, Pass and Auto. The round now always hands
// control back: if the engine already fought the round but the replay broke before the next turn was set up, the next turn is set
// up here (flags cleared, round advanced, the draw); if a castle fell, the match ends as usual.
async function resolveRound(opts){
  const m = matchState; const r0 = m ? m.round : 0;
  try{ return await resolveRoundCore(opts); }
  catch(e){
    try{ console.error('[fight] resolveRound failed', e); }catch(_){}
    if(!m || matchState !== m) return;
    m.resolving = false; m._upkeep = false; m._coachWait = false; m.replayRows = null; m.ending = false;
    try{ document.documentElement.classList.remove('bw-resolving', 'bw-upkeep', 'bw-coach-wait'); hideUpkeepChip(); syncFightTimeScale(m); }catch(_){}
    if(!m._rrCombatDone) m._rrFails = (m._rrFails||0) + 1; // the next try skips the tutorial/effects waits (resolveRoundCore)
    if(m.over || !m._rrCombatDone || m.round !== r0) { fightSafe(renderMatchUI, 'renderMatchUI'); return; }
    const dead = [1, 2].filter(p=> m.players[p] && m.players[p].hq && m.players[p].hq.hp <= 0);
    if(dead.length && m.forcedWinner == null && !m.dungeon){
      m.forcedWinner = dead.length === 2 ? 0 : (dead[0] === 1 ? 2 : 1);
      setTimeout(()=>{ if(matchState === m && !m.over) resolveRound({manual:true, run:()=> true}); }, 0);
      return;
    }
    [1, 2].forEach(p=>{ m.players[p].playedThisTurn = false; m.players[p].discardUsedThisTurn = false; });
    if(m.mode==='pc' || m.mode==='liveRanked'){ m.turnDone = {1:false, 2:false}; m.active = 1; }
    m.round += 1;
    const ev = [];
    fightSafe(()=>{ if(m.engine.roundStart && m.mode!=='tutorial' && m.mode!=='liveRanked') m.engine.roundStart(m.players, m.round, m.sideOf || (id=> id===1?'A':'B'), m.stats, ev); }, 'roundStart');
    fightSafe(()=>{ m.engine.draw(m.players[1], 1, 'A', m.stats, ev); m.engine.draw(m.players[2], 1, 'B', m.stats, ev); }, 'draw');
    ev.forEach(x=> fightSafe(()=> pushLog(x)));
    fightSafe(renderMatchUI, 'renderMatchUI');
  }
}
