    if((m.stallRounds >= STALL_ROUNDS_FOR_DRAW && (m.round >= STALL_DRAW_FROM_ROUND || m.raidRoundCap)) || m.round >= DRAW_ROUND_CAP){ m.forcedWinner = 0; m.endReason = m.round >= DRAW_ROUND_CAP ? 'cap' : 'stalled'; over = true; }
