  for(const p of (pid ? [pid] : [1,2])){ const r = m.players[p].row; const c = [...r.left, ...r.center, ...r.right].find(c=> c.hp>0 && defs[c.defId] && pred(defs[c.defId], c)); if(c) return boardCardEl(c.uid); }
