  // it actually blocked something (a Bulwark card with, say, 0 current reduction stays silent).
  if(ev.type==='hitHQ' && ev.bulwark>0 && targetEl){ setTimeout(()=> { SoundKit.bulwarkTone(); floatText(targetEl, '🛡 -'+ev.bulwark+' blocked', ''); }, 140); }
