  if(ev.type==='pounce'){
    const el = boardCardEl(ev.uid);
    if(el){ floatText(el, `🐾 Pounce ${ev.amount}`, 'gold'); } // 2026-10-15: the spring is now the hit's own leap onto its target (SkillFX.pounceOnto)
  }
