  const part = (glyph, need, have, label)=>{ if(!need) return; const short = have < need; parts.push(`<span class="bc ${short ? 'is-short' : ''}" title="${escapeAttr(label)}: need ${need}, you have ${have}">${glyph} ${need}</span>`); };
