// Published pack table (admin, card_overrides row `__cfg:shop-packs`): live for every player.
let cloudShopPacks = null;
function applyCloudShopPacks(r){
  cloudShopPacks = (!r.deleted && r.data && Array.isArray(r.data.packs) && r.data.packs.length) ? r.data.packs : null;
  try{ if(currentTab==='shop') renderShop(); }catch(e){}
}
async function publishShopPacks(packs){
  const row = packs ? {data:{kind:'shop-packs', packs}, deleted:false, deleted_snapshot:null} : {data:null, deleted:true, deleted_snapshot:null};
  return cloudWriteCardOverride('__cfg:shop-packs', row);
}
// D14 (2026-10-03, explicit: "Don't let the latest chests/cases/packs be purchaseable except for
// Hedgerow Pouch for now"): these show as "Coming soon" and can't be bought, even under an admin override.
// 2026-10-10: the Tidemire Chest now comes with the Ember Peddler (map 11) instead; the Highcrest Case waits for
// the map-19 merchant.
const SHOP_PACKS_COMING_SOON = new Set([]); // 2026-10-12: the Highcrest Case goes on sale with the Gilded Caravan (Map 13); was ['gold']
function packMerchant(p){ return p ? FEATURE_SPOTS.find(sp=> sp.merchant && sp.pack === p.id) || null : null; }
function packMerchantLocked(p){ const sp = packMerchant(p); return !!(sp && !featureUnlocked(sp.key)); }
function packOnSale(p){ if(p && p.id === MYSTERY_PACK_ID && !p.anytime) return mysteryPacksLeft() > 0; return p && (packMerchant(p) || !(p.comingSoon === undefined ? SHOP_PACKS_COMING_SOON.has(p.id) : p.comingSoon)) /* a pack with a merchant on the map is sold once that merchant is found, "coming soon" or not (2026-10-12) */ && p.available!==false && !packMerchantLocked(p); }
// Mystery Boosters (2026-10-11, user: "Mystery packs are limited when the wandering trader DOES appear. E.g. maybe buy max
// 5" + their map list: "Wandering Trader A unlocks Mystery Pack A"): only the wandering trader sells them, once you've found
// them that day, at most 5 a visit. (An admin pack edit with `anytime` puts them back on the shelf.)
const MYSTERY_PACK_ID = 'mystery', MYSTERY_PER_VISIT = 5;
function mysteryPacksLeft(){ try{ if(!wanderingMerchantToday() || !wandererState().found) return 0; if(FEATURE_SPOTS.some(sp=> sp.key==='wanderer') && !featureUnlocked('wanderer')) return 0; return Math.max(0, MYSTERY_PER_VISIT - (wandererState().mystery||0)); }catch(e){ return 0; } }
