// About you (2026-10-07, user: "the account page should say my email and i should be able to enter
// other details such as hobby and name and birthday if i want... I wanted to do birthday related
// rewards"). Name and email already come from Google, so they're shown, not asked for. Hobby and
// birthday are optional, saved on this device and in your own private progress row (only you can
// read it), and the birthday is month and day only — enough for a gift, nothing more.
const PERSONAL_KEY = 'bramblewood_personal_v1';
function loadPersonal(){ try{ return JSON.parse(localStorage.getItem(PERSONAL_KEY) || '{}') || {}; }catch(e){ return {}; } }
function savePersonal(p){ try{ localStorage.setItem(PERSONAL_KEY, JSON.stringify(p)); }catch(e){} try{ livePushProgress(true); }catch(e){} }
const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
function aboutYouHTML(){
  const p = loadPersonal(); const [bm, bd] = (p.birthday || '').split('-').map(Number);
  return `<details class="panel about-you" ${p.hobby || p.birthday ? '' : 'open'}><summary><h3>🌱 About you <small>optional</small></h3></summary>
    <p class="panel-sub">Only you can see these. ${isSignedIn() ? 'Saved privately with your account.' : 'Saved on this device.'}</p>
    <label class="ay-row"><span>Hobby</span><input type="text" id="ayHobby" maxlength="40" placeholder="e.g. birdwatching" value="${escapeAttr(p.hobby || '')}"></label>
    <div class="ay-row"><span>Birthday</span><select id="ayBMonth" aria-label="Birthday month"><option value="">Month</option>${MONTHS.map((m, i)=> `<option value="${i+1}" ${bm===i+1?'selected':''}>${m}</option>`).join('')}</select>
      <select id="ayBDay" aria-label="Birthday day"><option value="">Day</option>${Array.from({length:31}, (_, i)=> `<option value="${i+1}" ${bd===i+1?'selected':''}>${i+1}</option>`).join('')}</select></div>
    <p class="panel-sub ay-note">🎂 On your birthday the Bramblewood leaves you a gift. No year needed.</p>
  </details>`;
}
function wireAboutYou(){
  const h = document.getElementById('ayHobby'), m = document.getElementById('ayBMonth'), d = document.getElementById('ayBDay');
  if(!h) return;
  const save = ()=>{
    const p = loadPersonal(); p.hobby = h.value.trim().slice(0, 40);
    if(m.value && d.value){ const md = `${String(m.value).padStart(2,'0')}-${String(d.value).padStart(2,'0')}`; if(md !== p.birthday){ p.birthday = md; } }
    else if(!m.value && !d.value) delete p.birthday;
    savePersonal(p); checkBirthdayGift();
  };
  h.addEventListener('change', save); m.addEventListener('change', save); d.addEventListener('change', save);
}
// Birthday gift: once per calendar year, on (or the first visit after midnight of) your birthday.
const BIRTHDAY_GIFT = {gold: 300, gems: 25};
function checkBirthdayGift(){
  const p = loadPersonal(); if(!p.birthday) return;
  const now = new Date(), today = `${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
  if(today !== p.birthday || p.giftYear === now.getFullYear()) return;
  p.giftYear = now.getFullYear(); savePersonal(p);
  Object.entries(BIRTHDAY_GIFT).forEach(([k, v])=> grantCurrency(k, v));
  try{ showToast(TX('toast.happy-birthday-the-bramblewood-left-you', {v1: cloudUserLabel ? ', ' + String(cloudUserLabel).split(' ')[0] : '', gold: BIRTHDAY_GIFT.gold, gems: BIRTHDAY_GIFT.gems}), 'ok'); SoundKit.win && SoundKit.win(); }catch(e){}
}
setTimeout(()=>{ try{ checkBirthdayGift(); }catch(e){} }, 4000);
// Profile (2026-10-08 redesign, user: "The Profile page in general does not look very nice ...
// there's no framework - things are being anchored randomly"; "The title should be shown above the
// profile icon ... Fuse this UI with the 'Your Character' UI. Clicking the logo opens a subpane that
// lets you edit this"; "It also [shows] your level and collection total level ... Collection % ...
// Skin collection %"; "Achievements should be its own page"). One header card (title over the
// avatar, name, level, rank), a row of four collection tiles, then two columns: left is play
// (wallet, achievements, what rivals see), right is account (sign-in, about you, log out).
function collectionStats(){
  const defs = getCardDefs();
  // One count everywhere (2026-10-13 UI audit: Home, Codex and Profile each counted cards differently): collectible cards only.
  const ids = Object.keys(defs).filter(id=> { const d = defs[id]; return d && !d.token && !d.test && !d.hero && d.cardType !== 'materia' && !isHofVariant(d) && !(SPELLS_SHELVED && d.cardType === 'spell'); });
  const owned = ids.filter(id=> (!defs[id].locked && !isCardHiddenForPlayer(defs[id])) || (myCardCopies[id]||[]).length);
  const levelSum = owned.reduce((t, id)=> t + getCardLevel(id), 0);
  // Skins (for now): each card has its plain print and its foil. Owning the card unlocks the plain
  // one; owning a foil copy unlocks the foil. More finishes will add to the total.
  const SKINS_PER_CARD = 2;
  const skins = owned.length + owned.filter(id=> (myCardCopies[id]||[]).some(c=> c && c.foil)).length;
  return {total: ids.length, owned: owned.length, levelSum, levelMax: ids.length*10, skins, skinTotal: ids.length*SKINS_PER_CARD};
}
function profileHeroHTML(){
  const av = loadAvatar(), L = playerLevelInfo(), rank = rankForRating(myRating);
  const name = myProfile ? myProfile.name : 'Guest';
  return `<section class="pf-hero">
    <button type="button" class="pf-avatar-btn" id="pfAvatarBtn" title="Edit your character" aria-label="Edit your character (${escapeAttr(avatarTitleLabel(av))})">
      <span class="pf-title">${escapeHtml(avatarTitleLabel(av))}</span>
      <span class="pf-avatar">${avatarHTML(av, 104)}</span>
      <span class="pf-edit" aria-hidden="true">✏️</span>
    </button>
    <div class="pf-who">
      <h2 class="pf-name">${escapeHtml(name)}</h2>
      <div class="pf-status">${isSignedIn() ? '<span class="pf-dot ok"></span>Synced to your account' : '<span class="pf-dot"></span>Guest · saved on this device'}${cloudCardAdmin ? ' · <span class="admin-badge">🛡 Admin</span>' : ''}</div>
      <div class="pf-level"><b>⭐ Level ${L.level}</b><span class="pf-bar"><span style="width:${Math.round(L.into/L.need*100)}%"></span></span><small>${L.into}/${L.need} XP</small></div>
    </div>
    <div class="pf-rank" title="From Online Raid and Ranked results">
      <span class="conquest-rank-badge">${rank.label}</span>
      <small>Rating ${Math.round(myRating)}</small>
    </div>
  </section>`;
}
function profileTilesHTML(){
  const c = collectionStats(), L = playerLevelInfo();
  const pct = (a, b)=> b ? Math.round(a/b*100) : 0;
  const tile = (ico, big, label, sub, bar, tip)=> `<div class="pf-tile" title="${escapeAttr(tip)}"><span class="pf-tile-ico">${ico}</span><b>${big}</b><span class="pf-tile-k">${label}</span>${bar!=null ? `<span class="pf-tile-bar"><span style="width:${bar}%"></span></span>` : ''}<small>${sub}</small></div>`;
  return `<section class="pf-tiles">
    ${tile('⭐', L.level, 'Player level', `${L.into}/${L.need} XP to ${L.level+1}`, Math.round(L.into/L.need*100), 'Your player level, from wins, first clears, medals and quests')}
    ${tile('📚', c.levelSum, 'Collection level', `the sum of every owned card's level (max ${c.levelMax})`, pct(c.levelSum, c.levelMax), 'Every card you own, added up by its Forge level')}
    ${tile('🗂️', pct(c.owned, c.total) + '%', 'Collection', `${c.owned} of ${c.total} cards unlocked`, pct(c.owned, c.total), 'How many of the game’s cards you have unlocked')}
    ${tile('🎨', pct(c.skins, c.skinTotal) + '%', 'Skins', `${c.skins} of ${c.skinTotal} (plain + foil per card)`, pct(c.skins, c.skinTotal), 'Each card has a plain print and a foil; more finishes are coming')}
  </section>`;
}
function profileAchievementsCardHTML(){
  const ctx = achievementContext();
  const claimed = ACHIEVEMENT_DEFS.filter(d=> myClaimedAchievements.has(d.id)).length;
  const ready = ACHIEVEMENT_DEFS.filter(d=> { const st = achievementStatus(d, ctx); return st.claimable && !st.claimed; }).length;
  return `<button type="button" class="panel pf-achv-card" id="pfAchvBtn">
    <span class="pf-achv-ico">🏆</span>
    <span class="pf-achv-body"><b>Achievements</b><small>${claimed}/${ACHIEVEMENT_DEFS.length} claimed${ready ? ` · <em>${ready} ready to claim</em>` : ''}</small>
      <span class="pf-tile-bar"><span style="width:${Math.round(claimed/ACHIEVEMENT_DEFS.length*100)}%"></span></span></span>
    <span class="pf-go" aria-hidden="true">›</span>
  </button>`;
}
function profileAccountHTML(){
  if(!isSignedIn()) return `<div class="panel pf-account" id="cloudAccountPanel"><h3>🔑 Sign in</h3><p class="panel-sub">Save your progress to an account and play online. <span id="cloudSyncStatusLine"></span></p>${authFormHTML('profile')}</div>`;
  return `<div class="panel pf-account" id="cloudAccountPanel">
    <h3>☁️ Account</h3>
    <dl class="pf-facts">
      <dt>Signed in as</dt><dd><b>${escapeHtml(cloudUserLabel || 'Your account')}</b>${cloudUserEmail && cloudUserEmail !== cloudUserLabel ? `<small>${escapeHtml(cloudUserEmail)}</small>` : ''}</dd>
      <dt>Sync</dt><dd id="cloudSyncStatusLine">Checking…</dd>
    </dl>
    ${userHasPasswordIdentity() ? '' : `<details class="add-password"><summary>Add a password (to also log in with email)</summary>
      <form id="addPasswordForm" class="auth-email-form"><input id="addPasswordInput" type="password" placeholder="New password (8+ characters)" autocomplete="new-password" minlength="8"><div class="auth-actions"><button type="submit" class="btn primary">Save password</button></div><div class="cloud-link-msg" id="addPasswordMsg" hidden></div></form></details>`}
    <button type="button" class="btn small" id="cloudSignOutBtn">Sign out</button>
  </div>`;
}
function openCharacterEditor(){
  let ov = document.getElementById('pfCharOverlay');
  if(!ov){ ov = document.createElement('div'); ov.id = 'pfCharOverlay'; ov.className = 'modal-overlay'; document.body.appendChild(ov); }
  ov.innerHTML = `<div class="modal pf-char-modal" role="dialog" aria-label="Your character"><button type="button" class="modal-close-btn" id="pfCharClose" aria-label="Close">✕</button>${avatarCustomizerHTML()}</div>`;
  ov.hidden = false;
  wireAvatarCustomizer();
  const close = ()=>{ ov.hidden = true; ov.innerHTML = ''; document.removeEventListener('keydown', onKey, true); if(currentTab==='profile') renderProfile(); };
  const onKey = e=>{ if(e.key==='Escape'){ e.stopImmediatePropagation(); close(); } };
  document.addEventListener('keydown', onKey, true);
  ov.querySelector('#pfCharClose').onclick = close;
  ov.onclick = e=>{ if(e.target===ov) close(); };
}
function renderAchievementsPage(){
  const root = document.getElementById('view-achievements'); if(!root) return;
  root.innerHTML = `<div class="play-subtabs" role="tablist"><button class="btn small" id="achvBackBtn">← Profile</button></div>${achievementsPanelHTML()}`;
  document.getElementById('achvBackBtn').onclick = ()=> switchTab('profile');
  wireAchievementsPanel();
}
// Admin resets (2026-10-13, user: "Help me add some admin functions in the profile. 1) Reset all, 2) Reset codex - just removes
// all seen only, 3) Reset to Map [N] -> assumes progress up till that map only, and unlocking all features up to that point").
// Admin content (card and map edits, NPC speeches, tutorial setup), device settings, admin mode and your name are kept.
const RESET_KEEP = /^(bramblewood_arena_(adminmode|devmode|profile|card_overlay|shop_packs_override)|bramblewood_(dialogue_edits_v1|forge_tier_edits_v1|node_edits_v1|tutorial_cfg_v2|map_layout_v1|ui_flags_v1|card_txns_v1))$/;
const PENDING_MAP_RESET_KEY = 'bw_pending_map_reset';
function adminWipeProgress(){ try{ Object.keys(localStorage).filter(k=> /^(bramblewood|bw_)/.test(k) && !DEVICE_SETTING_KEYS.test(k) && !RESET_KEEP.test(k)).forEach(k=> localStorage.removeItem(k)); sessionStorage.clear(); }catch(e){} }
function adminResetAll(){ adminWipeProgress(); location.reload(); }
function adminResetCodex(){
  try{ localStorage.removeItem(SEEN_KEY); localStorage.removeItem(DISCOVERED_KEY); }catch(e){}
  mySeenCardIds = new Set(); myDiscoveredCardIds = new Set(); try{ localStorage.setItem(SEEN_KEY, '[]'); }catch(e){}
  showToast('📖 The Codex forgot every card you had seen. Cards you own still show.', 'ok');
}
function adminResetToMap(n){
  n = Math.max(0, Math.floor(+n || 0)); const fac = loadFactionChoice();
  adminWipeProgress();
  try{ localStorage.setItem(PENDING_MAP_RESET_KEY, JSON.stringify({n, fac})); }catch(e){}
  location.reload();
}
// Runs once after the reload: tutorials done, every fight on the maps before Map N cleared (S rank, with its card rewards),
// and every feature from those maps open. Map N itself is where you stand.
function applyPendingMapReset(){
  let job = null; try{ job = JSON.parse(localStorage.getItem(PENDING_MAP_RESET_KEY) || 'null'); localStorage.removeItem(PENDING_MAP_RESET_KEY); }catch(e){}
  if(!job) return;
  try{
    saveTutorialDone(); saveTutorial2Done(); if(job.fac) localStorage.setItem('bramblewood_arena_faction', job.fac);
    try{ localStorage.setItem(NAME_CHOSEN_KEY, '1'); }catch(e){}
    if(job.n >= 2){ try{ localStorage.setItem(PITCH_OPEN_KEY, '1'); }catch(e){} }
    const maps = mainConquestMaps().filter((m, i)=> i < job.n), p = loadConquestProgress();
    CONQUEST_MAPS.forEach(m=> m.nodes.filter(nd=> nd.kind === 'tutorial').forEach(nd=>{ const id = conquestNodeId(m.id, nd.key); if(!p.completed.includes(id)) p.completed.push(id); }));
    let cards = 0;
    maps.forEach(m=> m.nodes.filter(nd=> nd.kind !== 'tutorial').forEach(nd=>{ const id = conquestNodeId(m.id, nd.key); if(!p.completed.includes(id)) p.completed.push(id); p.ranks[id] = 'S';
      nodeRewardCardIds(m.id, nd.key).forEach(cid=>{ try{ if(unlockCardForPlayer(cid, 'reward') !== false) cards++; }catch(e){} }); markCardRewardsClaimed(id); }));
    saveConquestProgress(p);
    const revealed = maps.map(m=> m.id); try{ localStorage.setItem(MAP_REVEALED_KEY, JSON.stringify(revealed)); }catch(e){}
    FEATURE_SPOTS.forEach(sp=>{ if(sp.mapNumber != null && sp.mapNumber < job.n) unlockFeature(sp.key); });
    const target = mainConquestMaps()[job.n]; if(target){ conquestSelectedMap = target.id; playSubTab = 'conquest'; }
    setTimeout(()=>{ try{ switchTab('play'); showToast(TX('toast.set-to-the-start-of-map', {n: job.n, length: maps.length, s: maps.length===1?'':'s', cards, s2: cards===1?'':'s'}), 'ok'); }catch(e){} }, 300);
  }catch(e){ console.error('[Bramblewood] reset to map failed', e); }
}
setTimeout(applyPendingMapReset, 1200);
function adminProfileToolsHTML(){
  if(!adminModeEnabled) return '';
  const top = Math.max(0, mainConquestMaps().length - 1);
  return `<div class="panel pf-admin"><h3>🚨 Admin: resets</h3><p class="panel-sub">Your card and map edits, NPC speeches and settings are kept.</p>
    <div class="pf-admin-row"><button type="button" class="btn small danger" id="pfResetAll">Reset all</button><span>Start this device over as a new player.</span></div>
    <div class="pf-admin-row"><button type="button" class="btn small" id="pfResetCodex">Reset Codex</button><span>Forget every card seen (owned cards stay).</span></div>
    <div class="pf-admin-row"><button type="button" class="btn small" id="pfResetMap">Reset to Map</button><input type="number" id="pfResetMapN" min="0" max="${top}" value="${Math.min(top, playerMapReach())}" aria-label="Map number"><span>Maps before it cleared, their features open.</span></div>
    <p class="pf-admin-confirm" id="pfAdminConfirm" hidden></p></div>`;
}
function wireAdminProfileTools(){
  const say = document.getElementById('pfAdminConfirm'); if(!say) return;
  // Two taps instead of confirm() (2026-10-13): the first tap arms the button, the second does it.
  const arm = (btn, label, fn)=>{ if(!btn) return; btn.onclick = ()=>{ if(btn.dataset.armed){ fn(); return; } btn.dataset.armed = '1'; const t = btn.textContent; btn.textContent = 'Tap again to ' + label.toLowerCase(); say.hidden = false; say.textContent = label + ': tap again within 4 seconds.'; setTimeout(()=>{ delete btn.dataset.armed; btn.textContent = t; say.hidden = true; }, 4000); }; };
  arm(document.getElementById('pfResetAll'), 'Reset all', adminResetAll);
  arm(document.getElementById('pfResetMap'), 'Reset to Map', ()=> adminResetToMap(document.getElementById('pfResetMapN').value));
  const rc = document.getElementById('pfResetCodex'); if(rc) rc.onclick = adminResetCodex;
}
function renderProfile(){
  const root = document.getElementById('view-profile');
  root.innerHTML = `<div class="pf">
    ${profileHeroHTML()}
    ${profileTilesHTML()}
    <div class="pf-grid">
      <div class="pf-col">
        <div class="panel pf-wallet"><h3>👛 Wallet</h3><div class="pf-wallet-row">${['gold','gems','dust','metal'].concat(featureUnlockedSafe('tavern') || (myCurrencies.beer||0) > 0 ? ['beer'] : []).map(k=> currencyPillHTML(k)).join('')}</div></div>
        ${profileAchievementsCardHTML()}
        ${profileMedalsHTML() /* 2026-10-15: Medals moved here from the Notices */}
        ${playerPreviewHTML()}
      </div>
      <div class="pf-col">
        ${profileAccountHTML()}
        ${aboutYouHTML()}
        <button class="btn danger pf-logout" id="logoutBtn">🚪 Log out of this device</button>
        ${adminProfileToolsHTML()}
      </div>
    </div>
    ${matchHistoryPanelHTML()}
  </div>`;
  document.getElementById('pfAvatarBtn').onclick = openCharacterEditor;
  document.getElementById('pfAchvBtn').onclick = ()=> switchTab('achievements');
  wireAboutYou(); wireAdminProfileTools();
  const ppEdit = document.getElementById('ppEditDeckBtn'); if(ppEdit) ppEdit.addEventListener('click', ()=>{ deckOpenBuilderOnce = true; deckShowList = false; deckEditingId = null; switchTab('deck'); });
  wireMatchHistoryPanel();
  if(isSignedIn() && matchHistoryList===null) loadMatchHistory();
  document.getElementById('logoutBtn').addEventListener('click', ()=>{
    if(isSignedIn()){ if(!confirm(TX('dialog.log-out-your-progress-is-saved'))) return; signOutAndSwitch(); return; }
    if(!confirm(TX('dialog.log-out-your-decks-currencies-and'))) return;
    clearMyProfile();
    matchHistoryList = null;
    showLoginScreen();
  });
  const signOutBtn = document.getElementById('cloudSignOutBtn');
  if(signOutBtn) signOutBtn.addEventListener('click', async ()=>{
    if(!confirm(TX('dialog.sign-out-your-progress-is-saved'))) return;
    await signOutAndSwitch();
  });
  const statusLine = document.getElementById('cloudSyncStatusLine');
  if(statusLine) statusLine.textContent = !sbClient ? 'Cloud sync unavailable right now.' : (isSignedIn() ? '✅ Active, your progress is backed up' : (cloudReady ? 'Playing as a guest.' : 'Connecting…'));
  wireAuthForm('profile', mode=>{
    showToast(mode==='create' ? TX('toast.account-created-everything-you-ve-done') : TX('toast.logged-in-this-device-now-has'), 'ok');
    renderProfile(); refreshAuthGateUI();
  });
  const pwForm = document.getElementById('addPasswordForm');
  if(pwForm) pwForm.addEventListener('submit', async e=>{
    e.preventDefault();
    const pw = document.getElementById('addPasswordInput').value; const m = document.getElementById('addPasswordMsg');
    const say = (t,err)=>{ m.hidden=false; m.textContent=t; m.classList.toggle('error',!!err); };
    if(pw.length<8){ say('Use at least 8 characters.', true); return; }
    try{ const { data, error } = await sbClient.auth.updateUser({password:pw}); if(error) throw error; if(data && data.user) cloudSessionUser = data.user; say('Saved — you can now also log in with your email and this password.'); }
    catch(err){ say(authErrorText(err), true); }
  });
}

/* ============================================================
   👥 Social: Friends, private match invites, and the public Market (2026-10-02, per explicit
   request: "1. friend system (LONG PASS) 2. public market system (LONG PASS) 3. friend private
   match invite + settings e.g. blackhole type").

   Backend: supabase/migrations/20261002_social_friends_invites_market.sql — friendships,
   match_invites, market_listings, plus SECURITY DEFINER functions that enforce the rules
   server-side (only friends can invite, one buyer per listing, can't buy your own listing).
   Every list here (arena types, cards, rarities, currencies, players) comes from Registry, never
   a hard-coded copy. Everything degrades to a clear "not available yet" note if the backend
   tables don't exist (e.g. before the migration is applied).
   ============================================================ */
const Social = {
  ready: false,            // backend tables reachable
  checked: false,
  myCode: null,
  rows: [],                // friendships rows involving me
  online: new Set(),       // profile ids currently online (Realtime presence)
  presence: null, inviteSub: null, friendSub: null,
  incomingInvites: [],     // pending invites to me
  outgoingInvite: null,    // my one pending invite (waiting screen)
  searchResults: null, searchTerm: '', searching: false,
  heartbeat: null,
};
function socialErrText(err){
  const raw = (err && (err.message || err.details)) || '';
  if(/relation .* does not exist|could not find the function|schema cache/i.test(raw)) return 'Friends & Market aren’t switched on yet — the database update still needs to be applied.';
  return raw || 'Something went wrong — try again.';
}
function relTime(iso){
  if(!iso) return 'a while ago';
  const s = Math.max(0, (Date.now() - new Date(iso).getTime())/1000);
  if(s<90) return 'just now'; if(s<3600) return Math.round(s/60)+'m ago'; if(s<86400) return Math.round(s/3600)+'h ago';
  return Math.round(s/86400)+'d ago';
}
// Called whenever the signed-in identity changes (and once at boot after cloud init).
async function socialInit(){
  socialTeardown();
  if(!sbClient || !isSignedIn()) { Social.checked = true; Social.ready = false; return; }
  try{
    const { data, error } = await sbClient.from('profiles').select('friend_code').eq('id', cloudUserId).maybeSingle();
    if(error) throw error;
    Social.myCode = data && data.friend_code || null;
    Social.ready = true;
  }catch(e){ Social.ready = false; Social.checked = true; return; }
  Social.checked = true;
  await socialRefresh();
  // Presence: who's online right now (keyed by profile id).
  try{
    Social.presence = sbClient.channel('bw-online', {config:{presence:{key: cloudUserId}}});
    Social.presence.on('presence', {event:'sync'}, ()=>{
      Social.online = new Set(Object.keys(Social.presence.presenceState()||{}));
      if(currentTab==='friends') renderFriendsListOnly();
    });
    Social.presence.subscribe(st=>{ if(st==='SUBSCRIBED') Social.presence.track({at: Date.now()}); });
  }catch(e){}
  // Live friend requests + invites.
  try{
    Social.friendSub = sbClient.channel('bw-friends-'+cloudUserId)
      .on('postgres_changes', {event:'*', schema:'public', table:'friendships', filter:`addressee_id=eq.${cloudUserId}`}, p=>{ socialRefresh().then(()=>{ if(p.eventType==='INSERT' && p.new && p.new.status==='pending') showToast(TX('toast.new-friend-request-open-friends-to')); }); })
      .on('postgres_changes', {event:'*', schema:'public', table:'friendships', filter:`requester_id=eq.${cloudUserId}`}, p=>{ socialRefresh().then(()=>{ if(p.eventType==='UPDATE' && p.new && p.new.status==='accepted') showToast(TX('toast.friend-request-accepted'), 'ok'); }); })
      .subscribe();
    Social.inviteSub = sbClient.channel('bw-invites-'+cloudUserId)
      .on('postgres_changes', {event:'INSERT', schema:'public', table:'match_invites', filter:`to_id=eq.${cloudUserId}`}, ()=> socialLoadInvites())
      .on('postgres_changes', {event:'UPDATE', schema:'public', table:'match_invites', filter:`to_id=eq.${cloudUserId}`}, ()=> socialLoadInvites())
      .on('postgres_changes', {event:'UPDATE', schema:'public', table:'match_invites', filter:`from_id=eq.${cloudUserId}`}, p=> onMyInviteUpdated(p.new))
      .subscribe();
  }catch(e){}
  socialLoadInvites();
  // "Last seen" heartbeat while signed in.
  const beat = ()=>{ if(sbClient && cloudUserId) sbClient.from('profiles').update({last_seen_at: new Date().toISOString()}).eq('id', cloudUserId).then(()=>{}, ()=>{}); };
  beat(); Social.heartbeat = setInterval(beat, 120000);
}
function socialTeardown(){
  ['presence','friendSub','inviteSub'].forEach(k=>{ try{ if(Social[k] && sbClient) sbClient.removeChannel(Social[k]); }catch(e){} Social[k] = null; });
  if(Social.heartbeat){ clearInterval(Social.heartbeat); Social.heartbeat = null; }
  Social.rows = []; Social.online = new Set(); Social.incomingInvites = []; Social.myCode = null; Social.outgoingInvite = null;
  hideInviteBanner();
}
async function socialRefresh(){
  if(!Social.ready) return;
  const { data, error } = await sbClient.from('friendships').select('*');
  if(error){ console.warn('friendships', error); return; }
  Social.rows = data || [];
  const ids = Social.rows.map(r=> r.requester_id===cloudUserId ? r.addressee_id : r.requester_id);
  await Registry.users.get(ids);
  refreshFriendsBadge();
  if(currentTab==='friends') renderFriends();
}
function socialBuckets(){
  const me = cloudUserId, out = {friends:[], incoming:[], outgoing:[], blocked:[]};
  Social.rows.forEach(r=>{
    const otherId = r.requester_id===me ? r.addressee_id : r.requester_id;
    const p = Registry.users._cache.get(otherId) || {id:otherId, display_name:'Player'};
    const item = {row:r, other:p};
    if(r.status==='accepted') out.friends.push(item);
    else if(r.status==='blocked' && r.requester_id===me) out.blocked.push(item);
    else if(r.status==='pending') (r.addressee_id===me ? out.incoming : out.outgoing).push(item);
  });
  out.friends.sort((a,b)=> (Social.online.has(b.other.id)-Social.online.has(a.other.id)) || String(a.other.display_name).localeCompare(String(b.other.display_name)));
  return out;
}
function refreshFriendsBadge(){
  const n = socialBuckets().incoming.length + Social.incomingInvites.length;
  document.querySelectorAll('[data-hometab="friends"] .home-badge').forEach(b=> b.remove());
  if(n>0) document.querySelectorAll('[data-hometab="friends"]').forEach(btn=>{ const s = document.createElement('span'); s.className = 'home-badge'; s.textContent = n; btn.appendChild(s); });
}
/* ---------- Friends screen ---------- */
function friendRowHTML(item, kind){
  const p = item.other; const on = Social.online.has(p.id);
  const name = escapeHtml(p.display_name || 'Player');
  const status = kind==='friend' ? (on ? '<span class="fr-on">● Online</span>' : `<span class="fr-off">Last seen ${relTime(p.last_seen_at)}</span>`) : (p.rating ? `Rating ${Math.round(p.rating)}` : '');
  let actions = '';
  if(kind==='friend') actions = `<button type="button" class="btn small primary" data-fr-invite="${p.id}">⚔️ Invite</button><button type="button" class="btn small ghost" data-fr-menu="${p.id}" aria-label="More for ${name}">⋯</button>`;
  if(kind==='incoming') actions = `<button type="button" class="btn small primary" data-fr-accept="${item.row.id}">Accept</button><button type="button" class="btn small" data-fr-decline="${item.row.id}">Decline</button>`;
  if(kind==='outgoing') actions = `<span class="fr-pending">Pending</span><button type="button" class="btn small ghost" data-fr-remove="${p.id}">Cancel</button>`;
  if(kind==='blocked') actions = `<button type="button" class="btn small" data-fr-remove="${p.id}">Unblock</button>`;
  return `<div class="fr-row" data-fr-id="${p.id}">
    <div class="fr-avatar ${on?'is-on':''}" aria-hidden="true">${escapeHtml((p.display_name||'?').trim().charAt(0).toUpperCase())}</div>
    <div class="fr-main"><div class="fr-name">${name}</div><div class="fr-sub">${status}</div></div>
    <div class="fr-actions">${actions}</div>
  </div>`;
}
function friendsListHTML(){
  const b = socialBuckets();
  const sec = (title, items, kind, empty)=> items.length || empty ? `<section class="fr-section"><h3>${title}${items.length?` <span class="fr-count">${items.length}</span>`:''}</h3>${items.length ? items.map(i=>friendRowHTML(i, kind)).join('') : `<p class="fr-empty">${empty}</p>`}</section>` : '';
  return sec('Requests', b.incoming, 'incoming', '')
    + sec('Friends', b.friends, 'friend', 'No friends yet — share your friend code or search for a player above.')
    + sec('Sent', b.outgoing, 'outgoing', '')
    + sec('Blocked', b.blocked, 'blocked', '');
}
function searchResultsHTML(){
  if(Social.searching) return '<p class="fr-empty">Searching…</p>';
  if(Social.searchResults===null) return '';
  if(!Social.searchResults.length) return `<p class="fr-empty">No players found for “${escapeHtml(Social.searchTerm)}”. Names need 3+ letters; friend codes are 6 characters.</p>`;
  const known = new Map(Social.rows.map(r=> [r.requester_id===cloudUserId ? r.addressee_id : r.requester_id, r]));
  return Social.searchResults.map(p=>{
    const r = known.get(p.id);
    const state = !r ? `<button type="button" class="btn small primary" data-fr-add="${p.id}">＋ Add</button>`
      : r.status==='accepted' ? '<span class="fr-pending">Friends ✓</span>'
      : r.status==='pending' ? (r.addressee_id===cloudUserId ? `<button type="button" class="btn small primary" data-fr-accept="${r.id}">Accept</button>` : '<span class="fr-pending">Requested</span>')
      : '<span class="fr-pending">Blocked</span>';
    return `<div class="fr-row"><div class="fr-avatar" aria-hidden="true">${escapeHtml((p.display_name||'?').charAt(0).toUpperCase())}</div><div class="fr-main"><div class="fr-name">${escapeHtml(p.display_name||'Player')}</div><div class="fr-sub">#${escapeHtml(p.friend_code||'')} · Rating ${Math.round(p.rating||1500)}</div></div><div class="fr-actions">${state}</div></div>`;
  }).join('');
}
// Friends page extras (2026-10-15, user: "Friends should be the default section. Will it show list of friends below? If no one,
// after 1s, show some characters from the game to make friends with. Then a section with last played players."). Woodland
// friends are local to this browser: befriend a character and they join your list and say hello when you wave.
const NPC_FRIENDS_KEY = 'bramblewood_npc_friends_v1';
const NPC_FRIEND_PICKS = [
  {who:'traveller', blurb:'Always one step down the road', hi:['A friend on the road is worth two packs in the cart.', 'Still walking? Good. So am I.']},
  {who:'golem', blurb:'Keeps the Forge fire', hi:['Cobble. Friend. I keep the fire warm for you.', 'Hm. You came to say hello. Cobble is glad.']},
  {who:'swiftpaw', blurb:'Otter scout captain', hi:['Knew you had good taste. Race you to the next map!', 'Need a scout? I know every shortcut.']},
  {who:'aurelia', blurb:'Matriarch of the Sunspire', hi:['The Sunspire remembers its friends. Fly well.', 'You honour us. Visit when the light is gold.']},
  {who:'hedgehog', blurb:'Collects lost buttons', hi:['Oh! Nobody ever befriends the hedgehog. Thank you!', 'I found a blue button today. Want to see?']},
  {who:'mouse', blurb:'Courier of the wood', hi:['A friend! Now I have someone to write to.', 'Any letters? I run fast, I promise.']},
];
let npcSuggestRevealed = false; // the "no one yet" pause happens once per visit
function loadNpcFriends(){ try{ const a = JSON.parse(localStorage.getItem(NPC_FRIENDS_KEY) || '[]'); return Array.isArray(a) ? a.filter(k=> DIALOGUE_SPEAKERS[k]) : []; }catch(e){ return []; } }
function saveNpcFriends(a){ try{ localStorage.setItem(NPC_FRIENDS_KEY, JSON.stringify(a)); }catch(e){} }
function npcFriendRowHTML(k, isFriend){
  const sp = DIALOGUE_SPEAKERS[k] || {}, pick = NPC_FRIEND_PICKS.find(p=> p.who === k) || {};
  return `<div class="fr-row fr-npc" data-npc-row="${k}"><div class="fr-avatar fr-npc-av" aria-hidden="true">${speakerPortraitHTML(sp)}</div>
    <div class="fr-main"><div class="fr-name">${escapeHtml(sp.name || k)}</div><div class="fr-sub">${isFriend ? '🌿 Woodland friend' : escapeHtml(pick.blurb || '')}</div></div>
    <div class="fr-actions">${isFriend ? `<button type="button" class="btn small" data-npc-hi="${k}">👋 Say hi</button>` : `<button type="button" class="btn small primary" data-npc-add="${k}">＋ Befriend</button>`}</div></div>`;
}
function friendsExtrasHTML(realFriends){
  const mine = loadNpcFriends(), offer = NPC_FRIEND_PICKS.filter(p=> !mine.includes(p.who));
  const nobody = !realFriends && !mine.length;
  const woodland = mine.length ? `<section class="fr-section"><h3>Woodland friends <span class="fr-count">${mine.length}</span></h3>${mine.map(k=> npcFriendRowHTML(k, true)).join('')}</section>` : '';
  const suggest = offer.length && !realFriends ? `<section class="fr-section fr-suggest ${nobody && !npcSuggestRevealed ? 'is-waiting' : ''}" id="frSuggest" ${nobody && !npcSuggestRevealed ? 'hidden' : ''}>
      <h3>${nobody ? 'No one yet? These folk would like a friend' : 'More folk to befriend'}</h3>${offer.slice(0, 4).map(p=> npcFriendRowHTML(p.who, false)).join('')}</section>` : '';
  const seen = new Set(), recent = loadRecentOpponents().map((o, i)=> Object.assign({i}, o)).filter(o=>{ const n = (o.name || '').trim(); if(!n || seen.has(n)) return false; seen.add(n); return true; }).slice(0, 6);
  const defs = getCardDefs();
  const recentSec = `<section class="fr-section fr-recent"><h3>🕑 Recently played</h3>${recent.length ? recent.map(o=>{ const top = Object.keys(o.deck || {}).sort((a, b)=> o.deck[b] - o.deck[a]).slice(0, 4).map(id=> defs[id] ? defs[id].icon : '').join('');
      return `<div class="fr-row"><div class="fr-avatar" aria-hidden="true">${escapeHtml((o.name || '?').trim().charAt(0).toUpperCase())}</div>
        <div class="fr-main"><div class="fr-name">${escapeHtml(o.name || 'Opponent')}</div><div class="fr-sub"><span class="ro-res ${o.result || ''}">${o.result==='win' ? 'Won' : o.result==='loss' ? 'Lost' : 'Draw'}</span> · ${escapeHtml(RECENT_OPP_MODE_LABEL[o.mode] || o.mode || '')} · ${relTime(new Date(o.at || Date.now()).toISOString())} <span aria-hidden="true">${top}</span></div></div>
        <div class="fr-actions"><button type="button" class="btn small ghost" data-fr-ro="${o.i}">🃏 Deck</button></div></div>`; }).join('')
    : '<p class="fr-empty">Nobody yet. The players and decks you face show up here.</p>'}</section>`;
  return woodland + suggest + recentSec;
}
function wireFriendsExtras(root){
  const box = root.querySelector('#frExtras'); if(!box) return;
  box.onclick = e=>{
    const t = e.target.closest('button'); if(!t) return;
    if(t.dataset.npcAdd){ const k = t.dataset.npcAdd, mine = loadNpcFriends(); if(!mine.includes(k)){ mine.push(k); saveNpcFriends(mine); }
      const pick = NPC_FRIEND_PICKS.find(p=> p.who === k) || {hi:['Friends!']}, sp = DIALOGUE_SPEAKERS[k] || {};
      try{ SoundKit.unlockChime ? SoundKit.unlockChime() : SoundKit.buffUp(); }catch(_){}
      showToast(`${sp.icon || '🌿'} ${sp.name || k}: “${pick.hi[0]}”`, 'ok');
      npcSuggestRevealed = true; renderFriends(); return; }
    if(t.dataset.npcHi){ const k = t.dataset.npcHi, pick = NPC_FRIEND_PICKS.find(p=> p.who === k) || {hi:['Hello!']}, sp = DIALOGUE_SPEAKERS[k] || {};
      const line = pick.hi[Math.floor(Math.random() * pick.hi.length)];
      DIALOGUES['npcfriend:' + k] = {lines:[{who:k, text:line}]};
      try{ playDialogue('npcfriend:' + k); }catch(_){ showToast(`${sp.icon || '🌿'} ${sp.name || k}: “${line}”`); }
      return; }
    if(t.dataset.frRo != null) openRecentOpponentDeck(+t.dataset.frRo);
  };
  const sug = box.querySelector('#frSuggest.is-waiting');
  if(sug) setTimeout(()=>{ if(!sug.isConnected) return; npcSuggestRevealed = true; sug.hidden = false; sug.classList.remove('is-waiting'); sug.classList.add('is-in'); }, 1000);
}
function renderFriends(){
  const root = document.getElementById('view-friends'); if(!root) return;
  if(!isSignedIn()){
    root.innerHTML = `<div class="panel fr-panel"><h2>👥 Friends</h2><p class="panel-sub">Add friends, see who’s online, and invite them to private matches.</p><button type="button" class="btn primary" id="frSignInBtn">Sign in to use Friends</button>
      <div id="frExtras">${friendsExtrasHTML(0)}</div></div>`;
    document.getElementById('frSignInBtn').onclick = ()=> requireSignIn('to use Friends', ()=>{ switchTab('friends'); });
    wireFriendsExtras(root);
    return;
  }
  if(!Social.ready){
    root.innerHTML = `<div class="panel fr-panel"><h2>👥 Friends</h2><p class="panel-sub">${Social.checked ? 'Friends aren’t switched on yet — the database update still needs to be applied.' : 'Connecting…'}</p><div id="frExtras">${friendsExtrasHTML(0)}</div></div>`;
    wireFriendsExtras(root);
    if(!Social.checked) socialInit().then(()=>{ if(currentTab==='friends') renderFriends(); });
    return;
  }
  root.innerHTML = `<div class="panel fr-panel">
      <div class="fr-head"><h2>👥 Friends</h2>
        <div class="fr-code" title="Share this so friends can add you">Your code <b id="frMyCode">${escapeHtml(Social.myCode||'——')}</b> <button type="button" class="btn small ghost" id="frCopyCode">Copy</button></div></div>
      <form class="fr-search" id="frSearchForm" role="search">
        <input type="search" id="frSearchInput" placeholder="Friend code or player name" value="${escapeAttr(Social.searchTerm)}" aria-label="Friend code or player name" autocomplete="off">
        <button type="submit" class="btn primary">Search</button>
      </form>
      <div id="frSearchResults">${searchResultsHTML()}</div>
      <div id="frLists">${friendsListHTML()}</div>
      ${Social.outgoingInvite ? `<div class="fr-waiting" id="frWaiting">⏳ Waiting for <b>${escapeHtml(((Registry.users._cache.get(Social.outgoingInvite.to_id)||{}).display_name)||'your friend')}</b> to accept… <button type="button" class="btn small ghost" id="frCancelInvite">Cancel invite</button></div>` : ''}
      <div id="frExtras">${friendsExtrasHTML(socialBuckets().friends.length)}</div>
    </div>`;
  wireFriends();
  wireFriendsExtras(root);
}
function renderFriendsListOnly(){ const el = document.getElementById('frLists'); if(el){ el.innerHTML = friendsListHTML(); } }
function wireFriends(){
  const root = document.getElementById('view-friends'); if(!root) return;
  const copy = document.getElementById('frCopyCode');
  if(copy) copy.onclick = ()=>{ try{ navigator.clipboard.writeText(Social.myCode||''); showToast(TX('toast.friend-code-copied')); }catch(e){} };
  const form = document.getElementById('frSearchForm');
  if(form) form.onsubmit = async e=>{
    e.preventDefault();
    Social.searchTerm = document.getElementById('frSearchInput').value.trim(); if(!Social.searchTerm) return;
    Social.searching = true; document.getElementById('frSearchResults').innerHTML = searchResultsHTML();
    try{ Social.searchResults = await Registry.users.search(Social.searchTerm); }
    catch(err){ Social.searchResults = []; showToast(socialErrText(err), 'error'); }
    Social.searching = false; document.getElementById('frSearchResults').innerHTML = searchResultsHTML();
  };
  const cancelInv = document.getElementById('frCancelInvite');
  if(cancelInv) cancelInv.onclick = cancelMyInvite;
  // One delegated handler for every row button (lists re-render often).
  root.onclick = async e=>{
    const t = e.target.closest('button'); if(!t) return;
    const run = async (fn, ok)=>{ t.disabled = true; try{ await fn(); if(ok) showToast(ok, 'ok'); await socialRefresh(); }catch(err){ showToast(socialErrText(err), 'error'); } finally{ t.disabled = false; } };
    if(t.dataset.frAdd) return run(async ()=>{ const { data, error } = await sbClient.rpc('send_friend_request', {p_target: t.dataset.frAdd}); if(error) throw error; showToast(data==='accepted' ? TX('toast.you-re-now-friends') : (data==='already_friends' ? TX('toast.already-friends') : TX('toast.friend-request-sent')), 'ok'); });
    if(t.dataset.frAccept) return run(async ()=>{ const { error } = await sbClient.rpc('respond_friend_request', {p_id: t.dataset.frAccept, p_accept: true}); if(error) throw error; }, '👥 Friend added!');
    if(t.dataset.frDecline) return run(async ()=>{ const { error } = await sbClient.rpc('respond_friend_request', {p_id: t.dataset.frDecline, p_accept: false}); if(error) throw error; });
    if(t.dataset.frRemove) return run(()=> socialRemove(t.dataset.frRemove));
    if(t.dataset.frInvite) return openInviteModal(t.dataset.frInvite);
    if(t.dataset.frMenu){
      const id = t.dataset.frMenu; const p = Registry.users._cache.get(id) || {};
      const choice = prompt(TX('dialog.type-remove-to-unfriend-or-block', {v1: p.display_name||'Player'}));
      if(!choice) return;
      if(/^remove$/i.test(choice.trim()) && confirm(TX('dialog.remove-from-your-friends', {v1: p.display_name||'this player'}))) return run(()=> socialRemove(id), 'Removed.');
      if(/^block$/i.test(choice.trim()) && confirm(TX('dialog.block-they-won-t-be-able', {v1: p.display_name||'this player'}))) return run(async ()=>{ const { error } = await sbClient.rpc('block_player', {p_target: id}); if(error) throw error; }, 'Blocked.');
    }
  };
}
async function socialRemove(otherId){
  const r = Social.rows.find(r=> (r.requester_id===otherId && r.addressee_id===cloudUserId) || (r.addressee_id===otherId && r.requester_id===cloudUserId));
  if(!r) return;
  const { error } = await sbClient.from('friendships').delete().eq('id', r.id); if(error) throw error;
}
/* ---------- Private match invites ---------- */
function liveBattleModes(){ return Registry.battleModes().filter(m=> m.live!==false); }
let inviteSettings = {battleMode: null};
function openInviteModal(friendId){
  const p = Registry.users._cache.get(friendId) || {display_name:'your friend'};
  const overlay = document.getElementById('authGateOverlay'); if(!overlay) return;
  const modes = liveBattleModes();
  if(!inviteSettings.battleMode || !modes.some(m=>m.id===inviteSettings.battleMode)) inviteSettings.battleMode = modes[0] ? modes[0].id : Registry.defaultBattleMode();
  const std = standardFormatOn(), inviteDeck = std ? loadStandardDeck() : myDeckCounts;
  const deckOk = deckTotal(inviteDeck)===DECK_SIZE;
  const modeHTML = ()=> modes.map(m=> `<button type="button" class="tk-speed-btn ${m.id===inviteSettings.battleMode?'is-on':''}" role="radio" aria-checked="${m.id===inviteSettings.battleMode}" data-inv-mode="${m.id}">${m.icon} ${escapeHtml(m.label)}</button>`).join('');
  overlay.innerHTML = `<div class="modal invite-modal" role="dialog" aria-labelledby="invTitle">
    <div class="modal-head-row"><h2 id="invTitle">⚔️ Invite ${escapeHtml(p.display_name||'friend')}</h2><button class="modal-close-btn" id="invClose" aria-label="Close">✕</button></div>
    <p class="panel-sub">A private, friendly match — no rating change.</p>
    <div class="inv-field"><div class="inv-label">Arena type</div><div class="tk-seg inv-modes" role="radiogroup" aria-label="Arena type">${modeHTML()}</div>
      <p class="inv-blurb" id="invBlurb">${escapeHtml((Registry.battleMode(inviteSettings.battleMode)||{}).blurb||'')}</p></div>
    <div class="inv-field"><div class="inv-label">Your deck</div><div class="inv-deck ${deckOk?'':'is-bad'}">${deckOk ? `✅ ${std?'🃏 Standard deck (all Level 1)':'Active deck'} · ${DECK_SIZE} cards` : `⚠️ Your ${std?'Standard ':''}deck has ${deckTotal(inviteDeck)} cards — it needs exactly ${DECK_SIZE}. Fix it in Deck first.`}</div></div>
    <div class="auth-actions"><button type="button" class="btn" id="invCancel">Cancel</button><button type="button" class="btn primary" id="invSend" ${deckOk?'':'disabled'}>Send invite</button></div>
  </div>`;
  overlay.hidden = false;
  const close = ()=>{ overlay.hidden = true; overlay.innerHTML = ''; };
  document.getElementById('invClose').onclick = close; document.getElementById('invCancel').onclick = close;
  overlay.onclick = e=>{ if(e.target===overlay) close(); };
  overlay.querySelectorAll('[data-inv-mode]').forEach(b=> b.onclick = ()=>{
    inviteSettings.battleMode = b.dataset.invMode;
    overlay.querySelectorAll('[data-inv-mode]').forEach(x=>{ x.classList.toggle('is-on', x===b); x.setAttribute('aria-checked', x===b); });
    document.getElementById('invBlurb').textContent = (Registry.battleMode(inviteSettings.battleMode)||{}).blurb||'';
  });
  document.getElementById('invSend').onclick = async ()=>{
    const btn = document.getElementById('invSend'); btn.disabled = true;
    try{
      const { data, error } = await sbClient.rpc('send_match_invite', {p_to: friendId, p_settings: {battleMode: inviteSettings.battleMode, friendly: true, format: std ? 'standard' : 'collection'}, p_deck: publicDeck(inviteDeck), p_character: myCharacterId, p_leader: matchLeaderId() || null});
      if(error) throw error;
      Social.outgoingInvite = data; close();
      showToast(TX('toast.invite-sent-to', {v1: p.display_name||'your friend'}), 'ok');
      if(currentTab==='friends') renderFriends();
      pollMyInvite();
    }catch(err){ btn.disabled = false; showToast(socialErrText(err), 'error'); }
  };
}
// Realtime normally tells us when the invite is answered; this poll is the backup.
let myInvitePoll = null;
function pollMyInvite(){
  clearTimeout(myInvitePoll);
  const inv = Social.outgoingInvite; if(!inv || !sbClient) return;
  myInvitePoll = setTimeout(async ()=>{
    try{ const { data } = await sbClient.from('match_invites').select('*').eq('id', inv.id).maybeSingle(); if(data) await onMyInviteUpdated(data); }catch(e){}
    if(Social.outgoingInvite && Social.outgoingInvite.id===inv.id) pollMyInvite();
  }, 4000);
}
async function onMyInviteUpdated(inv){
  if(!inv || !Social.outgoingInvite || inv.id!==Social.outgoingInvite.id || inv.status==='pending') return;
  Social.outgoingInvite = null; clearTimeout(myInvitePoll);
  const name = ((Registry.users._cache.get(inv.to_id)||{}).display_name) || 'Your friend';
  if(inv.status==='accepted' && inv.match_id){
    const { data: row } = await sbClient.from('live_matches').select('*').eq('id', inv.match_id).maybeSingle();
    if(row){ showToast(TX('toast.accepted-match-starting', {name}), 'ok'); switchTab('play'); await enterLiveMatch(row); return; }
  }
  if(inv.status==='declined') showToast(TX('toast.declined-the-invite', {name}));
  if(inv.status==='expired') showToast(TX('toast.your-invite-expired'));
  if(currentTab==='friends') renderFriends();
}
async function cancelMyInvite(){
  const inv = Social.outgoingInvite; if(!inv) return;
  Social.outgoingInvite = null; clearTimeout(myInvitePoll);
  try{ await sbClient.rpc('cancel_match_invite', {p_id: inv.id}); }catch(e){}
  if(currentTab==='friends') renderFriends();
}
async function socialLoadInvites(){
  if(!Social.ready) return;
  const since = new Date(Date.now() - 15*60000).toISOString();
  const { data } = await sbClient.from('match_invites').select('*').eq('to_id', cloudUserId).eq('status','pending').gte('created_at', since).order('created_at', {ascending:false});
  Social.incomingInvites = data || [];
  await Registry.users.get(Social.incomingInvites.map(i=>i.from_id));
  refreshFriendsBadge();
  showInviteBanner();
}
function showInviteBanner(){
  const inv = Social.incomingInvites[0];
  if(!inv || (matchState && !matchState.over)){ hideInviteBanner(); return; }
  let el = document.getElementById('inviteBanner');
  if(!el){ el = document.createElement('div'); el.id = 'inviteBanner'; el.className = 'invite-banner'; el.setAttribute('role','alert'); document.body.appendChild(el); try{ fxHook('banner', el); }catch(e){} } // fxHook: 2026-10-15 batch F
  const from = (Registry.users._cache.get(inv.from_id)||{}).display_name || 'A friend';
  const mode = Registry.battleMode((inv.settings||{}).battleMode) || Registry.battleMode(Registry.defaultBattleMode());
  el.innerHTML = `<span class="ib-text">⚔️ <b>${escapeHtml(from)}</b> invites you to a friendly match · ${mode?mode.icon+' '+escapeHtml(mode.label):''}${(inv.settings||{}).format==='standard'?' · 🃏 Standard':''}</span>
    <span class="ib-actions"><button type="button" class="btn small primary" id="ibAccept">Accept</button><button type="button" class="btn small" id="ibDecline">Decline</button></span>`;
  el.hidden = false;
  document.getElementById('ibDecline').onclick = async ()=>{ try{ await sbClient.rpc('respond_match_invite', {p_id: inv.id, p_accept: false, p_deck: {}, p_character: null, p_leader: null}); }catch(e){} Social.incomingInvites.shift(); showInviteBanner(); refreshFriendsBadge(); };
  document.getElementById('ibAccept').onclick = async ()=>{
    const invStd = (inv.settings||{}).format==='standard', accDeck = invStd ? loadStandardDeck() : myDeckCounts;
    if(deckTotal(accDeck)!==DECK_SIZE){ showToast(TX('toast.your-deck-needs-exactly-cards-to', {v1: invStd?'Standard ':'', DECK_SIZE}), 'error'); if(invStd) openStandardDeckBuilder(); return; }
    const b = document.getElementById('ibAccept'); b.disabled = true;
    try{
      const { data: row, error } = await sbClient.rpc('respond_match_invite', {p_id: inv.id, p_accept: true, p_deck: publicDeck(accDeck), p_character: myCharacterId, p_leader: matchLeaderId() || null});
      if(error) throw error;
      Social.incomingInvites = []; hideInviteBanner(); refreshFriendsBadge();
      switchTab('play'); await enterLiveMatch(row);
    }catch(err){ b.disabled = false; showToast(socialErrText(err), 'error'); Social.incomingInvites.shift(); showInviteBanner(); }
  };
}
function hideInviteBanner(){ const el = document.getElementById('inviteBanner'); if(el) el.hidden = true; }
/* ---------- Public Market (Shop → Market tab) ---------- */
const MARKET_FEE = 0.05; // 5% of each sale is burned as a fee
const Market = Object.assign({tab:'browse', q:'', rarity:'', sort:'cheap', listings:null, mine:null, loading:false, sellId:'', sellPrice:20, sellCurrency:'gold'}, (()=>{ const o = uiSticky('market'), out = {}; ['q', 'rarity', 'sort'].forEach(k=>{ if(typeof o[k] === 'string') out[k] = o[k]; }); return out; })()); // 2026-10-16: filters kept
function marketCurrencies(){ return Object.keys(CURRENCY_META).filter(k=> k==='gold' || k==='gems').map(k=> Object.assign({id:k}, CURRENCY_META[k])); }
function priceHTML(price, cur){ const c = CURRENCY_META[cur] || {}; return `<span class="mk-price" title="${escapeAttr(c.label||cur)}">${c.glyph||''} ${price}</span>`; }
async function marketLoad(){
  if(!sbClient){ Market.listings = []; return; }
  Market.loading = true;
  try{
    let q = sbClient.from('market_listings').select('*').eq('status','active');
    q = Market.sort==='new' ? q.order('created_at', {ascending:false}) : q.order('price', {ascending: Market.sort!=='dear'});
    const { data, error } = await q.limit(200); if(error) throw error;
    Market.listings = data || []; Market.error = null;
    await Registry.users.get(Market.listings.map(l=>l.seller_id));
    if(isSignedIn()){
      const { data: mine } = await sbClient.from('market_listings').select('*').eq('seller_id', cloudUserId).order('created_at', {ascending:false}).limit(60);
      Market.mine = mine || [];
      await marketClaimProceeds();
    }
  }catch(err){ Market.listings = []; Market.error = socialErrText(err); }
  Market.loading = false;
}
// The seller's share after the fee, in whole Leaves: floor(price × 95 / 100), at least 1. Integer maths, so it is exactly the
// number claim_market_proceeds credits on the server (20261017_market_server_settlement.sql).
function marketNet(price){ return Math.max(1, Math.floor((Math.floor(Number(price)||0) * Math.round((1-MARKET_FEE)*100)) / 100)); }
// 2026-10-17 (security): the market settles on the server (buy_listing_v2 takes the price, claim_market_proceeds credits the
// seller). Until that migration is applied the v2 functions don't exist, so each call falls back to the old one.
const marketV2Missing = {};
function rpcMissing(err){ const code = String((err && err.code) || ''), msg = String((err && (err.message || err.details)) || ''); return code === 'PGRST202' || code === '42883' || /could not find the function/i.test(msg); }
async function rpcV2(name, args){
  if(!marketV2Missing[name]){
    const r = await sbClient.rpc(name + '_v2', args);
    if(!r.error || !rpcMissing(r.error)) return r;
    marketV2Missing[name] = true;
  }
  return sbClient.rpc(name, args);
}
function marketErrText(err){
  const raw = String((err && (err.message || err.details)) || '');
  if(/you do not own this card/i.test(raw)) return 'The market can’t see this card in your saved collection yet. Wait a moment for it to sync, then try again.';
  if(/not enough leaves/i.test(raw)) return 'The market says you don’t have enough Leaves saved. Wait a moment for your balance to sync, then try again.';
  if(/price out of range/i.test(raw)) return 'Pick a price from 1 to 100,000.';
  if(/sign in required|not authenticated/i.test(raw)) return 'Sign in to use the Flea Market.';
  return socialErrText(err);
}
async function marketClaimProceeds(){
  try{
    // After the migration the server credits the seller inside this same call; the browser adds the same amount, so the two
    // balances stay equal (and the next save sends no gain at all).
    const { data, error } = await sbClient.rpc('claim_market_proceeds'); if(error) throw error;
    (data||[]).forEach(l=>{ const net = marketNet(l.price); grantCurrency(l.currency, net); const d = Registry.card(l.card_id); showToast(TX('toast.sold-for', {v1: d?d.name:'a card', net, v3: (CURRENCY_META[l.currency]||{}).label||l.currency}), 'ok'); });
  }catch(e){}
}
function marketBrowseHTML(){
  if(Market.error) return `<p class="fr-empty">${escapeHtml(Market.error)}</p>`;
  if(Market.loading || Market.listings===null) return '<p class="fr-empty">Loading the market…</p>';
  const q = Market.q.trim().toLowerCase();
  const rows = Market.listings.filter(l=>{ const d = Registry.card(l.card_id); return d && (!q || d.name.toLowerCase().includes(q)) && (!Market.rarity || d.rarity===Market.rarity); });
  if(!rows.length) return `<p class="fr-empty">${Market.listings.length ? 'No listings match your filters.' : 'Nothing for sale yet — be the first to list a card from the Sell tab.'}</p>`;
  return `<div class="mk-grid">${rows.map(l=>{
    const d = Registry.card(l.card_id); const mine = l.seller_id===cloudUserId; const seller = (Registry.users._cache.get(l.seller_id)||{}).display_name || 'Player';
    const afford = (myCurrencies[l.currency]||0) >= l.price;
    return `<div class="mk-item">${cardTileHTML(d, {inPlay:true})}${l.foil?'<div class="mk-foil">✨ Foil</div>':''}
      <div class="mk-meta">${priceHTML(l.price, l.currency)}<span class="mk-seller">by ${escapeHtml(seller)}</span></div>
      ${mine ? '<button type="button" class="btn small" disabled>Your listing</button>' : `<button type="button" class="btn small primary" data-mk-buy="${l.id}" ${afford||!isSignedIn()?'':'disabled'} title="${afford?'':'Not enough '+escapeAttr((CURRENCY_META[l.currency]||{}).label||'')}">Buy</button>`}
    </div>`; }).join('')}</div>`;
}
function ownedForSale(){
  return Object.keys(myCardCopies).filter(id=> (myCardCopies[id]||[]).length>0 && Registry.card(id)).sort((a,b)=> Registry.card(a).name.localeCompare(Registry.card(b).name));
}
function marketSellHTML(){
  if(!isSignedIn()) return `<p class="fr-empty">Sign in to sell cards.</p><button type="button" class="btn primary" id="mkSignIn">Sign in</button>`;
  const owned = ownedForSale();
  if(!owned.length) return '<p class="fr-empty">You don’t own any cards to sell yet. Cards you win or open in packs show up here.</p>';
  if(!Market.sellId || !owned.includes(Market.sellId)) Market.sellId = owned[0];
  const copies = myCardCopies[Market.sellId]||[]; const d = Registry.card(Market.sellId);
  const inDeck = (myDeckCounts[Market.sellId]||0) > 0 && copies.length<=1;
  return `<form class="mk-sell" id="mkSellForm">
    <label class="inv-label" for="mkSellCard">Card</label>
    <select id="mkSellCard">${owned.map(id=>`<option value="${escapeAttr(id)}" ${id===Market.sellId?'selected':''}>${escapeHtml(Registry.card(id).name)} (×${myCardCopies[id].length})</option>`).join('')}</select>
    <div class="mk-sell-preview">${cardTileHTML(d, {inPlay:true})}</div>
    ${inDeck ? '<p class="inv-deck is-bad">⚠️ This is your only copy and it’s in your deck — selling it removes it from your collection.</p>' : ''}
    <div class="mk-sell-row">
      <label>Price <input type="number" id="mkSellPrice" min="1" max="100000" value="${Market.sellPrice}"></label>
      <label>Currency <select id="mkSellCur">${marketCurrencies().map(c=>`<option value="${c.id}" ${c.id===Market.sellCurrency?'selected':''}>${escapeHtml(c.label)}</option>`).join('')}</select></label>
    </div>
    <p class="tk-hint" id="mkNet">You’ll receive ${marketNet(Market.sellPrice)} after the ${Math.round(MARKET_FEE*100)}% market fee. The card leaves your collection while it’s listed; cancel any time to get it back.</p>
    <button type="submit" class="btn primary">List for sale</button>
  </form>`;
}
function marketMineHTML(){
  if(!isSignedIn()) return '<p class="fr-empty">Sign in to see your listings.</p>';
  const mine = Market.mine||[];
  if(!mine.length) return '<p class="fr-empty">You haven’t listed anything yet.</p>';
  const label = {active:'For sale', sold:'Sold', cancelled:'Cancelled'};
  return mine.map(l=>{ const d = Registry.card(l.card_id) || {name:l.card_id, icon:'❔'};
    return `<div class="fr-row"><div class="fr-avatar">${cardIcoHTML(d)}</div><div class="fr-main"><div class="fr-name">${escapeHtml(d.name)}${l.foil?' ✨':''}</div><div class="fr-sub">${label[l.status]||l.status} · ${priceHTML(l.price, l.currency)}${l.status==='sold'?' · '+relTime(l.sold_at):''}</div></div>
      <div class="fr-actions">${l.status==='active'?`<button type="button" class="btn small" data-mk-cancel="${l.id}">Cancel</button>`:''}</div></div>`; }).join('');
}
function renderFleaMarket(){
  const root = document.getElementById('view-market'); if(!root) return;
  root.innerHTML = `<div class="panel mk-panel"><h2>🧺 Flea Market</h2>
      <p class="panel-sub">Buy cards from other players and sell the ones you don't need.</p>
      <div class="forge-currency-row" id="shopCurrencyRow">${shopCurrencyRowInnerHTML()}</div></div>
    <div id="marketMount"></div>`;
  const mount = document.getElementById('marketMount');
  renderMarketInto(mount);
  marketLoad().then(()=>{ if(currentTab==='market' && document.getElementById('marketMount')===mount) renderMarketInto(mount); });
}
function renderMarketInto(body){
  body.innerHTML = `<div class="panel mk-panel">
    <div class="mk-tabs tk-seg" role="tablist">
      ${[['browse','🛍️ Browse'],['sell','🏷️ Sell'],['mine','📋 My listings']].map(([k,l])=>`<button type="button" class="tk-speed-btn ${Market.tab===k?'is-on':''}" role="tab" aria-selected="${Market.tab===k}" data-mk-tab="${k}">${l}</button>`).join('')}
    </div>
    ${Market.tab==='browse' ? `<div class="mk-filters">
      <input type="search" id="mkQ" placeholder="Search cards…" value="${escapeAttr(Market.q)}" aria-label="Search cards">
      <select id="mkRarity" aria-label="Rarity"><option value="">All rarities</option>${Registry.rarities().map(r=>`<option value="${escapeAttr(r.key)}" ${Market.rarity===r.key?'selected':''}>${escapeHtml(r.label)}</option>`).join('')}</select>
      <select id="mkSort" aria-label="Sort"><option value="cheap" ${Market.sort==='cheap'?'selected':''}>Cheapest first</option><option value="dear" ${Market.sort==='dear'?'selected':''}>Priciest first</option><option value="new" ${Market.sort==='new'?'selected':''}>Newest first</option></select>
    </div><div id="mkBody">${marketBrowseHTML()}</div>` : Market.tab==='sell' ? `<div id="mkBody">${marketSellHTML()}</div>` : `<div id="mkBody">${marketMineHTML()}</div>`}
  </div>`;
  body.onclick = async e=>{
    const t = e.target.closest('button'); if(!t) return;
    if(t.dataset.mkTab){ Market.tab = t.dataset.mkTab; renderMarketInto(body); return; }
    if(t.id==='mkSignIn'){ requireSignIn('to use the Flea Market', ()=>{ renderFleaMarket(); }); return; }
    if(t.dataset.mkBuy){
      if(!isSignedIn()){ requireSignIn('to buy from the Flea Market', ()=>{ renderFleaMarket(); }); return; }
      const l = (Market.listings||[]).find(x=>x.id===t.dataset.mkBuy); if(!l) return;
      const d = Registry.card(l.card_id);
      if((myCurrencies[l.currency]||0) < l.price){ showToast((TX('toast.not-enough') + ' ')+((CURRENCY_META[l.currency]||{}).label||l.currency)+'.', 'error'); return; }
      if(!confirm(TX('dialog.buy-for', {v1: d?d.name:'this card', price: l.price, v3: (CURRENCY_META[l.currency]||{}).label||''}))) return;
      t.disabled = true;
      try{
        // buy_listing_v2 takes the price on the server; the browser takes the same price here, so both balances agree.
        // "Not enough Leaves" from the server usually means this browser's last save hasn't landed yet: save, then try once more.
        let { error } = await rpcV2('buy_listing', {p_id: l.id});
        if(error && /not enough leaves/i.test(String(error.message||''))){ await cloudPushCurrencies(); ({ error } = await rpcV2('buy_listing', {p_id: l.id})); }
        if(error) throw error;
        myCurrencies[l.currency] = (myCurrencies[l.currency]||0) - l.price; saveCurrencies();
        unlockCardForPlayer(l.card_id, 'market');
        if(l.foil){ const c = myCardCopies[l.card_id]; if(c && c.length){ c[c.length-1].foil = true; saveCardCopies(); } }
        showToast(TX('toast.bought-it-s-in-your-nest', {v1: d?d.name:'a card'}), 'ok');
        await marketLoad(); renderMarketInto(body); { const row = document.getElementById('shopCurrencyRow'); if(row) row.innerHTML = shopCurrencyRowInnerHTML(); }
      }catch(err){ t.disabled = false; showToast(marketErrText(err), 'error'); await marketLoad(); renderMarketInto(body); }
      return;
    }
    if(t.dataset.mkCancel){
      t.disabled = true;
      try{
        const { data, error } = await sbClient.rpc('cancel_listing', {p_id: t.dataset.mkCancel}); if(error) throw error;
        if(!myCardCopies[data.card_id]) myCardCopies[data.card_id] = [];
        myCardCopies[data.card_id].push({foil: !!data.foil}); saveCardCopies();
        showToast(TX('toast.listing-cancelled-the-card-is-back'));
        await marketLoad(); renderMarketInto(body);
      }catch(err){ t.disabled = false; showToast(socialErrText(err), 'error'); }
    }
  };
  const q = document.getElementById('mkQ'); if(q) q.oninput = ()=>{ Market.q = q.value; uiStickySave('market', {q: Market.q}); document.getElementById('mkBody').innerHTML = marketBrowseHTML(); };
  const r = document.getElementById('mkRarity'); if(r) r.onchange = ()=>{ Market.rarity = r.value; uiStickySave('market', {rarity: Market.rarity}); document.getElementById('mkBody').innerHTML = marketBrowseHTML(); };
  const so = document.getElementById('mkSort'); if(so) so.onchange = async ()=>{ Market.sort = so.value; uiStickySave('market', {sort: Market.sort}); await marketLoad(); renderMarketInto(body); };
  const card = document.getElementById('mkSellCard'); if(card) card.onchange = ()=>{ Market.sellId = card.value; renderMarketInto(body); };
  const price = document.getElementById('mkSellPrice'); if(price) price.oninput = ()=>{ Market.sellPrice = Math.max(1, Math.floor(Number(price.value)||1)); const n = document.getElementById('mkNet'); if(n) n.firstChild && (n.textContent = `You’ll receive ${marketNet(Market.sellPrice)} after the ${Math.round(MARKET_FEE*100)}% market fee. The card leaves your collection while it’s listed; cancel any time to get it back.`); };
  const cur = document.getElementById('mkSellCur'); if(cur) cur.onchange = ()=>{ Market.sellCurrency = cur.value; };
  const form = document.getElementById('mkSellForm');
  if(form) form.onsubmit = async e=>{
    e.preventDefault();
    const id = Market.sellId; const copies = myCardCopies[id]||[]; if(!copies.length) return;
    const btn = form.querySelector('button[type=submit]'); btn.disabled = true;
    // Sell a non-foil copy when there is one; foils only when that's all you have.
    let idx = copies.findIndex(c=>!c.foil); if(idx<0) idx = 0;
    try{
      // create_listing_v2 checks the card is in the saved collection (player_card_unlocks). If this browser's unlocks haven't
      // been saved yet, save them and try once more. Listing still takes the copy out of the collection here (cancel gives
      // it back), as before; the server only checks ownership.
      const args = {p_card: id, p_foil: !!copies[idx].foil, p_price: Market.sellPrice, p_currency: Market.sellCurrency};
      let { error } = await rpcV2('create_listing', args);
      if(error && /you do not own this card/i.test(String(error.message||''))){ await cloudPushCardLevels(); ({ error } = await rpcV2('create_listing', args)); }
      if(error) throw error;
      copies.splice(idx, 1); saveCardCopies();
      showToast(TX('toast.listed-for', {v1: Registry.card(id).name, sellPrice: Market.sellPrice}), 'ok');
      Market.tab = 'mine'; await marketLoad(); renderMarketInto(body);
    }catch(err){ btn.disabled = false; showToast(marketErrText(err), 'error'); }
  };
}

// 2026-10-03 (explicit: "the player MUST complete tutorial to continue"): until the tutorial is
// won, the only places open are Home (which offers it), Profile (sign-in) and Admin for admins.
const TUTORIAL_FREE_TABS = new Set(['home','profile','admin']);
function tutorialGateBlocks(tab){
  if(loadTutorialDone() || TUTORIAL_FREE_TABS.has(tab)) return false;
  if(tab==='play' && matchState && matchState.mode==='tutorial') return false;
  if(adminModeEnabled || devModeEnabled) return false;
  return true;
}
