// Leaf sweep (2026-10-07, second rework — user: "the leaves rush (smooth) to the middle of the
// screen then to the right... space the leaves out randomly, or in a wave like pattern... smoothly
// interpolate from edge -20% to the other edge +10%"). Each leaf now travels at an even pace from
// 20% past the left edge to 10% past the right edge — no mid-screen waypoint everyone converges on.
// Its height rides a gentle sine wave (its own amplitude, wavelength and phase), the leaves start at
// random moments over ~0.7 s and at random heights, and each tumbles at its own rate. Keyframes are
// computed here and played with the Web Animations API on transform/opacity only (compositor).
function leafSweep(){
  if(!fxAtLeast('low')) return;
  if(document.querySelector('#editorOverlay:not([hidden]) .modal, #skirmishEditorOverlay:not([hidden]) .modal')) return; // never over an open editor
  const glyphs = ['🍂','🍁','🍃','🍂','🍁','🌿','🍃','🍂','🍁'];
  const n = fxLevel() === 'low' ? 5 : glyphs.length;
  const f = document.createElement('div'); f.className = 'leaf-sweep'; f.setAttribute('aria-hidden', 'true');
  f.innerHTML = '<span class="ls-veil"></span>';
  document.body.appendChild(f);
  const W = innerWidth, H = innerHeight, STEPS = 10;
  let longest = 0;
  for(let i = 0; i < n; i++){
    const leaf = document.createElement('i'); leaf.textContent = glyphs[i % glyphs.length];
    leaf.style.fontSize = (22 + Math.random()*20).toFixed(0) + 'px';
    f.appendChild(leaf);
    const y0 = H * (0.08 + 0.84 * ((i + Math.random()*0.8) / n));   // spread down the screen, jittered
    const amp = H * (0.03 + Math.random()*0.05), waves = 0.8 + Math.random()*1.0, phase = Math.random()*Math.PI*2;
    const drift = H * (Math.random()*0.10 - 0.03);                     // a slight overall sink or rise
    const r0 = Math.random()*360, spin = (Math.random() < .5 ? -1 : 1) * (200 + Math.random()*260);
    const x0 = -0.20*W, x1 = 1.10*W;
    const frames = [];
    for(let k = 0; k <= STEPS; k++){
      const t = k / STEPS;
      const x = x0 + (x1 - x0) * t;
      const y = y0 + drift * t + amp * Math.sin(phase + t * waves * Math.PI * 2);
      const op = t < 0.08 ? t / 0.08 : t > 0.9 ? (1 - t) / 0.1 : 1;
      frames.push({transform:`translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) rotate(${(r0 + spin*t).toFixed(1)}deg)`, opacity: op.toFixed(2)});
    }
    const dur = 1500 + Math.random()*700, delay = Math.random()*700;
    longest = Math.max(longest, dur + delay);
    try{ leaf.animate(frames, {duration: dur, delay, easing: 'linear', fill: 'both'}); }catch(e){ leaf.remove(); }
  }
  setTimeout(()=> f.remove(), longest + 120);
}
function placeOverlay(cls, html, ms){
  const f = document.createElement('div'); f.className = cls; f.setAttribute('aria-hidden','true'); f.innerHTML = html || '';
  document.body.appendChild(f); setTimeout(()=> f.remove(), ms || 900);
}
const PLACES = {
  deck: {cls:'tent-scene', icon:'⛺', sign:'Camp', ambience:'tent', enter: ()=> placeOverlay('tent-flaps', '<i></i><i></i>', 900)},
  shop: {cls:'cart-scene', icon:'🧳', get sign(){ return shopsTitle(); }, ambience:'cart', enter: ()=>{ placeOverlay('cart-awning', '', 900); try{ SoundKit.pitchChime && SoundKit.pitchChime(); }catch(e){} }},
  market: {cls:'flea-scene', icon:'🧺', sign:'Flea Market', ambience:'cart', enter: ()=>{}},
  nest: {cls:'nest-scene', icon:'🪺', sign:'The Nest', ambience:'nest', enter: ()=> placeOverlay('nest-down', Array.from({length:14}, (_, k)=> `<i style="left:${(k*53)%96 + 2}%; animation-delay:${(k*97)%600}ms; animation-duration:${1800 + (k*131)%1200}ms"></i>`).join(''), 3200)},
};
var tabSwitchSeq = 0; // counts screen changes (renderPlay tells a fresh arrival from a redraw)
function switchTab(tab){
  tabSwitchSeq++;
  if(tab !== (typeof currentTab!=='undefined' ? currentTab : null)) forgeReadyUsed = false; // the Forge's one-shot "Show the N I can temper" comes back on a new visit
  if(tab !== 'play') try{ caveScreenOff(); }catch(e){}
  if(typeof currentTab!=='undefined' && currentTab==='deck' && tab!=='deck' && deckDirty){ deckLeaveGuard(()=> switchTab(tab)); return; }
  if(typeof currentTab!=='undefined' && currentTab==='deck' && tab!=='deck') endDeckDraft();
  currentTabBeforeSwitch = (typeof currentTab!=='undefined') ? currentTab : null;
  // 2026-10-15 (user: "Forge is not a submenu of Codex" + "I pressed codex and it went to Forge"): the Forge is its own page that
  // happens to be drawn in the Codex view, so leaving it forgets it; the next plain visit to the Codex opens Browse.
  let leftForge = false;
  if(currentTabBeforeSwitch === 'codex' && tab !== 'codex' && codexSubTab === 'forge'){ codexSubTab = 'browse'; leftForge = true; }
  // Shop's back button (2026-10-12, user: "Shop should have a back button - to go back to the conquest map if that's where you
  // were before"): remember where the Shop was opened from.
  if(tab === 'shop' && currentTabBeforeSwitch && currentTabBeforeSwitch !== 'shop') shopCameFrom = {tab:currentTabBeforeSwitch, sub: (typeof playSubTab!=='undefined' ? playSubTab : null), map: (typeof conquestSelectedMap!=='undefined' ? conquestSelectedMap : null)};
  if(tutorialGateBlocks(tab)){ showToast(TX('toast.finish-the-tutorial-first-it-only')); tab = 'home'; }
  try{ document.body.dataset.tab = tab; }catch(e){}
  if(tab!=='play') exitConquestImmersive();
  if(tab!=='home' && tab!=='play' && !tabOpen(tab)){ showToast(TX('toast.that-opens-up-later-keep-pushing')); tab = 'play'; playSubTab = 'conquest'; }
  // 2026-10-08 (user: "the deck editor should land on the Manage decks page first"): entering Deck
  // shows the deck list, unless a button asked to open the builder directly (deckOpenBuilderOnce).
  if(tab!=='play' || playSubTab!=='conquest') document.body.classList.remove('cq-node-focus');
  if(tab!=='play'){ const aw = document.getElementById('appWrap'); if(aw) aw.classList.remove('cq-hud', 'cq-no-tabs'); document.body.classList.remove('conquest-full', 'play-full'); }
  if(tab==='deck' && currentTabBeforeSwitch!=='deck'){ try{ deckHeroView = false; }catch(e){} }
  if(tab!=='deck' && currentTabBeforeSwitch==='deck'){ try{ restoreMainDeck(); }catch(e){} }
  if(tab==='deck' && currentTabBeforeSwitch!=='deck'){ if(!deckOpenBuilderOnce){ deckShowList = true; deckEditingId = null; } deckOpenBuilderOnce = false; }
  currentTab = tab;
  // Ambience: Home has its own meadow; Play sets the place's sound from its map/battle; the
  // menu-like tabs (Deck, Shop, Codex...) are indoors, so the outdoor sound fades away.
  // Places (immersion #4): some screens are places you walk into, each with its own look, sound
  // and entrance — the Armoury Tent (Deck), the Traveller's Cart (Shop), the Old Nest (Nest).
  try{
    const place = PLACES[tab];
    if(tab==='home') Ambience.play('home'); else if(place) Ambience.play(place.ambience); else if(tab!=='play') Ambience.stop();
    Object.entries(PLACES).forEach(([t, pl])=>{ const v = document.getElementById('view-' + t); if(v){ v.classList.add(pl.cls); v.dataset.sign = pl.icon + ' ' + (window.i18 ? i18(pl.sign) : pl.sign); } });
    const reduced = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
    // 2026-10-08 (user: "Clicking play or any other button should instantly transit you"): no entrance
    // that covers the new screen (the tent flaps and cart awning hid it for ~0.8 s). Only the Nest's
    // drifting down remains, and it never covers anything.
    // 2026-10-08 (user: "I like how the Hall of Fame and Deleted sections transition in/out ... make the rest like
    // that. Forge's transition is too exaggerated"): every screen change is now the Codex's quick page turn (forward
    // when moving right along the menu, back when moving left). The leaf gust and the Nest's falling down are retired.
    if(currentTabBeforeSwitch && currentTabBeforeSwitch!==tab && !reduced && !matchState && tab!=='play'){
      const ORDER = ['home','play','deck','nest','shop','market','codex','profile','achievements','ranking','admin'];
      // 2026-10-10 (user: "When I click Home from Conquest, the Home background loads up, but at the wrong size, and it has to
      // resize"): a transform on #view-home turned the fixed, full-screen Home scene into a box the size of the view for the
      // length of the turn, then it snapped to the screen. Home turns its menu instead, so the scene is full size from the start.
      const v = tab==='home' ? document.querySelector('#view-home .home-menu') : document.getElementById('view-' + tab), dir = ORDER.indexOf(tab) >= ORDER.indexOf(currentTabBeforeSwitch) ? 'fwd' : 'back';
      if(v){ v.classList.remove('view-turn-fwd','view-turn-back'); void v.offsetWidth; v.classList.add('view-turn-' + dir); setTimeout(()=> v.classList.remove('view-turn-' + dir), 420); }
    }
  }catch(e){}
  // In-page Back (2026-10-13, user: "Feature pages (Nest, Forge, etc.) need a prominent in-page Back button"; then "Make the Back
  // button more inline with the page itself ... on the same row as the title like 'Armoury', but on the far right? With no
  // text, just a return indicator. The Hero, Codex, Forge and Nest etc should have shortcuts to each other"): one row at the
  // top right of every page off the map: shortcuts to the other places you've opened, then ↩.
  { const FEATURE = !['home','play','admin'].includes(tab);
    if(FEATURE && currentTabBeforeSwitch && currentTabBeforeSwitch !== tab && !['admin'].includes(currentTabBeforeSwitch)) pageCameFrom = {tab:currentTabBeforeSwitch, sub: (typeof playSubTab!=='undefined' ? playSubTab : null), map: (typeof conquestSelectedMap!=='undefined' ? conquestSelectedMap : null), forge: leftForge};
    refreshPageBar(tab); }
  document.getElementById('view-home').hidden = tab!=='home';
  document.getElementById('view-codex').hidden = tab!=='codex';
  document.getElementById('view-play').hidden = tab!=='play';
  document.getElementById('view-deck').hidden = tab!=='deck';
  document.getElementById('view-shop').hidden = tab!=='shop';
  document.getElementById('view-nest').hidden = tab!=='nest';
  { const vm = document.getElementById('view-market'); if(vm) vm.hidden = tab!=='market'; }
  document.getElementById('view-profile').hidden = tab!=='profile';
  document.getElementById('view-ranking').hidden = tab!=='ranking';
  { const va = document.getElementById('view-achievements'); if(va) va.hidden = tab!=='achievements'; }
  { const vp = document.getElementById('view-paths'); if(vp) vp.hidden = tab!=='paths'; }
  { const vi = document.getElementById('view-inventory'); if(vi) vi.hidden = tab!=='inventory'; }
  { const vs = document.getElementById('view-stomp'); if(vs) vs.hidden = tab!=='stomp'; }
  document.getElementById('view-guild').hidden = tab!=='guild';
  { const vf = document.getElementById('view-friends'); if(vf) vf.hidden = tab!=='friends'; }
  document.getElementById('view-admin').hidden = tab!=='admin';
  // Reliability hardening (2026-09-24, same pass as the entrance-screen fix): each tab's
  // renderer is wrapped individually so a bug in ONE tab's render path (bad localStorage state,
  // a data-shape mismatch, whatever) can't throw out of switchTab() entirely and leave the rest
  // of this function -- the topbar visibility toggles below, the nav-button hidden states -- from
  // running. Previously an uncaught throw here would propagate straight up to whatever called
  // switchTab(), which for the entrance flow meant a permanently frozen splash screen (see
  // triggerEntranceAnimation's own hardening above) and for a normal in-app tab click meant a
  // dead nav bar. Now the tab area is left visible (hidden=false was already set above) even if
  // its content failed to render, which is a far more recoverable failure mode than a frozen UI.
  function safeRender(name, fn){ try{ fn(); }catch(e){ console.error('[Bramblewood] render'+name+'() failed:', e); } }
  if(tab==='home') safeRender('Home', renderHome);
  if(tab==='codex') safeRender('Codex', renderCodex);
  if(tab==='play') safeRender('Play', renderPlay);
  if(tab==='deck') safeRender('DeckSection', renderDeckSection);
  if(tab==='shop') safeRender('Shop', renderShop);
  if(tab==='nest') safeRender('Nest', renderNest);
  if(tab==='market') safeRender('FleaMarket', renderFleaMarket);
  if(tab==='profile') safeRender('Profile', renderProfile);
  if(tab==='ranking') safeRender('Ranking', renderRanking);
  if(tab==='achievements') safeRender('Achievements', renderAchievementsPage);
  if(tab==='inventory') safeRender('Inventory', renderInventory);
  // 2026-10-17 (user: "Stomping Grounds default: On load, load the main screen, not the last seen card."): coming in from another page
  // always opens the Stomping Grounds at its front (the top of the page, the Hero Hall), with no card close-up left open over it.
  if(tab==='stomp'){ if(currentTabBeforeSwitch !== 'stomp'){ try{ const cd = document.getElementById('cardDetailOverlay'); if(cd && !cd.hidden){ cd.hidden = true; cd.innerHTML = ''; cardDetailOpenId = null; } window.hideCardPop && window.hideCardPop(); }catch(e){} try{ window.scrollTo(0, 0); }catch(e){} } safeRender('Stomp', renderStomp); }
  if(tab==='paths') safeRender('Wildpaths', ()=>{ renderWildpaths.drawn = false; renderWildpaths(); });
  if(tab==='guild') safeRender('Guild', renderGuild);
  if(tab==='friends') safeRender('Friends', renderFriends);
  if(tab==='admin') safeRender('Admin', renderAdmin);
  safeRender('CommunityTabs', ()=> syncCommunityTabs(tab));
  // Task #94 (2026-09-16, "make the battleground significantly bigger, full on full
  // screen"): the wider layout only makes sense while an actual match is on screen, so it's
  // gated on being both on the Play tab AND mid-match, not just the tab alone.
  const wrap = document.getElementById('appWrap');
  if(wrap) wrap.classList.toggle('in-match', tab==='play' && !!matchState);
  // 2026-09-20: the old always-visible tab strip is gone (see renderHome's own comment) — the
  // topbar's Home button is the one persistent way back, so it hides itself while you're
  // already there instead of doing nothing when clicked.
  const homeBtn = document.getElementById('homeNavBtn');
  if(homeBtn) homeBtn.hidden = (tab==='home');
  try{ refreshTopbarDungeonKey(tab); }catch(e){} // 2026-10-16 (user: "the daily dungeon key logo ... beside HOME ... (same throughout)")
  // Item #275 (2026-09-20, "the header is unnecessary on the home page"... "Home button should
  // be renamed 'Back'... on the same line as the sub nav bar. Same for settings... the logo and
  // title name row can be left out of the header"): the Home page already has its own inline
  // brand mark + Settings button (renderHome's own #settingsBtnHome), and the Play tab's
  // sub-tab bar now carries its own Back/Settings pair too (see renderPlay's play-subtabs-row) —
  // so the global topbar (brand row + Home button + Settings gear) is pure duplication in both
  // places and hides itself entirely there. See the matching #appWrap.tab-home/.tab-play CSS.
  if(wrap){
    wrap.classList.toggle('tab-home', tab==='home');
    wrap.classList.toggle('tab-play', tab==='play');
  }
}
