const LIGHT_COLORS = {shock:[0.75, 0.85, 1], /* lightning (2026-10-16) */ heat:[1, 0.55, 0.18], cold:[0.45, 0.75, 1], poison:[0.5, 1, 0.35], acid:[0.75, 1, 0.3], decay:[0.6, 0.45, 0.8], physical:[1, 0.88, 0.62]};
